const files = {
  "prisma/schema.prisma": "// ============================================================\n// Al-Musnad (المسند) — Prisma Schema (Upgraded v3.0)\n// منصة المسند التربوية — تدعم المؤسسات، المتفقدين، المعلمين، التلاميذ، والمشرفين\n// ============================================================\n\ngenerator client {\n  provider        = \"prisma-client-js\"\n  previewFeatures = [\"fullTextSearchPostgres\"]\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ── Enums ────────────────────────────────────────────────────\n\nenum Role {\n  INSTITUTION\n  INSPECTOR\n  TEACHER\n  STUDENT\n  ADMIN\n}\n\nenum WorksheetStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\n/// جمهور النشر المستهدف الذي يحدده الناشر عند رفع المنشور\nenum TargetAudience {\n  ALL                   // متاح لجميع منتسبي المنصة\n  SAME_ROLE_ONLY        // متاح فقط لنفس فئة الناشر (معلم لمعلم / مؤسسة لمؤسسة / متفقد لمتفقد)\n  TEACHERS_ONLY         // خاص بالمعلمين والمتفقدين فقط (مثل: إصلاح الامتحانات، المذكرات، ودليل المعلم)\n  TEACHERS_AND_STUDENTS // متاح للمعلمين والتلاميذ معاً (مثل: التمارين وأوراق العمل التطبيقية)\n  INSTITUTIONS_ONLY     // خاص بالمؤسسات التربوية والإدارة فقط\n}\n\n/// حالة طلب تعديل الملف الشخصي (يتطلب موافقة المشرف العام)\nenum ProfileEditStatus {\n  NONE\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// ── Models ───────────────────────────────────────────────────\n\nmodel User {\n  id                 String            @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  email              String            @unique @db.VarChar(255)\n  name               String            @db.VarChar(255)\n  avatarUrl          String?           @map(\"avatar_url\") @db.Text\n  role               Role              @default(TEACHER)\n  school             String?           @db.VarChar(255)\n  bio                String?           @db.Text\n  subscriptionPlan   String            @default(\"STANDARD\") @map(\"subscription_plan\") @db.VarChar(50)\n  profileEditStatus  ProfileEditStatus @default(NONE) @map(\"profile_edit_status\")\n  pendingProfileData Json?             @map(\"pending_profile_data\")\n  followersCount     Int               @default(0) @map(\"followers_count\")\n  favoritedByCount   Int               @default(0) @map(\"favorited_by_count\")\n  inspectorPending   Boolean           @default(false) @map(\"inspector_pending\")\n  inspectorCode      String?           @unique @map(\"inspector_code\") @db.VarChar(32)\n  createdAt          DateTime          @default(now()) @map(\"created_at\") @db.Timestamptz()\n  updatedAt          DateTime          @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz()\n\n  // Relations\n  worksheets          Worksheet[]         @relation(\"UploadedWorksheets\")\n  endorsedWorksheets  Worksheet[]         @relation(\"EndorsedWorksheets\")\n  downloads           Download[]\n  favorites           Favorite[]\n  reviews             Review[]\n  followers           PublisherFollow[]   @relation(\"PublisherFollowers\")\n  following           PublisherFollow[]   @relation(\"UserFollowing\")\n  favoritedByUsers    FavoritePublisher[] @relation(\"PublisherFavoritedBy\")\n  favoritePublishers  FavoritePublisher[] @relation(\"UserFavoritePublishers\")\n  notifications       Notification[]\n\n  @@map(\"users\")\n}\n\nmodel Category {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String   @unique @db.VarChar(100)\n  nameAr    String   @unique @map(\"name_ar\") @db.VarChar(100)\n  slug      String   @unique @db.VarChar(100)\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  worksheets Worksheet[]\n\n  @@map(\"categories\")\n}\n\nmodel Grade {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String   @unique @db.VarChar(100)\n  nameAr    String   @unique @map(\"name_ar\") @db.VarChar(100)\n  slug      String   @unique @db.VarChar(100)\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  worksheets Worksheet[]\n\n  @@map(\"grades\")\n}\n\nmodel Subject {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String   @unique @db.VarChar(100)\n  nameAr    String   @unique @map(\"name_ar\") @db.VarChar(100)\n  slug      String   @unique @db.VarChar(100)\n  color     String?  @db.VarChar(7)\n  icon      String?  @db.VarChar(50)\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  worksheets Worksheet[]\n\n  @@map(\"subjects\")\n}\n\nmodel Worksheet {\n  id            String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  title         String          @db.VarChar(255)\n  titleAr       String?         @map(\"title_ar\") @db.VarChar(255)\n  description   String?         @db.Text\n  descriptionAr String?         @map(\"description_ar\") @db.Text\n  categoryId    String          @map(\"category_id\") @db.Uuid\n  gradeId       String          @map(\"grade_id\") @db.Uuid\n  subjectId     String          @map(\"subject_id\") @db.Uuid\n  uploadedBy    String          @map(\"uploaded_by\") @db.Uuid\n  fileUrl       String          @map(\"file_url\") @db.Text\n  fileName      String          @map(\"file_name\") @db.VarChar(255)\n  fileSize      Int             @map(\"file_size\")\n  thumbnailUrl  String?         @map(\"thumbnail_url\") @db.Text\n  pageCount     Int?            @map(\"page_count\")\n  status        WorksheetStatus @default(DRAFT)\n  audience      TargetAudience  @default(TEACHERS_AND_STUDENTS)\n  isEndorsed    Boolean         @default(false) @map(\"is_endorsed\")\n  endorsedById  String?         @map(\"endorsed_by_id\") @db.Uuid\n  endorsedAt    DateTime?       @map(\"endorsed_at\") @db.Timestamptz()\n  tags          String[]        @default([])\n  downloadCount Int             @default(0) @map(\"download_count\")\n  favoriteCount Int             @default(0) @map(\"favorite_count\")\n  ratingAvg     Float           @default(0) @map(\"rating_avg\")\n  reviewCount   Int             @default(0) @map(\"review_count\")\n  createdAt     DateTime        @default(now()) @map(\"created_at\") @db.Timestamptz()\n  updatedAt     DateTime        @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz()\n\n  category   Category   @relation(fields: [categoryId], references: [id])\n  grade      Grade      @relation(fields: [gradeId], references: [id])\n  subject    Subject    @relation(fields: [subjectId], references: [id])\n  uploader   User       @relation(\"UploadedWorksheets\", fields: [uploadedBy], references: [id])\n  endorsedBy User?      @relation(\"EndorsedWorksheets\", fields: [endorsedById], references: [id])\n  downloads  Download[]\n  favorites  Favorite[]\n  reviews    Review[]\n\n  @@index([status])\n  @@index([gradeId])\n  @@index([subjectId])\n  @@index([categoryId])\n  @@index([uploadedBy])\n  @@index([audience])\n  @@index([isEndorsed(sort: Desc), createdAt(sort: Desc)])\n  @@index([subjectId, isEndorsed(sort: Desc), createdAt(sort: Desc)])\n  @@index([gradeId, subjectId])\n  @@map(\"worksheets\")\n}\n\nmodel Download {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId       String   @map(\"user_id\") @db.Uuid\n  worksheetId  String   @map(\"worksheet_id\") @db.Uuid\n  downloadedAt DateTime @default(now()) @map(\"downloaded_at\") @db.Timestamptz()\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  worksheet Worksheet @relation(fields: [worksheetId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, worksheetId])\n  @@index([userId])\n  @@map(\"downloads\")\n}\n\nmodel Favorite {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId      String   @map(\"user_id\") @db.Uuid\n  worksheetId String   @map(\"worksheet_id\") @db.Uuid\n  createdAt   DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  worksheet Worksheet @relation(fields: [worksheetId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, worksheetId])\n  @@index([userId])\n  @@map(\"favorites\")\n}\n\n/// متابعة الأعضاء للناشرين (مؤسسات / معلمين / متفقدين)\nmodel PublisherFollow {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  followerId  String   @map(\"follower_id\") @db.Uuid\n  publisherId String   @map(\"publisher_id\") @db.Uuid\n  createdAt   DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  follower  User @relation(\"UserFollowing\", fields: [followerId], references: [id], onDelete: Cascade)\n  publisher User @relation(\"PublisherFollowers\", fields: [publisherId], references: [id], onDelete: Cascade)\n\n  @@unique([followerId, publisherId])\n  @@index([followerId])\n  @@index([publisherId])\n  @@map(\"publisher_follows\")\n}\n\n/// إضافة الناشر (معلم / مؤسسة) إلى قائمة الناشرين المفضلين\nmodel FavoritePublisher {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId      String   @map(\"user_id\") @db.Uuid\n  publisherId String   @map(\"publisher_id\") @db.Uuid\n  createdAt   DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  user      User @relation(\"UserFavoritePublishers\", fields: [userId], references: [id], onDelete: Cascade)\n  publisher User @relation(\"PublisherFavoritedBy\", fields: [publisherId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, publisherId])\n  @@index([userId])\n  @@index([publisherId])\n  @@map(\"favorite_publishers\")\n}\n\n/// نظام التنبيهات الفورية (جرس الإشعارات في البار العلوي)\nmodel Notification {\n  id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId    String   @map(\"user_id\") @db.Uuid\n  title     String   @db.VarChar(255)\n  message   String   @db.Text\n  link      String?  @db.Text\n  isRead    Boolean  @default(false) @map(\"is_read\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, isRead])\n  @@index([createdAt(sort: Desc)])\n  @@map(\"notifications\")\n}\n\nmodel Review {\n  id                  String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  rating              Int\n  comment             String   @db.Text\n  isOfficialDirective Boolean  @default(false) @map(\"is_official_directive\")\n  userId              String   @map(\"user_id\") @db.Uuid\n  worksheetId         String   @map(\"worksheet_id\") @db.Uuid\n  createdAt           DateTime @default(now()) @map(\"created_at\") @db.Timestamptz()\n  updatedAt           DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz()\n\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  worksheet Worksheet @relation(fields: [worksheetId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, worksheetId])\n  @@index([worksheetId])\n  @@index([userId])\n  @@map(\"reviews\")\n}\n",
  "supabase/sql/rls-policies.sql": "-- ============================================================\n-- Row Level Security (RLS) Policies — Al-Musnad (المسند) v3.0\n-- ============================================================\n\nALTER TABLE users ENABLE ROW LEVEL SECURITY;\nALTER TABLE worksheets ENABLE ROW LEVEL SECURITY;\nALTER TABLE downloads ENABLE ROW LEVEL SECURITY;\nALTER TABLE favorites ENABLE ROW LEVEL SECURITY;\nALTER TABLE reviews ENABLE ROW LEVEL SECURITY;\nALTER TABLE categories ENABLE ROW LEVEL SECURITY;\nALTER TABLE grades ENABLE ROW LEVEL SECURITY;\nALTER TABLE subjects ENABLE ROW LEVEL SECURITY;\nALTER TABLE publisher_follows ENABLE ROW LEVEL SECURITY;\nALTER TABLE favorite_publishers ENABLE ROW LEVEL SECURITY;\nALTER TABLE notifications ENABLE ROW LEVEL SECURITY;\n\n-- ── Users ────────────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Anyone can view public user profiles\" ON users;\nCREATE POLICY \"Anyone can view public user profiles\"\n  ON users FOR SELECT\n  USING (true);\n\nDROP POLICY IF EXISTS \"Users can update own profile\" ON users;\nCREATE POLICY \"Users can update own profile\"\n  ON users FOR UPDATE\n  USING (auth.uid() = id);\n\nDROP POLICY IF EXISTS \"Service role full access to users\" ON users;\nCREATE POLICY \"Service role full access to users\"\n  ON users FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Worksheets ───────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Anyone can view published worksheets\" ON worksheets;\nCREATE POLICY \"Anyone can view published worksheets\"\n  ON worksheets FOR SELECT\n  USING (status = 'PUBLISHED');\n\nDROP POLICY IF EXISTS \"Users can view own worksheets\" ON worksheets;\nCREATE POLICY \"Users can view own worksheets\"\n  ON worksheets FOR SELECT\n  USING (auth.uid() = uploaded_by);\n\nDROP POLICY IF EXISTS \"Authenticated users can create worksheets\" ON worksheets;\nCREATE POLICY \"Authenticated users can create worksheets\"\n  ON worksheets FOR INSERT\n  WITH CHECK (auth.uid() = uploaded_by);\n\nDROP POLICY IF EXISTS \"Users can update own worksheets\" ON worksheets;\nCREATE POLICY \"Users can update own worksheets\"\n  ON worksheets FOR UPDATE\n  USING (auth.uid() = uploaded_by);\n\nDROP POLICY IF EXISTS \"Service role full access to worksheets\" ON worksheets;\nCREATE POLICY \"Service role full access to worksheets\"\n  ON worksheets FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Publisher Follows & Favorites ────────────────────────────\nDROP POLICY IF EXISTS \"Anyone can view publisher follows\" ON publisher_follows;\nCREATE POLICY \"Anyone can view publisher follows\"\n  ON publisher_follows FOR SELECT\n  USING (true);\n\nDROP POLICY IF EXISTS \"Users can manage own follows\" ON publisher_follows;\nCREATE POLICY \"Users can manage own follows\"\n  ON publisher_follows FOR ALL\n  USING (auth.uid() = follower_id);\n\nDROP POLICY IF EXISTS \"Users can manage own favorite publishers\" ON favorite_publishers;\nCREATE POLICY \"Users can manage own favorite publishers\"\n  ON favorite_publishers FOR ALL\n  USING (auth.uid() = user_id);\n\n-- ── Notifications ────────────────────────────────────────────\nDROP POLICY IF EXISTS \"Users can view own notifications\" ON notifications;\nCREATE POLICY \"Users can view own notifications\"\n  ON notifications FOR SELECT\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Users can update own notifications\" ON notifications;\nCREATE POLICY \"Users can update own notifications\"\n  ON notifications FOR UPDATE\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Service role full access to notifications\" ON notifications;\nCREATE POLICY \"Service role full access to notifications\"\n  ON notifications FOR ALL\n  USING (auth.role() = 'service_role');\n\n-- ── Downloads, Favorites, Reviews, Reference Tables ──────────\nDROP POLICY IF EXISTS \"Users can view own downloads\" ON downloads;\nCREATE POLICY \"Users can view own downloads\"\n  ON downloads FOR SELECT\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Service role full access to downloads\" ON downloads;\nCREATE POLICY \"Service role full access to downloads\"\n  ON downloads FOR ALL\n  USING (auth.role() = 'service_role');\n\nDROP POLICY IF EXISTS \"Users can view own favorites\" ON favorites;\nCREATE POLICY \"Users can view own favorites\"\n  ON favorites FOR SELECT\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Service role full access to favorites\" ON favorites;\nCREATE POLICY \"Service role full access to favorites\"\n  ON favorites FOR ALL\n  USING (auth.role() = 'service_role');\n\nDROP POLICY IF EXISTS \"Anyone can view reviews\" ON reviews;\nCREATE POLICY \"Anyone can view reviews\"\n  ON reviews FOR SELECT\n  USING (true);\n\nDROP POLICY IF EXISTS \"Authenticated users can create own reviews\" ON reviews;\nCREATE POLICY \"Authenticated users can create own reviews\"\n  ON reviews FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Users can update own reviews\" ON reviews;\nCREATE POLICY \"Users can update own reviews\"\n  ON reviews FOR UPDATE\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Users can delete own reviews\" ON reviews;\nCREATE POLICY \"Users can delete own reviews\"\n  ON reviews FOR DELETE\n  USING (auth.uid() = user_id);\n\nDROP POLICY IF EXISTS \"Service role full access to reviews\" ON reviews;\nCREATE POLICY \"Service role full access to reviews\"\n  ON reviews FOR ALL\n  USING (auth.role() = 'service_role');\n\nDROP POLICY IF EXISTS \"Anyone can view categories\" ON categories;\nCREATE POLICY \"Anyone can view categories\" ON categories FOR SELECT USING (true);\n\nDROP POLICY IF EXISTS \"Anyone can view grades\" ON grades;\nCREATE POLICY \"Anyone can view grades\" ON grades FOR SELECT USING (true);\n\nDROP POLICY IF EXISTS \"Anyone can view subjects\" ON subjects;\nCREATE POLICY \"Anyone can view subjects\" ON subjects FOR SELECT USING (true);\n",
  "src/config/constants.ts": "/**\n * Application Constants — Al-Musnad (المسند) v3.0\n */\n\nexport const APP_CONFIG = {\n  name: \"Al-Musnad\",\n  nameAr: \"المسند\",\n  description: \"Integrated educational platform for institutions, inspectors, teachers, and students.\",\n  descriptionAr: \"منصة المسند التربوية المتكاملة للمؤسسات التعليمية، المتفقدين، المعلمين، والتلاميذ لتبادل واعتماد الموارد والأنشطة البيداغوجية.\",\n  url: process.env.NEXT_PUBLIC_APP_URL ?? \"http://localhost:3000\",\n} as const;\n\nexport const MAX_FILE_SIZE_MB = 20;\nexport const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;\n\nexport const ALLOWED_FILE_TYPES = [\"application/pdf\"] as const;\nexport type AllowedFileType = (typeof ALLOWED_FILE_TYPES)[number];\n\nexport const ALLOWED_FILE_EXTENSIONS = [\".pdf\"] as const;\n\nexport const DEFAULT_PAGE_SIZE = 20;\nexport const MAX_PAGE_SIZE = 50;\n\nexport const STORAGE_BUCKETS = {\n  WORKSHEETS: process.env.SUPABASE_STORAGE_BUCKET ?? \"worksheets\",\n} as const;\n\nexport const SIGNED_URL_EXPIRY_SECONDS = 3600; // 1 hour\n",
  "src/types/api.ts": "/**\n * API Contracts and Data Transfer Object (DTO) Type Definitions — Al-Musnad v3.0\n */\n\nexport type Role = \"INSTITUTION\" | \"INSPECTOR\" | \"TEACHER\" | \"STUDENT\" | \"ADMIN\";\nexport type AccountRoleOption = \"INSTITUTION\" | \"INSPECTOR\" | \"TEACHER\" | \"STUDENT\";\nexport type WorksheetStatus = \"DRAFT\" | \"PUBLISHED\" | \"ARCHIVED\";\n\nexport type TargetAudience =\n  | \"ALL\"\n  | \"SAME_ROLE_ONLY\"\n  | \"TEACHERS_ONLY\"\n  | \"TEACHERS_AND_STUDENTS\"\n  | \"INSTITUTIONS_ONLY\";\n\nexport type ProfileEditStatus = \"NONE\" | \"PENDING\" | \"APPROVED\" | \"REJECTED\";\n\nexport type WorksheetSortOption = \"newest\" | \"popular\" | \"downloads\" | \"title\";\n\nexport interface PaginationMeta {\n  page: number;\n  limit: number;\n  total: number;\n  totalPages: number;\n}\n\nexport interface ApiSuccessResponse<T> {\n  success: true;\n  data: T;\n  meta?: PaginationMeta;\n}\n\nexport interface ApiErrorDetail {\n  field?: string;\n  message: string;\n}\n\nexport interface ApiErrorResponse {\n  success: false;\n  error: {\n    code: string;\n    message: string;\n    details?: ApiErrorDetail[];\n  };\n}\n\nexport type ApiResponse<T> = ApiSuccessResponse<T> | ApiErrorResponse;\n\nexport interface PendingProfileData {\n  name?: string;\n  school?: string | null;\n  bio?: string | null;\n  avatarUrl?: string | null;\n  requestedAt?: string;\n}\n\nexport interface User {\n  id: string;\n  email: string;\n  name: string;\n  avatarUrl: string | null;\n  role: Role;\n  school: string | null;\n  bio?: string | null;\n  subscriptionPlan?: string;\n  profileEditStatus?: ProfileEditStatus;\n  pendingProfileData?: PendingProfileData | null;\n  followersCount?: number;\n  favoritedByCount?: number;\n  inspectorPending?: boolean;\n  inspectorCode?: string | null;\n  createdAt: Date | string;\n  updatedAt: Date | string;\n}\n\nexport interface NotificationItem {\n  id: string;\n  userId: string;\n  title: string;\n  message: string;\n  link: string | null;\n  isRead: boolean;\n  createdAt: Date | string;\n}\n\nexport interface Category {\n  id: string;\n  name: string;\n  nameAr: string;\n  slug: string;\n  sortOrder: number;\n  createdAt: Date | string;\n}\n\nexport interface Grade {\n  id: string;\n  name: string;\n  nameAr: string;\n  slug: string;\n  sortOrder: number;\n  createdAt: Date | string;\n}\n\nexport interface Subject {\n  id: string;\n  name: string;\n  nameAr: string;\n  slug: string;\n  color: string | null;\n  icon: string | null;\n  sortOrder: number;\n  createdAt: Date | string;\n}\n\nexport interface Worksheet {\n  id: string;\n  title: string;\n  titleAr: string | null;\n  description: string | null;\n  descriptionAr: string | null;\n  categoryId: string;\n  gradeId: string;\n  subjectId: string;\n  uploadedBy: string;\n  fileUrl: string;\n  fileName: string;\n  fileSize: number;\n  thumbnailUrl: string | null;\n  pageCount: number | null;\n  status: WorksheetStatus;\n  audience: TargetAudience;\n  isEndorsed: boolean;\n  endorsedById?: string | null;\n  endorsedAt?: Date | string | null;\n  tags: string[];\n  downloadCount: number;\n  favoriteCount: number;\n  ratingAvg: number;\n  reviewCount: number;\n  createdAt: Date | string;\n  updatedAt: Date | string;\n}\n\nexport interface WorksheetWithRelations extends Worksheet {\n  category: Category;\n  grade: Grade;\n  subject: Subject;\n  uploader: Pick<User, \"id\" | \"name\" | \"avatarUrl\" | \"school\" | \"role\" | \"bio\" | \"followersCount\" | \"favoritedByCount\">;\n  endorsedBy?: Pick<User, \"id\" | \"name\" | \"role\" | \"school\"> | null;\n  previewUrl?: string;\n}\n\nexport interface WorksheetFilterParams {\n  page?: number;\n  limit?: number;\n  search?: string;\n  grade?: string;\n  subject?: string;\n  category?: string;\n  audience?: TargetAudience;\n  tags?: string[];\n  sort?: WorksheetSortOption;\n  status?: WorksheetStatus;\n}\n\nexport interface Download {\n  id: string;\n  userId: string;\n  worksheetId: string;\n  downloadedAt: Date | string;\n}\n\nexport interface Favorite {\n  id: string;\n  userId: string;\n  worksheetId: string;\n  createdAt: Date | string;\n}\n\nexport interface Review {\n  id: string;\n  rating: number;\n  comment: string;\n  isOfficialDirective: boolean;\n  userId: string;\n  worksheetId: string;\n  createdAt: Date | string;\n  updatedAt: Date | string;\n}\n\nexport interface ReviewWithUser extends Review {\n  user: Pick<User, \"id\" | \"name\" | \"avatarUrl\" | \"school\" | \"role\">;\n}\n",
  "src/lib/validators/auth.ts": "/**\n * Auth & Profile Validation Schemas — Al-Musnad v3.0\n */\n\nimport { z } from \"zod\";\n\nexport const accountRoleOptionSchema = z\n  .enum([\"INSTITUTION\", \"INSPECTOR\", \"TEACHER\", \"STUDENT\"])\n  .default(\"TEACHER\");\n\nexport const signUpSchema = z.object({\n  email: z.string().email(\"البريد الإلكتروني غير صالح / Invalid email\"),\n  password: z\n    .string()\n    .min(8, \"كلمة المرور يجب ألا تقل عن 8 أحرف / Min 8 characters\")\n    .max(72, \"كلمة المرور طويلة جداً\"),\n  name: z\n    .string()\n    .trim()\n    .min(2, \"الاسم يجب أن يتكون من حرفين على الأقل\")\n    .max(255, \"الاسم طويل جداً\"),\n  school: z.string().trim().max(255).optional(),\n  role: accountRoleOptionSchema.optional().default(\"TEACHER\"),\n});\n\nexport const signInSchema = z.object({\n  email: z.string().email(\"البريد الإلكتروني غير صالح / Invalid email\"),\n  password: z.string().min(1, \"كلمة المرور مطلوبة / Password is required\"),\n  role: accountRoleOptionSchema.optional(),\n});\n\n/** Profile update request (submitted for Admin Approval) */\nexport const updateProfileSchema = z.object({\n  name: z\n    .string()\n    .trim()\n    .min(2, \"الاسم يجب أن يتكون من حرفين على الأقل\")\n    .max(255)\n    .optional(),\n  school: z.string().trim().max(255).optional(),\n  bio: z.string().trim().max(1000, \"النبذة التعريفية يجب ألا تتجاوز 1000 حرف\").optional(),\n  avatarUrl: z.string().url(\"رابط الصورة غير صالح\").optional().nullable(),\n});\n\nexport type SignUpInput = z.infer<typeof signUpSchema>;\nexport type SignInInput = z.infer<typeof signInSchema>;\nexport type UpdateProfileInput = z.infer<typeof updateProfileSchema>;\n",
  "src/lib/validators/worksheet.ts": "/**\n * Worksheet Validation Schemas — Al-Musnad v3.0 (With TargetAudience Support)\n */\n\nimport { z } from \"zod\";\nimport { WorksheetStatus } from \"@prisma/client\";\nimport { uuidSchema, paginationSchema, worksheetSortSchema } from \"./common\";\n\nexport const targetAudienceSchema = z\n  .enum([\n    \"ALL\",\n    \"SAME_ROLE_ONLY\",\n    \"TEACHERS_ONLY\",\n    \"TEACHERS_AND_STUDENTS\",\n    \"INSTITUTIONS_ONLY\",\n  ])\n  .default(\"TEACHERS_AND_STUDENTS\");\n\n/** Schema for creating a new worksheet */\nexport const createWorksheetSchema = z.object({\n  title: z\n    .string()\n    .trim()\n    .min(3, \"العنوان يجب أن يتكون من 3 أحرف على الأقل\")\n    .max(255, \"العنوان طويل جداً\"),\n  titleAr: z\n    .string()\n    .trim()\n    .max(255, \"العنوان العربي طويل جداً\")\n    .optional(),\n  description: z\n    .string()\n    .trim()\n    .max(2000, \"الوصف طويل جداً\")\n    .optional(),\n  descriptionAr: z\n    .string()\n    .trim()\n    .max(2000, \"الوصف العربي طويل جداً\")\n    .optional(),\n  categoryId: uuidSchema,\n  gradeId: uuidSchema,\n  subjectId: uuidSchema,\n  audience: targetAudienceSchema,\n  pageCount: z.number().int().positive().optional(),\n  thumbnailUrl: z.string().optional(),\n  tags: z\n    .array(z.string().trim().min(1).max(50))\n    .max(10, \"الحد الأقصى 10 وسوم\")\n    .default([]),\n});\n\n/** Schema for updating an existing worksheet */\nexport const updateWorksheetSchema = createWorksheetSchema\n  .partial()\n  .extend({\n    status: z.nativeEnum(WorksheetStatus).optional(),\n  });\n\n/** Schema for filtering/searching worksheets */\nexport const worksheetFilterSchema = paginationSchema.extend({\n  search: z.string().trim().max(200).optional(),\n  grade: z.string().optional(),\n  subject: z.string().optional(),\n  category: z.string().optional(),\n  audience: targetAudienceSchema.optional(),\n  tags: z\n    .string()\n    .transform((val) => val.split(\",\").map((t) => t.trim()))\n    .optional(),\n  sort: worksheetSortSchema,\n  status: z.nativeEnum(WorksheetStatus).optional(),\n});\n\nexport type CreateWorksheetInput = z.infer<typeof createWorksheetSchema>;\nexport type UpdateWorksheetInput = z.infer<typeof updateWorksheetSchema>;\nexport type WorksheetFilterInput = z.infer<typeof worksheetFilterSchema>;\n",
  "src/services/worksheet.service.ts": "/**\n * Worksheet Service — Al-Musnad v3.0\n *\n * Features:\n * 1. Inspector Endorsement Ranking Boost: Worksheets endorsed by an Inspector (`isEndorsed: true`)\n *    automatically rise to the top of their subject & catalog listings (`orderBy: [{ isEndorsed: 'desc' }, ...]`).\n * 2. Audience Visibility Filtering: Enforces `TargetAudience` rules so teacher-only materials\n *    (like exam answer keys / إصلاح الامتحانات) are hidden from students, and `SAME_ROLE_ONLY`\n *    posts stay within the publisher's peer group.\n */\n\nimport { db } from \"@/lib/db\";\nimport { Prisma, WorksheetStatus, Role, TargetAudience } from \"@prisma/client\";\nimport { getPaginationParams, buildPaginationMeta } from \"@/lib/utils/pagination\";\nimport { NotFoundError, ForbiddenError } from \"@/lib/utils/errors\";\nimport { getSignedDownloadUrl } from \"@/services/storage.service\";\nimport type { WorksheetFilterInput, CreateWorksheetInput, UpdateWorksheetInput } from \"@/lib/validators/worksheet\";\n\nexport const publicWorksheetSelect = {\n  id: true,\n  title: true,\n  titleAr: true,\n  description: true,\n  descriptionAr: true,\n  categoryId: true,\n  gradeId: true,\n  subjectId: true,\n  uploadedBy: true,\n  fileUrl: true,\n  fileName: true,\n  fileSize: true,\n  thumbnailUrl: true,\n  pageCount: true,\n  status: true,\n  audience: true,\n  isEndorsed: true,\n  endorsedById: true,\n  endorsedAt: true,\n  tags: true,\n  downloadCount: true,\n  favoriteCount: true,\n  ratingAvg: true,\n  reviewCount: true,\n  createdAt: true,\n  updatedAt: true,\n  category: {\n    select: {\n      id: true,\n      name: true,\n      nameAr: true,\n      slug: true,\n      sortOrder: true,\n    },\n  },\n  grade: {\n    select: {\n      id: true,\n      name: true,\n      nameAr: true,\n      slug: true,\n      sortOrder: true,\n    },\n  },\n  subject: {\n    select: {\n      id: true,\n      name: true,\n      nameAr: true,\n      slug: true,\n      color: true,\n      icon: true,\n      sortOrder: true,\n    },\n  },\n  uploader: {\n    select: {\n      id: true,\n      name: true,\n      avatarUrl: true,\n      school: true,\n      role: true,\n      bio: true,\n      followersCount: true,\n      favoritedByCount: true,\n    },\n  },\n  endorsedBy: {\n    select: {\n      id: true,\n      name: true,\n      role: true,\n      school: true,\n    },\n  },\n} as const;\n\n/**\n * Builds the Prisma audience visibility filter based on the current viewer's Role.\n */\nexport function buildAudienceVisibilityFilter(viewerRole?: Role | string | null): Prisma.WorksheetWhereInput {\n  if (viewerRole === \"ADMIN\" || viewerRole === \"INSPECTOR\") {\n    // Inspectors and Admins have supervisory visibility across educational materials\n    return {};\n  }\n\n  if (viewerRole === \"TEACHER\") {\n    return {\n      OR: [\n        { audience: TargetAudience.ALL },\n        { audience: TargetAudience.TEACHERS_AND_STUDENTS },\n        { audience: TargetAudience.TEACHERS_ONLY },\n        {\n          AND: [\n            { audience: TargetAudience.SAME_ROLE_ONLY },\n            { uploader: { role: Role.TEACHER } },\n          ],\n        },\n      ],\n    };\n  }\n\n  if (viewerRole === \"INSTITUTION\") {\n    return {\n      OR: [\n        { audience: TargetAudience.ALL },\n        { audience: TargetAudience.TEACHERS_AND_STUDENTS },\n        { audience: TargetAudience.TEACHERS_ONLY },\n        { audience: TargetAudience.INSTITUTIONS_ONLY },\n        {\n          AND: [\n            { audience: TargetAudience.SAME_ROLE_ONLY },\n            { uploader: { role: Role.INSTITUTION } },\n          ],\n        },\n      ],\n    };\n  }\n\n  if (viewerRole === \"STUDENT\") {\n    return {\n      OR: [\n        { audience: TargetAudience.ALL },\n        { audience: TargetAudience.TEACHERS_AND_STUDENTS },\n        {\n          AND: [\n            { audience: TargetAudience.SAME_ROLE_ONLY },\n            { uploader: { role: Role.STUDENT } },\n          ],\n        },\n      ],\n    };\n  }\n\n  // Unauthenticated guests: only see public ALL and TEACHERS_AND_STUDENTS worksheets\n  // (Teacher-only exam corrections and same-role internal posts are hidden)\n  return {\n    audience: {\n      in: [TargetAudience.ALL, TargetAudience.TEACHERS_AND_STUDENTS],\n    },\n  };\n}\n\nexport async function listWorksheets(\n  filters: WorksheetFilterInput,\n  viewerRole?: Role | string | null\n) {\n  const { page, limit, search, grade, subject, category, audience, tags, sort } = filters;\n  const { skip, take, page: currentPage, limit: currentLimit } = getPaginationParams(page, limit);\n\n  const audienceGuard = buildAudienceVisibilityFilter(viewerRole);\n\n  const where: Prisma.WorksheetWhereInput = {\n    status: WorksheetStatus.PUBLISHED,\n    ...audienceGuard,\n  };\n\n  if (grade) where.grade = { slug: grade };\n  if (subject) where.subject = { slug: subject };\n  if (category) where.category = { slug: category };\n  if (audience) where.audience = audience;\n  if (tags && tags.length > 0) where.tags = { hasSome: tags };\n\n  if (search && search.trim().length > 0) {\n    const term = search.trim();\n    where.AND = [\n      ...(Array.isArray(where.AND) ? where.AND : []),\n      {\n        OR: [\n          { title: { contains: term, mode: \"insensitive\" } },\n          { titleAr: { contains: term, mode: \"insensitive\" } },\n          { description: { contains: term, mode: \"insensitive\" } },\n          { descriptionAr: { contains: term, mode: \"insensitive\" } },\n          { tags: { has: term } },\n        ],\n      },\n    ];\n  }\n\n  // Secondary sort selected by user; PRIMARY sort is ALWAYS `isEndorsed: \"desc\"`\n  // so Inspector-verified worksheets rise to the top of the subject/catalog!\n  const secondaryOrderBy: Prisma.WorksheetOrderByWithRelationInput = (() => {\n    switch (sort) {\n      case \"popular\":\n        return { favoriteCount: \"desc\" };\n      case \"downloads\":\n        return { downloadCount: \"desc\" };\n      case \"title\":\n        return { title: \"asc\" };\n      case \"newest\":\n      default:\n        return { createdAt: \"desc\" };\n    }\n  })();\n\n  const orderBy: Prisma.WorksheetOrderByWithRelationInput[] = [\n    { isEndorsed: \"desc\" },\n    secondaryOrderBy,\n  ];\n\n  const [total, worksheets] = await Promise.all([\n    db.worksheet.count({ where }),\n    db.worksheet.findMany({\n      where,\n      select: publicWorksheetSelect,\n      orderBy,\n      skip,\n      take,\n    }),\n  ]);\n\n  return {\n    data: worksheets,\n    meta: buildPaginationMeta(total, currentPage, currentLimit),\n  };\n}\n\nexport async function getWorksheetById(\n  id: string,\n  viewerRole?: Role | string | null,\n  viewerUserId?: string | null\n) {\n  const worksheet = await db.worksheet.findUnique({\n    where: { id },\n    select: publicWorksheetSelect,\n  });\n\n  if (!worksheet || worksheet.status === WorksheetStatus.ARCHIVED) {\n    throw new NotFoundError(\"Worksheet\");\n  }\n\n  // Check audience permission unless viewer is the uploader, Inspector, or Admin\n  const isOwnerOrSupervisor =\n    (viewerUserId && worksheet.uploadedBy === viewerUserId) ||\n    viewerRole === \"ADMIN\" ||\n    viewerRole === \"INSPECTOR\";\n\n  if (!isOwnerOrSupervisor) {\n    if (\n      worksheet.audience === TargetAudience.TEACHERS_ONLY &&\n      viewerRole !== \"TEACHER\" &&\n      viewerRole !== \"INSTITUTION\"\n    ) {\n      throw new ForbiddenError(\"هذا المنشور (إصلاح / وثيقة خاصة) مخصص للمعلمين والمتفقدين فقط.\");\n    }\n    if (\n      worksheet.audience === TargetAudience.INSTITUTIONS_ONLY &&\n      viewerRole !== \"INSTITUTION\"\n    ) {\n      throw new ForbiddenError(\"هذا المنشور مخصص للمؤسسات التربوية فقط.\");\n    }\n    if (\n      worksheet.audience === TargetAudience.SAME_ROLE_ONLY &&\n      viewerRole !== worksheet.uploader.role\n    ) {\n      throw new ForbiddenError(\"هذا المنشور مخصص فقط لأعضاء نفس فئة الناشر.\");\n    }\n  }\n\n  let previewUrl: string | undefined = undefined;\n  try {\n    previewUrl = await getSignedDownloadUrl(worksheet.fileUrl, 3600);\n  } catch (err) {\n    console.warn(\"[getWorksheetById] Preview signed URL fallback:\", err);\n  }\n\n  return {\n    ...worksheet,\n    previewUrl,\n  };\n}\n\nexport interface CreateWorksheetData extends CreateWorksheetInput {\n  uploadedBy: string;\n  fileUrl: string;\n  fileName: string;\n  fileSize: number;\n  thumbnailUrl?: string;\n  pageCount?: number;\n}\n\nexport async function createWorksheet(data: CreateWorksheetData) {\n  return db.worksheet.create({\n    data: {\n      title: data.title,\n      titleAr: data.titleAr ?? null,\n      description: data.description ?? null,\n      descriptionAr: data.descriptionAr ?? null,\n      categoryId: data.categoryId,\n      gradeId: data.gradeId,\n      subjectId: data.subjectId,\n      uploadedBy: data.uploadedBy,\n      fileUrl: data.fileUrl,\n      fileName: data.fileName,\n      fileSize: data.fileSize,\n      thumbnailUrl: data.thumbnailUrl ?? null,\n      pageCount: data.pageCount ?? null,\n      audience: data.audience ?? TargetAudience.TEACHERS_AND_STUDENTS,\n      tags: data.tags ?? [],\n      status: WorksheetStatus.PUBLISHED,\n    },\n    select: publicWorksheetSelect,\n  });\n}\n\nexport async function updateWorksheet(\n  id: string,\n  userId: string,\n  data: UpdateWorksheetInput,\n  userRole?: string\n) {\n  const existing = await db.worksheet.findUnique({\n    where: { id },\n    select: { id: true, uploadedBy: true },\n  });\n\n  if (!existing) {\n    throw new NotFoundError(\"Worksheet\");\n  }\n\n  if (existing.uploadedBy !== userId && userRole !== \"ADMIN\") {\n    throw new ForbiddenError(\"You can only edit your own worksheets\");\n  }\n\n  return db.worksheet.update({\n    where: { id },\n    data: {\n      ...(data.title !== undefined ? { title: data.title } : {}),\n      ...(data.titleAr !== undefined ? { titleAr: data.titleAr } : {}),\n      ...(data.description !== undefined ? { description: data.description } : {}),\n      ...(data.descriptionAr !== undefined ? { descriptionAr: data.descriptionAr } : {}),\n      ...(data.categoryId !== undefined ? { categoryId: data.categoryId } : {}),\n      ...(data.gradeId !== undefined ? { gradeId: data.gradeId } : {}),\n      ...(data.subjectId !== undefined ? { subjectId: data.subjectId } : {}),\n      ...(data.audience !== undefined ? { audience: data.audience } : {}),\n      ...(data.tags !== undefined ? { tags: data.tags } : {}),\n      ...(data.status !== undefined ? { status: data.status } : {}),\n    },\n    select: publicWorksheetSelect,\n  });\n}\n\nexport async function archiveWorksheet(\n  id: string,\n  userId: string,\n  userRole?: string\n) {\n  const existing = await db.worksheet.findUnique({\n    where: { id },\n    select: { id: true, uploadedBy: true },\n  });\n\n  if (!existing) {\n    throw new NotFoundError(\"Worksheet\");\n  }\n\n  if (existing.uploadedBy !== userId && userRole !== \"ADMIN\") {\n    throw new ForbiddenError(\"You can only archive your own worksheets\");\n  }\n\n  await db.worksheet.update({\n    where: { id },\n    data: { status: WorksheetStatus.ARCHIVED },\n  });\n\n  return { success: true, archived: true, id };\n}\n\nexport async function getUserUploads(userId: string, pageInput?: number, limitInput?: number) {\n  const { skip, take, page, limit } = getPaginationParams(pageInput, limitInput);\n\n  const where: Prisma.WorksheetWhereInput = {\n    uploadedBy: userId,\n    status: { not: WorksheetStatus.ARCHIVED },\n  };\n\n  const [total, worksheets] = await Promise.all([\n    db.worksheet.count({ where }),\n    db.worksheet.findMany({\n      where,\n      select: publicWorksheetSelect,\n      orderBy: [{ isEndorsed: \"desc\" }, { createdAt: \"desc\" }],\n      skip,\n      take,\n    }),\n  ]);\n\n  return {\n    data: worksheets,\n    meta: buildPaginationMeta(total, page, limit),\n  };\n}\n",
  "src/app/api/worksheets/route.ts": "/**\n * GET  /api/worksheets — List and search worksheets (Audience-Aware & Endorsement-Boosted)\n * POST /api/worksheets — Create a new worksheet (with file, auto-thumbnail & target audience)\n */\n\nimport { NextRequest } from \"next/server\";\nimport { successResponse, errorResponse } from \"@/lib/utils/api-response\";\nimport { worksheetFilterSchema, createWorksheetSchema } from \"@/lib/validators/worksheet\";\nimport { listWorksheets, createWorksheet } from \"@/services/worksheet.service\";\nimport { uploadFile, uploadThumbnail } from \"@/services/storage.service\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { UnauthorizedError } from \"@/lib/utils/errors\";\nimport { db } from \"@/lib/db\";\n\nexport async function GET(request: NextRequest) {\n  try {\n    const searchParams = Object.fromEntries(request.nextUrl.searchParams);\n    const filters = worksheetFilterSchema.parse(searchParams);\n\n    let viewerRole: string | null = null;\n    try {\n      const supabase = await createSupabaseServerClient();\n      const {\n        data: { user },\n      } = await supabase.auth.getUser();\n      if (user) {\n        const dbUser = await db.user.findUnique({\n          where: { id: user.id },\n          select: { role: true },\n        });\n        viewerRole = dbUser?.role || null;\n      }\n    } catch {\n      // Guest viewer\n    }\n\n    const result = await listWorksheets(filters, viewerRole);\n    return successResponse(result.data, result.meta);\n  } catch (error) {\n    return errorResponse(error);\n  }\n}\n\nexport async function POST(request: NextRequest) {\n  try {\n    const supabase = await createSupabaseServerClient();\n    const {\n      data: { user },\n    } = await supabase.auth.getUser();\n    if (!user) throw new UnauthorizedError();\n\n    const formData = await request.formData();\n    const file = formData.get(\"file\") as File | null;\n    const thumbnail = formData.get(\"thumbnail\") as File | null;\n    const pageCountRaw = formData.get(\"pageCount\") as string | null;\n    const metadataRaw = formData.get(\"metadata\") as string | null;\n\n    if (!file) {\n      return errorResponse(\n        { message: \"File is required\", code: \"MISSING_FILE\", statusCode: 400 },\n        400\n      );\n    }\n\n    const metadata = createWorksheetSchema.parse(\n      metadataRaw ? JSON.parse(metadataRaw) : {}\n    );\n\n    const [uploadResult, thumbnailUrl] = await Promise.all([\n      uploadFile(file, user.id),\n      thumbnail\n        ? uploadThumbnail(thumbnail, user.id).catch(() => undefined)\n        : Promise.resolve(undefined),\n    ]);\n\n    const parsedPageCount = pageCountRaw ? Number(pageCountRaw) : undefined;\n\n    const worksheet = await createWorksheet({\n      ...metadata,\n      uploadedBy: user.id,\n      fileUrl: uploadResult.fileUrl,\n      fileName: uploadResult.fileName,\n      fileSize: uploadResult.fileSize,\n      thumbnailUrl,\n      pageCount:\n        Number.isInteger(parsedPageCount) && parsedPageCount! > 0\n          ? parsedPageCount\n          : undefined,\n    });\n\n    return successResponse(worksheet, undefined, 201);\n  } catch (error) {\n    return errorResponse(error);\n  }\n}\n",
  "src/actions/inspector.actions.ts": "\"use server\";\n\nimport { revalidatePath } from \"next/cache\";\nimport crypto from \"crypto\";\nimport { db } from \"@/lib/db\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport {\n  UnauthorizedError,\n  ForbiddenError,\n  ValidationError,\n  NotFoundError,\n} from \"@/lib/utils/errors\";\nimport { Role } from \"@prisma/client\";\n\n/**\n * للمشرف فقط: توليد كود تفعيل خاص لمتفقد بعد التحقق من هويته\n */\nexport async function generateInspectorCodeAdminAction(targetUserId: string) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) throw new UnauthorizedError(\"يرجى تسجيل الدخول أولاً\");\n\n  const adminUser = await db.user.findUnique({\n    where: { id: user.id },\n    select: { role: true },\n  });\n\n  if (!adminUser || adminUser.role !== Role.ADMIN) {\n    throw new ForbiddenError(\"غير مصرح لك بتوليد أكواد المتفقدين\");\n  }\n\n  const targetUser = await db.user.findUnique({\n    where: { id: targetUserId },\n    select: { id: true, name: true },\n  });\n\n  if (!targetUser) {\n    throw new NotFoundError(\"المستخدم غير موجود\");\n  }\n\n  const part1 = crypto.randomBytes(2).toString(\"hex\").toUpperCase();\n  const part2 = crypto.randomBytes(2).toString(\"hex\").toUpperCase();\n  const code = `INSP-${part1}-${part2}`;\n\n  const updated = await db.user.update({\n    where: { id: targetUserId },\n    data: {\n      inspectorCode: code,\n      inspectorPending: true,\n    },\n    select: {\n      id: true,\n      name: true,\n      inspectorCode: true,\n    },\n  });\n\n  await db.notification.create({\n    data: {\n      userId: targetUserId,\n      title: \"تم إصدار كود تفعيل المتفقد التربوي\",\n      message: \"قام المشرف العام بمراجعة طلبك وإصدار كود التفعيل الخاص بك. يمكنك الآن تفعيل الشارة الرسمية.\",\n      link: \"/inspector/activate\",\n    },\n  });\n\n  revalidatePath(\"/admin/dashboard\");\n  return updated;\n}\n\n/**\n * للمتفقد: إدخال الكود السري لتفعيل صلاحية المتفقد والشارة الرسمية\n */\nexport async function activateInspectorCodeAction(rawCode: string) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    throw new UnauthorizedError(\"يرجى تسجيل الدخول أولاً لتفعيل الكود\");\n  }\n\n  const cleanCode = rawCode.trim().toUpperCase();\n  if (!cleanCode.startsWith(\"INSP-\") || cleanCode.length < 10) {\n    throw new ValidationError(\"صيغة كود التفعيل غير صحيحة (مثال: INSP-1A2B-3C4D)\");\n  }\n\n  const dbUser = await db.user.findUnique({\n    where: { id: user.id },\n    select: { id: true, role: true, inspectorCode: true },\n  });\n\n  if (!dbUser) {\n    throw new NotFoundError(\"الحساب غير موجود\");\n  }\n\n  if (dbUser.role === Role.INSPECTOR) {\n    return { alreadyActivated: true };\n  }\n\n  if (!dbUser.inspectorCode || dbUser.inspectorCode !== cleanCode) {\n    throw new ValidationError(\"كود التفعيل غير صحيح أو غير مخصص لهذا الحساب\");\n  }\n\n  await db.user.update({\n    where: { id: user.id },\n    data: {\n      role: Role.INSPECTOR,\n      inspectorPending: false,\n      inspectorCode: null,\n    },\n  });\n\n  revalidatePath(\"/profile\");\n  revalidatePath(\"/inspector/activate\");\n  revalidatePath(\"/\");\n\n  return { success: true, role: Role.INSPECTOR };\n}\n\n/**\n * ميزة اعتماد الصحة العلمية والبيداغوجية للمنشور من قِبل المتفقد التربوي\n * عند وضع المتفقد لعلامة الاعتماد، يرتفع المنشور تلقائياً في ترتيب المنشورات داخل المادة الدراسية\n */\nexport async function toggleWorksheetEndorsementAction(worksheetId: string) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    throw new UnauthorizedError(\"يرجى تسجيل الدخول أولاً\");\n  }\n\n  const caller = await db.user.findUnique({\n    where: { id: user.id },\n    select: { id: true, name: true, role: true },\n  });\n\n  if (!caller || (caller.role !== Role.INSPECTOR && caller.role !== Role.ADMIN)) {\n    throw new ForbiddenError(\"هذه الصلاحية مخصصة للمتفقدين التربويين المعتمدين فقط\");\n  }\n\n  const worksheet = await db.worksheet.findUnique({\n    where: { id: worksheetId },\n    select: {\n      id: true,\n      title: true,\n      titleAr: true,\n      isEndorsed: true,\n      uploadedBy: true,\n    },\n  });\n\n  if (!worksheet) {\n    throw new NotFoundError(\"المنشور غير موجود\");\n  }\n\n  const nextEndorsedState = !worksheet.isEndorsed;\n\n  const updated = await db.worksheet.update({\n    where: { id: worksheetId },\n    data: {\n      isEndorsed: nextEndorsedState,\n      endorsedById: nextEndorsedState ? caller.id : null,\n      endorsedAt: nextEndorsedState ? new Date() : null,\n    },\n    select: {\n      id: true,\n      isEndorsed: true,\n      endorsedAt: true,\n      endorsedBy: {\n        select: { id: true, name: true, role: true, school: true },\n      },\n    },\n  });\n\n  if (nextEndorsedState && worksheet.uploadedBy !== caller.id) {\n    const wsTitle = worksheet.titleAr || worksheet.title;\n    await db.notification.create({\n      data: {\n        userId: worksheet.uploadedBy,\n        title: \"🎖️ اعتماد علمي وبيداغوجي لمنشورك!\",\n        message: `قام المتفقد التربوي (${caller.name}) بتأكيد الصحة العلمية والبيداغوجية لمنشورك \"${wsTitle}\"، وقد تم رفع ترتيبه في صدارة المادة.`,\n        link: `/worksheet/${worksheet.id}`,\n      },\n    });\n  }\n\n  revalidatePath(`/worksheet/${worksheetId}`);\n  revalidatePath(\"/browse\");\n  revalidatePath(\"/\");\n  revalidatePath(\"/admin/dashboard\");\n\n  return updated;\n}\n",
  "src/actions/profile.actions.ts": "\"use server\";\n\n/**\n * Profile & Settings Server Actions — Al-Musnad v3.0\n *\n * Implements Admin-Approved Profile Edits:\n * When a user edits their profile, the changes are saved in `pendingProfileData`\n * with `profileEditStatus = 'PENDING'` until an ADMIN approves them in `/admin/dashboard`.\n */\n\nimport { revalidatePath } from \"next/cache\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { db } from \"@/lib/db\";\nimport { updateProfileSchema, type UpdateProfileInput } from \"@/lib/validators/auth\";\nimport { UnauthorizedError } from \"@/lib/utils/errors\";\nimport { ProfileEditStatus, Role, Prisma } from \"@prisma/client\";\n\nexport async function updateProfileAction(input: UpdateProfileInput) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    throw new UnauthorizedError(\"يجب تسجيل الدخول أولاً\");\n  }\n\n  const validated = updateProfileSchema.parse(input);\n\n  const currentUser = await db.user.findUnique({\n    where: { id: user.id },\n    select: { id: true, role: true, name: true, school: true, bio: true, avatarUrl: true },\n  });\n\n  if (!currentUser) {\n    throw new UnauthorizedError(\"الحساب غير موجود\");\n  }\n\n  // If the user is ADMIN, apply immediately; otherwise submit for Admin approval\n  if (currentUser.role === Role.ADMIN) {\n    const updatedAdmin = await db.user.update({\n      where: { id: user.id },\n      data: {\n        ...(validated.name !== undefined ? { name: validated.name } : {}),\n        ...(validated.school !== undefined ? { school: validated.school } : {}),\n        ...(validated.bio !== undefined ? { bio: validated.bio } : {}),\n        ...(validated.avatarUrl !== undefined ? { avatarUrl: validated.avatarUrl } : {}),\n        profileEditStatus: ProfileEditStatus.APPROVED,\n        pendingProfileData: Prisma.DbNull,\n      },\n    });\n    revalidatePath(\"/profile\");\n    return { ...updatedAdmin, pendingApproval: false };\n  }\n\n  const pendingPayload = {\n    name: validated.name ?? currentUser.name,\n    school: validated.school !== undefined ? validated.school : currentUser.school,\n    bio: validated.bio !== undefined ? validated.bio : currentUser.bio,\n    avatarUrl: validated.avatarUrl !== undefined ? validated.avatarUrl : currentUser.avatarUrl,\n    requestedAt: new Date().toISOString(),\n  };\n\n  const updatedUser = await db.user.update({\n    where: { id: user.id },\n    data: {\n      profileEditStatus: ProfileEditStatus.PENDING,\n      pendingProfileData: pendingPayload,\n    },\n  });\n\n  revalidatePath(\"/profile\");\n  revalidatePath(\"/admin/dashboard\");\n  return { ...updatedUser, pendingApproval: true };\n}\n\nexport async function updateSubscriptionPlanAction(planCode: string) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) throw new UnauthorizedError(\"يجب تسجيل الدخول أولاً\");\n\n  const updated = await db.user.update({\n    where: { id: user.id },\n    data: { subscriptionPlan: planCode },\n    select: { id: true, subscriptionPlan: true },\n  });\n\n  await db.notification.create({\n    data: {\n      userId: user.id,\n      title: \"تم تحديث باقة الاشتراك في المسند\",\n      message: `تم تفعيل باقة (${planCode}) على حسابك بنجاح.`,\n      link: \"/profile?tab=subscriptions\",\n    },\n  });\n\n  revalidatePath(\"/profile\");\n  return updated;\n}\n",
  "src/actions/publisher.actions.ts": "\"use server\";\n\n/**\n * Publisher Social & Bookmark Actions — Al-Musnad v3.0\n *\n * Allows members to:\n * 1. Follow / Unfollow any Publisher (Institution, Teacher, or Inspector).\n * 2. Add / Remove any Publisher to/from their Favorite Publishers list.\n * 3. View complete public Publisher Profile with role-filtered publications.\n */\n\nimport { revalidatePath } from \"next/cache\";\nimport { db } from \"@/lib/db\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { UnauthorizedError, NotFoundError, ValidationError } from \"@/lib/utils/errors\";\nimport { publicWorksheetSelect, buildAudienceVisibilityFilter } from \"@/services/worksheet.service\";\nimport { WorksheetStatus } from \"@prisma/client\";\n\nexport async function toggleFollowPublisherAction(publisherId: string) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    throw new UnauthorizedError(\"يرجى تسجيل الدخول لمتابعة الناشر\");\n  }\n\n  if (user.id === publisherId) {\n    throw new ValidationError(\"لا يمكنك متابعة حسابك الشخصي\");\n  }\n\n  const publisher = await db.user.findUnique({\n    where: { id: publisherId },\n    select: { id: true, name: true, followersCount: true },\n  });\n\n  if (!publisher) {\n    throw new NotFoundError(\"الناشر غير موجود\");\n  }\n\n  const result = await db.$transaction(async (tx) => {\n    const existing = await tx.publisherFollow.findUnique({\n      where: {\n        followerId_publisherId: {\n          followerId: user.id,\n          publisherId,\n        },\n      },\n    });\n\n    if (existing) {\n      await tx.publisherFollow.delete({ where: { id: existing.id } });\n      const nextCount = Math.max(0, (publisher.followersCount || 0) - 1);\n      await tx.user.update({\n        where: { id: publisherId },\n        data: { followersCount: nextCount },\n      });\n      return { isFollowing: false, followersCount: nextCount };\n    } else {\n      await tx.publisherFollow.create({\n        data: {\n          followerId: user.id,\n          publisherId,\n        },\n      });\n      const nextCount = (publisher.followersCount || 0) + 1;\n      await tx.user.update({\n        where: { id: publisherId },\n        data: { followersCount: nextCount },\n      });\n\n      const followerUser = await tx.user.findUnique({\n        where: { id: user.id },\n        select: { name: true },\n      });\n\n      await tx.notification.create({\n        data: {\n          userId: publisherId,\n          title: \"متابع جديد لحسابك في المسند\",\n          message: `بدأ (${followerUser?.name || \"أحد الأعضاء\"}) بمتابعة منشوراتك التربوية.`,\n          link: `/publisher/${user.id}`,\n        },\n      });\n\n      return { isFollowing: true, followersCount: nextCount };\n    }\n  });\n\n  revalidatePath(`/publisher/${publisherId}`);\n  revalidatePath(\"/profile\");\n  return result;\n}\n\nexport async function toggleFavoritePublisherAction(publisherId: string) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    throw new UnauthorizedError(\"يرجى تسجيل الدخول لإضافة الناشر إلى المفضلة\");\n  }\n\n  if (user.id === publisherId) {\n    throw new ValidationError(\"لا يمكنك إضافة حسابك الشخصي إلى المفضلة\");\n  }\n\n  const publisher = await db.user.findUnique({\n    where: { id: publisherId },\n    select: { id: true, favoritedByCount: true },\n  });\n\n  if (!publisher) {\n    throw new NotFoundError(\"الناشر غير موجود\");\n  }\n\n  const result = await db.$transaction(async (tx) => {\n    const existing = await tx.favoritePublisher.findUnique({\n      where: {\n        userId_publisherId: {\n          userId: user.id,\n          publisherId,\n        },\n      },\n    });\n\n    if (existing) {\n      await tx.favoritePublisher.delete({ where: { id: existing.id } });\n      const nextCount = Math.max(0, (publisher.favoritedByCount || 0) - 1);\n      await tx.user.update({\n        where: { id: publisherId },\n        data: { favoritedByCount: nextCount },\n      });\n      return { isFavoritedPublisher: false, favoritedByCount: nextCount };\n    } else {\n      await tx.favoritePublisher.create({\n        data: {\n          userId: user.id,\n          publisherId,\n        },\n      });\n      const nextCount = (publisher.favoritedByCount || 0) + 1;\n      await tx.user.update({\n        where: { id: publisherId },\n        data: { favoritedByCount: nextCount },\n      });\n      return { isFavoritedPublisher: true, favoritedByCount: nextCount };\n    }\n  });\n\n  revalidatePath(`/publisher/${publisherId}`);\n  revalidatePath(\"/profile\");\n  return result;\n}\n\nexport async function getPublicPublisherProfileData(publisherId: string) {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user: viewerAuth },\n  } = await supabase.auth.getUser();\n\n  let viewerRole: string | null = null;\n  if (viewerAuth) {\n    const vUser = await db.user.findUnique({\n      where: { id: viewerAuth.id },\n      select: { role: true },\n    });\n    viewerRole = vUser?.role || null;\n  }\n\n  const publisher = await db.user.findUnique({\n    where: { id: publisherId },\n    select: {\n      id: true,\n      name: true,\n      avatarUrl: true,\n      role: true,\n      school: true,\n      bio: true,\n      followersCount: true,\n      favoritedByCount: true,\n      createdAt: true,\n    },\n  });\n\n  if (!publisher) {\n    throw new NotFoundError(\"الناشر غير موجود\");\n  }\n\n  const audienceFilter =\n    viewerAuth?.id === publisherId ? {} : buildAudienceVisibilityFilter(viewerRole);\n\n  const [worksheets, followRecord, favRecord] = await Promise.all([\n    db.worksheet.findMany({\n      where: {\n        uploadedBy: publisherId,\n        status: WorksheetStatus.PUBLISHED,\n        ...audienceFilter,\n      },\n      select: publicWorksheetSelect,\n      orderBy: [{ isEndorsed: \"desc\" }, { createdAt: \"desc\" }],\n    }),\n    viewerAuth\n      ? db.publisherFollow.findUnique({\n          where: {\n            followerId_publisherId: {\n              followerId: viewerAuth.id,\n              publisherId,\n            },\n          },\n        })\n      : Promise.resolve(null),\n    viewerAuth\n      ? db.favoritePublisher.findUnique({\n          where: {\n            userId_publisherId: {\n              userId: viewerAuth.id,\n              publisherId,\n            },\n          },\n        })\n      : Promise.resolve(null),\n  ]);\n\n  const totalDownloads = worksheets.reduce((acc, w) => acc + (w.downloadCount || 0), 0);\n  const endorsedCount = worksheets.filter((w) => w.isEndorsed).length;\n\n  return {\n    publisher,\n    worksheets,\n    stats: {\n      worksheetsCount: worksheets.length,\n      endorsedCount,\n      totalDownloads,\n      followersCount: publisher.followersCount ?? 0,\n      favoritedByCount: publisher.favoritedByCount ?? 0,\n    },\n    viewerState: {\n      isOwnProfile: viewerAuth?.id === publisherId,\n      isFollowing: Boolean(followRecord),\n      isFavoritedPublisher: Boolean(favRecord),\n    },\n  };\n}\n\nexport async function getMyFavoritePublishersAction() {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) return [];\n\n  const records = await db.favoritePublisher.findMany({\n    where: { userId: user.id },\n    include: {\n      publisher: {\n        select: {\n          id: true,\n          name: true,\n          role: true,\n          school: true,\n          bio: true,\n          avatarUrl: true,\n          followersCount: true,\n          favoritedByCount: true,\n          _count: { select: { worksheets: true } },\n        },\n      },\n    },\n    orderBy: { createdAt: \"desc\" },\n  });\n\n  return records.map((r) => r.publisher);\n}\n",
  "src/app/api/notifications/route.ts": "/**\n * GET   /api/notifications — Fetch current user's notifications & unread count\n * PATCH /api/notifications — Mark all (or single) notifications as read\n */\n\nimport { NextRequest } from \"next/server\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { db } from \"@/lib/db\";\nimport { successResponse, errorResponse } from \"@/lib/utils/api-response\";\nimport { UnauthorizedError } from \"@/lib/utils/errors\";\n\nexport async function GET() {\n  try {\n    const supabase = await createSupabaseServerClient();\n    const {\n      data: { user },\n    } = await supabase.auth.getUser();\n\n    if (!user) {\n      throw new UnauthorizedError();\n    }\n\n    const [notifications, unreadCount] = await Promise.all([\n      db.notification.findMany({\n        where: { userId: user.id },\n        orderBy: { createdAt: \"desc\" },\n        take: 20,\n      }),\n      db.notification.count({\n        where: { userId: user.id, isRead: false },\n      }),\n    ]);\n\n    return successResponse({ notifications, unreadCount });\n  } catch (error) {\n    return errorResponse(error);\n  }\n}\n\nexport async function PATCH(request: NextRequest) {\n  try {\n    const supabase = await createSupabaseServerClient();\n    const {\n      data: { user },\n    } = await supabase.auth.getUser();\n\n    if (!user) {\n      throw new UnauthorizedError();\n    }\n\n    const body = await request.json().catch(() => ({}));\n    const notificationId = body?.id as string | undefined;\n\n    if (notificationId) {\n      await db.notification.updateMany({\n        where: { id: notificationId, userId: user.id },\n        data: { isRead: true },\n      });\n    } else {\n      await db.notification.updateMany({\n        where: { userId: user.id, isRead: false },\n        data: { isRead: true },\n      });\n    }\n\n    return successResponse({ markedRead: true });\n  } catch (error) {\n    return errorResponse(error);\n  }\n}\n",
  "src/actions/admin.actions.ts": "\"use server\";\n\nimport { revalidatePath } from \"next/cache\";\nimport { db } from \"@/lib/db\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { deleteFile } from \"@/services/storage.service\";\nimport {\n  UnauthorizedError,\n  ForbiddenError,\n  NotFoundError,\n} from \"@/lib/utils/errors\";\nimport { Role, WorksheetStatus, ProfileEditStatus, Prisma } from \"@prisma/client\";\n\nasync function requireAdmin() {\n  const supabase = await createSupabaseServerClient();\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    throw new UnauthorizedError(\"يرجى تسجيل الدخول أولاً\");\n  }\n\n  const dbUser = await db.user.findUnique({\n    where: { id: user.id },\n    select: { id: true, role: true, name: true, email: true },\n  });\n\n  if (!dbUser || dbUser.role !== Role.ADMIN) {\n    throw new ForbiddenError(\"غير مصرح لك بالدخول إلى لوحة تحكم المشرفين\");\n  }\n\n  return dbUser;\n}\n\nexport async function getAdminDashboardData() {\n  const admin = await requireAdmin();\n\n  const [\n    totalWorksheets,\n    publishedWorksheets,\n    draftWorksheets,\n    archivedWorksheets,\n    endorsedWorksheets,\n    totalUsers,\n    pendingProfileEditsCount,\n    totalDownloadsAgg,\n    worksheets,\n    teachers,\n    pendingProfileUsers,\n  ] = await Promise.all([\n    db.worksheet.count(),\n    db.worksheet.count({ where: { status: WorksheetStatus.PUBLISHED } }),\n    db.worksheet.count({ where: { status: WorksheetStatus.DRAFT } }),\n    db.worksheet.count({ where: { status: WorksheetStatus.ARCHIVED } }),\n    db.worksheet.count({ where: { isEndorsed: true } }),\n    db.user.count(),\n    db.user.count({ where: { profileEditStatus: ProfileEditStatus.PENDING } }),\n    db.worksheet.aggregate({ _sum: { downloadCount: true } }),\n    db.worksheet.findMany({\n      orderBy: [{ isEndorsed: \"desc\" }, { createdAt: \"desc\" }],\n      take: 100,\n      include: {\n        grade: { select: { id: true, nameAr: true } },\n        subject: { select: { id: true, nameAr: true, color: true } },\n        category: { select: { id: true, nameAr: true } },\n        uploader: {\n          select: { id: true, name: true, email: true, school: true, role: true },\n        },\n      },\n    }),\n    db.user.findMany({\n      orderBy: { createdAt: \"desc\" },\n      take: 100,\n      include: {\n        _count: {\n          select: {\n            worksheets: true,\n            downloads: true,\n            favorites: true,\n          },\n        },\n      },\n    }),\n    db.user.findMany({\n      where: { profileEditStatus: ProfileEditStatus.PENDING },\n      orderBy: { updatedAt: \"desc\" },\n      select: {\n        id: true,\n        name: true,\n        email: true,\n        role: true,\n        school: true,\n        bio: true,\n        avatarUrl: true,\n        pendingProfileData: true,\n        updatedAt: true,\n      },\n    }),\n  ]);\n\n  return {\n    currentAdminId: admin.id,\n    stats: {\n      totalWorksheets,\n      publishedWorksheets,\n      draftWorksheets,\n      archivedWorksheets,\n      endorsedWorksheets,\n      totalUsers,\n      pendingProfileEditsCount,\n      totalDownloads: totalDownloadsAgg._sum.downloadCount ?? 0,\n    },\n    worksheets,\n    teachers,\n    pendingProfileUsers,\n  };\n}\n\nexport async function approveProfileEditAdminAction(targetUserId: string) {\n  await requireAdmin();\n\n  const user = await db.user.findUnique({\n    where: { id: targetUserId },\n    select: {\n      id: true,\n      name: true,\n      school: true,\n      bio: true,\n      avatarUrl: true,\n      pendingProfileData: true,\n    },\n  });\n\n  if (!user || !user.pendingProfileData) {\n    throw new NotFoundError(\"لا يوجد طلب تعديل معلق لهذا المستخدم\");\n  }\n\n  const pending = user.pendingProfileData as {\n    name?: string;\n    school?: string | null;\n    bio?: string | null;\n    avatarUrl?: string | null;\n  };\n\n  const updated = await db.user.update({\n    where: { id: targetUserId },\n    data: {\n      name: pending.name || user.name,\n      school: pending.school !== undefined ? pending.school : user.school,\n      bio: pending.bio !== undefined ? pending.bio : user.bio,\n      avatarUrl: pending.avatarUrl !== undefined ? pending.avatarUrl : user.avatarUrl,\n      profileEditStatus: ProfileEditStatus.APPROVED,\n      pendingProfileData: Prisma.DbNull,\n    },\n  });\n\n  await db.notification.create({\n    data: {\n      userId: targetUserId,\n      title: \"✅ تمت الموافقة على تعديل ملفك الشخصي\",\n      message: \"اعتمد المشرف العام التعديلات الجديدة على ملفك الشخصي وأصبحت ظاهرة لجميع الأعضاء في منصة المسند.\",\n      link: `/publisher/${targetUserId}`,\n    },\n  });\n\n  revalidatePath(\"/admin/dashboard\");\n  revalidatePath(\"/profile\");\n  revalidatePath(`/publisher/${targetUserId}`);\n  return updated;\n}\n\nexport async function rejectProfileEditAdminAction(targetUserId: string) {\n  await requireAdmin();\n\n  const updated = await db.user.update({\n    where: { id: targetUserId },\n    data: {\n      profileEditStatus: ProfileEditStatus.REJECTED,\n      pendingProfileData: Prisma.DbNull,\n    },\n  });\n\n  await db.notification.create({\n    data: {\n      userId: targetUserId,\n      title: \"تنبيه بخصوص طلب تعديل الملف الشخصي\",\n      message: \"تعذر اعتماد التعديلات المقترحة على ملفك الشخصي من قِبل الإدارة. يرجى التأكد من دقة البيانات الرسمية والمحاولة مجدداً.\",\n      link: \"/profile?tab=edit\",\n    },\n  });\n\n  revalidatePath(\"/admin/dashboard\");\n  revalidatePath(\"/profile\");\n  return updated;\n}\n\nexport async function updateWorksheetStatusAdminAction(\n  worksheetId: string,\n  status: WorksheetStatus\n) {\n  await requireAdmin();\n\n  const existing = await db.worksheet.findUnique({\n    where: { id: worksheetId },\n    select: { id: true },\n  });\n\n  if (!existing) {\n    throw new NotFoundError(\"ورقة العمل غير موجودة\");\n  }\n\n  const updated = await db.worksheet.update({\n    where: { id: worksheetId },\n    data: { status },\n    select: { id: true, status: true },\n  });\n\n  revalidatePath(\"/admin/dashboard\");\n  revalidatePath(\"/browse\");\n  revalidatePath(\"/\");\n  revalidatePath(`/worksheet/${worksheetId}`);\n\n  return updated;\n}\n\nexport async function deleteWorksheetAdminAction(worksheetId: string) {\n  await requireAdmin();\n\n  const existing = await db.worksheet.findUnique({\n    where: { id: worksheetId },\n    select: { id: true, fileUrl: true },\n  });\n\n  if (!existing) {\n    throw new NotFoundError(\"ورقة العمل غير موجودة\");\n  }\n\n  await deleteFile(existing.fileUrl);\n  await db.worksheet.delete({\n    where: { id: worksheetId },\n  });\n\n  revalidatePath(\"/admin/dashboard\");\n  revalidatePath(\"/browse\");\n  revalidatePath(\"/\");\n\n  return { deleted: true, id: worksheetId };\n}\n\nexport async function updateUserRoleAdminAction(\n  targetUserId: string,\n  newRole: Role\n) {\n  const admin = await requireAdmin();\n\n  if (admin.id === targetUserId && newRole !== Role.ADMIN) {\n    throw new ForbiddenError(\"لا يمكنك إلغاء صلاحية المشرف عن حسابك الشخصي الحالي\");\n  }\n\n  const updatedUser = await db.user.update({\n    where: { id: targetUserId },\n    data: { role: newRole },\n    select: { id: true, role: true, name: true },\n  });\n\n  revalidatePath(\"/admin/dashboard\");\n  return updatedUser;\n}\n",
  "src/context/AppPreferencesContext.tsx": "\"use client\";\n\n/**\n * Global Theme (Light / Dark) & Trilingual (AR / FR / EN) Preferences Context — Al-Musnad (المسند) v3.0\n *\n * Updates:\n * - Rebranded completely to \"المسند\" (Al-Musnad).\n * - Removed \"الاختيار الأول / الثاني / الثالث / الرابع\" from role badges.\n * - Removed all \"مجاني / free / gratuitement\" wording.\n */\n\nimport React, { createContext, useContext, useState, useEffect } from \"react\";\nimport type { AccountRoleOption } from \"@/types/api\";\n\nexport type Locale = \"ar\" | \"fr\" | \"en\";\nexport type ThemeMode = \"light\" | \"dark\";\n\nexport interface RoleMetadataTranslations {\n  title: string;\n  subtitle: string;\n  badge: string;\n  orgLabel: string;\n  orgPlaceholder: string;\n  nameLabel: string;\n  namePlaceholder: string;\n}\n\nexport interface Dictionary {\n  dir: \"rtl\" | \"ltr\";\n  brandName: string;\n  brandTagline: string;\n  nav: {\n    home: string;\n    browse: string;\n    upload: string;\n    adminPanel: string;\n    login: string;\n    register: string;\n    logout: string;\n    profile: string;\n    editProfile: string;\n    subscriptions: string;\n    settings: string;\n    notifications: string;\n    markAllRead: string;\n    noNotifications: string;\n    themeLight: string;\n    themeDark: string;\n    language: string;\n  };\n  authModal: {\n    loginTitle: string;\n    loginSubtitle: string;\n    registerTitle: string;\n    registerSubtitle: string;\n    switchToRegister: string;\n    switchToLogin: string;\n    close: string;\n    continueBtn: string;\n    changeRoleBtn: string;\n  };\n  roles: Record<AccountRoleOption, RoleMetadataTranslations>;\n  authForm: {\n    emailLabel: string;\n    passwordLabel: string;\n    passwordHint: string;\n    submitLogin: string;\n    submitRegister: string;\n    googleContinue: string;\n    orDivider: string;\n    inspectorNote: string;\n    haveCodeQuestion: string;\n    activateCodeLink: string;\n  };\n}\n\nexport const DICTIONARIES: Record<Locale, Dictionary> = {\n  ar: {\n    dir: \"rtl\",\n    brandName: \"المسند\",\n    brandTagline: \"المنصة التربوية والبيداغوجية المعتمدة\",\n    nav: {\n      home: \"الرئيسية\",\n      browse: \"بنك المنشورات\",\n      upload: \"نشر وثيقة\",\n      adminPanel: \"لوحة المشرف\",\n      login: \"تسجيل الدخول\",\n      register: \"إنشاء حساب\",\n      logout: \"تسجيل الخروج\",\n      profile: \"الملف الشخصي ومساحتي\",\n      editProfile: \"تعديل الملف الشخصي\",\n      subscriptions: \"الاشتراكات\",\n      settings: \"الإعدادات\",\n      notifications: \"التنبيهات والإشعارات\",\n      markAllRead: \"تحديد الكل كمقروء\",\n      noNotifications: \"لا توجد تنبيهات جديدة حالياً\",\n      themeLight: \"الوضع النهاري\",\n      themeDark: \"الوضع الليلي\",\n      language: \"اللغة\",\n    },\n    authModal: {\n      loginTitle: \"اختر صفتك لتسجيل الدخول إلى المسند\",\n      loginSubtitle: \"حدد فضاءك التربوي للوصول المباشر إلى المنشورات وأدوات العمل المخصصة لك\",\n      registerTitle: \"اختر نوع الحساب الذي تريد إنشاءه في المسند\",\n      registerSubtitle: \"انضم إلى منظومة المسند التربوية بحساب مخصص يناسب صفتك ومهامك\",\n      switchToRegister: \"ليس لديك حساب؟ انتقل إلى إنشاء حساب جديد\",\n      switchToLogin: \"لديك حساب بالفعل؟ انتقل إلى تسجيل الدخول\",\n      close: \"إغلاق النافذة\",\n      continueBtn: \"متابعة\",\n      changeRoleBtn: \"تغيير نوع الحساب\",\n    },\n    roles: {\n      INSTITUTION: {\n        title: \"حساب مؤسسة تربوية\",\n        subtitle: \"للمدارس، المعاهد، والمؤسسات التعليمية لإدارة ونشر الرصيد البيداغوجي والوثائق المدرسية.\",\n        badge: \"فضاء المؤسسات\",\n        orgLabel: \"اسم المؤسسة التربوية / المدرسة *\",\n        orgPlaceholder: \"مثال: المدرسة الابتدائية حي النور\",\n        nameLabel: \"اسم المدير أو المنسق البيداغوجي *\",\n        namePlaceholder: \"مثال: أ. عبد الرحمن بن صالح\",\n      },\n      INSPECTOR: {\n        title: \"حساب متفقد تربوي\",\n        subtitle: \"للمتفقدين والموجهين البيداغوجيين لاعتماد صحة المنشورات علمياً وتربوياً وتقديم التوجيهات الرسمية.\",\n        badge: \"فضاء المتفقدين\",\n        orgLabel: \"الدائرة التفقدية / المندوبية الجهوية *\",\n        orgPlaceholder: \"مثال: دائرة التفقد التربوي بقفصة\",\n        nameLabel: \"الاسم الكامل للمتفقد *\",\n        namePlaceholder: \"مثال: د. محمد الهادي\",\n      },\n      TEACHER: {\n        title: \"حساب معلم\",\n        subtitle: \"للمعلمين والأساتذة لنشر المذكرات، التمارين، وإصلاح الاختبارات مع التحكم الكامل في جمهور النشر.\",\n        badge: \"فضاء المعلمين\",\n        orgLabel: \"المؤسسة التربوية التي تدرّس بها (اختياري)\",\n        orgPlaceholder: \"مثال: مدرسة الأمل الابتدائية\",\n        nameLabel: \"الاسم الكامل للمعلم *\",\n        namePlaceholder: \"مثال: أ. سارة المنصوري\",\n      },\n      STUDENT: {\n        title: \"حساب تلميذ\",\n        subtitle: \"للتلاميذ وأولياء الأمور لتصفح وتحميل التمارين، المراجعات، والأنشطة الموجهة للتلاميذ.\",\n        badge: \"فضاء التلاميذ\",\n        orgLabel: \"المدرسة / الصف الدراسي (اختياري)\",\n        orgPlaceholder: \"مثال: الصف الخامس ابتدائي\",\n        nameLabel: \"اسم التلميذ *\",\n        namePlaceholder: \"مثال: ياسين التونسي\",\n      },\n    },\n    authForm: {\n      emailLabel: \"البريد الإلكتروني *\",\n      passwordLabel: \"كلمة المرور *\",\n      passwordHint: \"8 أحرف على الأقل\",\n      submitLogin: \"تسجيل الدخول الآن\",\n      submitRegister: \"إنشاء الحساب الآن\",\n      googleContinue: \"المتابعة باستخدام حساب Google\",\n      orDivider: \"أو\",\n      inspectorNote: \"ملاحظة للمتفقدين: بعد إنشاء الحساب، يمنحك المشرف العام كود التفعيل لتوثيق الشارة الذهبية واعتماد المنشورات.\",\n      haveCodeQuestion: \"هل لديك كود تفعيل متفقد؟\",\n      activateCodeLink: \"تفعيل الكود الآن\",\n    },\n  },\n\n  fr: {\n    dir: \"ltr\",\n    brandName: \"Al-Musnad\",\n    brandTagline: \"Plateforme Pédagogique Certifiée\",\n    nav: {\n      home: \"Accueil\",\n      browse: \"Catalogue\",\n      upload: \"Publier\",\n      adminPanel: \"Administration\",\n      login: \"Connexion\",\n      register: \"Créer un compte\",\n      logout: \"Déconnexion\",\n      profile: \"Mon Espace & Profil\",\n      editProfile: \"Modifier le profil\",\n      subscriptions: \"Abonnements\",\n      settings: \"Paramètres\",\n      notifications: \"Notifications\",\n      markAllRead: \"Tout marquer comme lu\",\n      noNotifications: \"Aucune notification pour le moment\",\n      themeLight: \"Mode Clair\",\n      themeDark: \"Mode Sombre\",\n      language: \"Langue\",\n    },\n    authModal: {\n      loginTitle: \"Choisissez votre profil de connexion sur Al-Musnad\",\n      loginSubtitle: \"Accédez à votre espace pédagogique dédié\",\n      registerTitle: \"Choisissez le type de compte à créer\",\n      registerSubtitle: \"Rejoignez Al-Musnad selon votre rôle dans l'écosystème éducatif\",\n      switchToRegister: \"Pas encore de compte ? Créer un nouveau compte\",\n      switchToLogin: \"Déjà inscrit ? Se connecter à mon compte\",\n      close: \"Fermer\",\n      continueBtn: \"Continuer\",\n      changeRoleBtn: \"Changer le type de compte\",\n    },\n    roles: {\n      INSTITUTION: {\n        title: \"Espace Établissement\",\n        subtitle: \"Pour les écoles et institutions éducatives afin de gérer et diffuser leurs ressources officielles.\",\n        badge: \"Établissement\",\n        orgLabel: \"Nom de l'établissement scolaire *\",\n        orgPlaceholder: \"Ex: École Primaire Al-Amal\",\n        nameLabel: \"Nom du directeur / responsable *\",\n        namePlaceholder: \"Ex: M. Karim Ben Ali\",\n      },\n      INSPECTOR: {\n        title: \"Espace Inspecteur\",\n        subtitle: \"Pour les inspecteurs pédagogiques afin d'homologuer les publications et publier des directives.\",\n        badge: \"Inspecteur\",\n        orgLabel: \"Circonscription / Délégation régionale *\",\n        orgPlaceholder: \"Ex: Circonscription pédagogique de Gafsa\",\n        nameLabel: \"Nom complet de l'inspecteur *\",\n        namePlaceholder: \"Ex: Dr. Mohamed Hedi\",\n      },\n      TEACHER: {\n        title: \"Espace Enseignant\",\n        subtitle: \"Pour les enseignants afin de publier des exercices ou des corrigés réservés aux enseignants.\",\n        badge: \"Enseignant\",\n        orgLabel: \"École d'affectation (optionnel)\",\n        orgPlaceholder: \"Ex: École Primaire Ibn Khaldoun\",\n        nameLabel: \"Nom complet de l'enseignant *\",\n        namePlaceholder: \"Ex: Mme. Sarra Mansouri\",\n      },\n      STUDENT: {\n        title: \"Espace Élève\",\n        subtitle: \"Pour les élèves et parents afin de consulter et télécharger les fiches d'exercices et révisions.\",\n        badge: \"Élève\",\n        orgLabel: \"École / Niveau scolaire (optionnel)\",\n        orgPlaceholder: \"Ex: 5ème année primaire\",\n        nameLabel: \"Nom complet de l'élève *\",\n        namePlaceholder: \"Ex: Yassine Tounsi\",\n      },\n    },\n    authForm: {\n      emailLabel: \"Adresse e-mail *\",\n      passwordLabel: \"Mot de passe *\",\n      passwordHint: \"8 caractères minimum\",\n      submitLogin: \"Se connecter\",\n      submitRegister: \"Créer mon compte\",\n      googleContinue: \"Continuer avec Google\",\n      orDivider: \"OU\",\n      inspectorNote: \"Note aux inspecteurs : Après l'inscription, un code d'activation vous sera fourni par l'administration.\",\n      haveCodeQuestion: \"Vous avez déjà un code inspecteur ?\",\n      activateCodeLink: \"Activer mon code\",\n    },\n  },\n\n  en: {\n    dir: \"ltr\",\n    brandName: \"Al-Musnad\",\n    brandTagline: \"Certified Educational & Pedagogical Platform\",\n    nav: {\n      home: \"Home\",\n      browse: \"Publications\",\n      upload: \"Publish\",\n      adminPanel: \"Admin Panel\",\n      login: \"Log In\",\n      register: \"Sign Up\",\n      logout: \"Sign Out\",\n      profile: \"My Workspace & Profile\",\n      editProfile: \"Edit Profile\",\n      subscriptions: \"Subscriptions\",\n      settings: \"Settings\",\n      notifications: \"Notifications\",\n      markAllRead: \"Mark all read\",\n      noNotifications: \"No new notifications\",\n      themeLight: \"Light Mode\",\n      themeDark: \"Dark Mode\",\n      language: \"Language\",\n    },\n    authModal: {\n      loginTitle: \"Select Your Account Type on Al-Musnad\",\n      loginSubtitle: \"Access your tailored educational workspace\",\n      registerTitle: \"Select the Account Type to Create\",\n      registerSubtitle: \"Join Al-Musnad with a role tailored to your educational mission\",\n      switchToRegister: \"Don't have an account? Create a new account\",\n      switchToLogin: \"Already have an account? Log in here\",\n      close: \"Close\",\n      continueBtn: \"Continue\",\n      changeRoleBtn: \"Change Account Type\",\n    },\n    roles: {\n      INSTITUTION: {\n        title: \"Educational Institution\",\n        subtitle: \"For schools and educational centers to manage and publish institutional curricula and worksheets.\",\n        badge: \"Institution\",\n        orgLabel: \"Official Institution / School Name *\",\n        orgPlaceholder: \"e.g., Al-Noor Primary School\",\n        nameLabel: \"Principal or Coordinator Name *\",\n        namePlaceholder: \"e.g., Mr. Abdulrahman Saleh\",\n      },\n      INSPECTOR: {\n        title: \"Pedagogical Inspector\",\n        subtitle: \"For certified inspectors to endorse scientific & pedagogical accuracy and pin official directives.\",\n        badge: \"Inspector\",\n        orgLabel: \"Inspection District / Regional Directorate *\",\n        orgPlaceholder: \"e.g., Primary Inspection District\",\n        nameLabel: \"Inspector Full Name *\",\n        namePlaceholder: \"e.g., Dr. Mohamed Hedi\",\n      },\n      TEACHER: {\n        title: \"Teacher Account\",\n        subtitle: \"For teachers to publish worksheets for students or answer keys exclusively for fellow teachers.\",\n        badge: \"Teacher\",\n        orgLabel: \"School Name (Optional)\",\n        orgPlaceholder: \"e.g., Al-Amal Primary School\",\n        nameLabel: \"Teacher Full Name *\",\n        namePlaceholder: \"e.g., Ms. Sara Mansouri\",\n      },\n      STUDENT: {\n        title: \"Student Account\",\n        subtitle: \"For students and parents to browse, preview, and download worksheets and study materials.\",\n        badge: \"Student\",\n        orgLabel: \"School / Grade Level (Optional)\",\n        orgPlaceholder: \"e.g., Grade 5 Primary\",\n        nameLabel: \"Student Full Name *\",\n        namePlaceholder: \"e.g., Yassine Tounsi\",\n      },\n    },\n    authForm: {\n      emailLabel: \"Email Address *\",\n      passwordLabel: \"Password *\",\n      passwordHint: \"At least 8 characters\",\n      submitLogin: \"Log In Now\",\n      submitRegister: \"Create Account\",\n      googleContinue: \"Continue with Google\",\n      orDivider: \"OR\",\n      inspectorNote: \"Inspector Note: After signing up, the administrator will issue your activation code to unlock the verified badge.\",\n      haveCodeQuestion: \"Already have an inspector code?\",\n      activateCodeLink: \"Activate Code\",\n    },\n  },\n};\n\ninterface AppPreferencesContextValue {\n  locale: Locale;\n  setLocale: (loc: Locale) => void;\n  theme: ThemeMode;\n  toggleTheme: () => void;\n  setTheme: (theme: ThemeMode) => void;\n  t: Dictionary;\n  authModalMode: \"login\" | \"register\" | null;\n  openAuthModal: (mode: \"login\" | \"register\") => void;\n  closeAuthModal: () => void;\n}\n\nconst AppPreferencesContext = createContext<AppPreferencesContextValue | undefined>(undefined);\n\nexport function AppPreferencesProvider({ children }: { children: React.ReactNode }) {\n  const [locale, setLocaleState] = useState<Locale>(\"ar\");\n  const [theme, setThemeState] = useState<ThemeMode>(\"light\");\n  const [authModalMode, setAuthModalMode] = useState<\"login\" | \"register\" | null>(null);\n\n  useEffect(() => {\n    try {\n      const savedLocale = localStorage.getItem(\"musnad_locale\") as Locale | null;\n      if (savedLocale && (savedLocale === \"ar\" || savedLocale === \"fr\" || savedLocale === \"en\")) {\n        setLocaleState(savedLocale);\n      }\n\n      const savedTheme = localStorage.getItem(\"musnad_theme\") as ThemeMode | null;\n      if (savedTheme === \"dark\" || savedTheme === \"light\") {\n        setThemeState(savedTheme);\n      } else if (window.matchMedia(\"(prefers-color-scheme: dark)\").matches) {\n        setThemeState(\"dark\");\n      }\n    } catch {\n      // ignore storage errors\n    }\n  }, []);\n\n  useEffect(() => {\n    const dict = DICTIONARIES[locale];\n    document.documentElement.lang = locale;\n    document.documentElement.dir = dict.dir;\n    document.body.style.direction = dict.dir;\n    document.body.style.textAlign = dict.dir === \"rtl\" ? \"right\" : \"left\";\n    try {\n      localStorage.setItem(\"musnad_locale\", locale);\n    } catch {\n      // ignore\n    }\n  }, [locale]);\n\n  useEffect(() => {\n    const root = document.documentElement;\n    if (theme === \"dark\") {\n      root.classList.add(\"dark\");\n    } else {\n      root.classList.remove(\"dark\");\n    }\n    try {\n      localStorage.setItem(\"musnad_theme\", theme);\n    } catch {\n      // ignore\n    }\n  }, [theme]);\n\n  const setLocale = (loc: Locale) => setLocaleState(loc);\n  const setTheme = (mode: ThemeMode) => setThemeState(mode);\n  const toggleTheme = () => setThemeState((prev) => (prev === \"light\" ? \"dark\" : \"light\"));\n\n  const openAuthModal = (mode: \"login\" | \"register\") => setAuthModalMode(mode);\n  const closeAuthModal = () => setAuthModalMode(null);\n\n  return (\n    <AppPreferencesContext.Provider\n      value={{\n        locale,\n        setLocale,\n        theme,\n        toggleTheme,\n        setTheme,\n        t: DICTIONARIES[locale],\n        authModalMode,\n        openAuthModal,\n        closeAuthModal,\n      }}\n    >\n      {children}\n    </AppPreferencesContext.Provider>\n  );\n}\n\nexport function useAppPreferences() {\n  const ctx = useContext(AppPreferencesContext);\n  if (!ctx) {\n    throw new Error(\"useAppPreferences must be used inside AppPreferencesProvider\");\n  }\n  return ctx;\n}\n",
  "src/components/auth/AuthRoleModal.tsx": "\"use client\";\n\n/**\n * Full-Screen 4-Role Selection Overlay — Al-Musnad (المسند) v3.0\n *\n * Clean badges without \"Option 1 / 2 / 3 / 4\" wording, rebranded with \"م\" logo for Al-Musnad.\n */\n\nimport React, { useEffect } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  Building2,\n  ShieldCheck,\n  BookOpen,\n  GraduationCap,\n  X,\n  ArrowLeft,\n  ArrowRight,\n  Sparkles,\n} from \"lucide-react\";\nimport { useAppPreferences } from \"@/context/AppPreferencesContext\";\nimport type { AccountRoleOption } from \"@/types/api\";\n\nexport interface RoleOptionVisual {\n  role: AccountRoleOption;\n  icon: React.ComponentType<{ className?: string }>;\n  gradient: string;\n  borderHover: string;\n  badgeStyle: string;\n  iconBg: string;\n}\n\nexport const ROLE_VISUAL_CARDS: RoleOptionVisual[] = [\n  {\n    role: \"INSTITUTION\",\n    icon: Building2,\n    gradient: \"from-indigo-600 to-violet-700\",\n    borderHover: \"hover:border-indigo-500 dark:hover:border-indigo-400\",\n    badgeStyle:\n      \"bg-indigo-50 text-indigo-700 border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-300 dark:border-indigo-800\",\n    iconBg: \"bg-indigo-600 text-white shadow-indigo-500/25\",\n  },\n  {\n    role: \"INSPECTOR\",\n    icon: ShieldCheck,\n    gradient: \"from-amber-500 to-orange-600\",\n    borderHover: \"hover:border-amber-500 dark:hover:border-amber-400\",\n    badgeStyle:\n      \"bg-amber-50 text-amber-800 border-amber-200 dark:bg-amber-950/60 dark:text-amber-300 dark:border-amber-800\",\n    iconBg: \"bg-gradient-to-br from-amber-500 to-amber-600 text-white shadow-amber-500/25\",\n  },\n  {\n    role: \"TEACHER\",\n    icon: BookOpen,\n    gradient: \"from-blue-600 to-cyan-600\",\n    borderHover: \"hover:border-blue-500 dark:hover:border-blue-400\",\n    badgeStyle:\n      \"bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-950/60 dark:text-blue-300 dark:border-blue-800\",\n    iconBg: \"bg-blue-600 text-white shadow-blue-500/25\",\n  },\n  {\n    role: \"STUDENT\",\n    icon: GraduationCap,\n    gradient: \"from-emerald-600 to-teal-600\",\n    borderHover: \"hover:border-emerald-500 dark:hover:border-emerald-400\",\n    badgeStyle:\n      \"bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-950/60 dark:text-emerald-300 dark:border-emerald-800\",\n    iconBg: \"bg-emerald-600 text-white shadow-emerald-500/25\",\n  },\n];\n\nexport default function AuthRoleModal() {\n  const router = useRouter();\n  const { authModalMode, closeAuthModal, openAuthModal, t } = useAppPreferences();\n\n  useEffect(() => {\n    if (!authModalMode) return;\n    const handleKeyDown = (e: KeyboardEvent) => {\n      if (e.key === \"Escape\") closeAuthModal();\n    };\n    window.addEventListener(\"keydown\", handleKeyDown);\n    return () => window.removeEventListener(\"keydown\", handleKeyDown);\n  }, [authModalMode, closeAuthModal]);\n\n  if (!authModalMode) return null;\n\n  const isLogin = authModalMode === \"login\";\n  const ArrowIcon = t.dir === \"rtl\" ? ArrowLeft : ArrowRight;\n\n  const handleSelectRole = (role: AccountRoleOption) => {\n    const targetPath = isLogin ? `/login?role=${role}` : `/register?role=${role}`;\n    closeAuthModal();\n    router.push(targetPath);\n  };\n\n  return (\n    <div\n      className=\"fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-xl flex flex-col justify-between overflow-y-auto animate-fadeIn p-4 sm:p-8\"\n      dir={t.dir}\n    >\n      {/* Top Bar */}\n      <div className=\"max-w-7xl w-full mx-auto flex items-center justify-between py-2\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center font-black text-xl shadow-lg shadow-blue-500/30\">\n            م\n          </div>\n          <div>\n            <span className=\"text-lg font-extrabold text-white block leading-none\">\n              {t.brandName}\n            </span>\n            <span className=\"text-xs text-slate-400\">{t.brandTagline}</span>\n          </div>\n        </div>\n\n        <button\n          type=\"button\"\n          onClick={closeAuthModal}\n          className=\"inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-white/10 hover:bg-white/20 text-white text-xs font-bold border border-white/15 transition cursor-pointer\"\n        >\n          <span>{t.authModal.close}</span>\n          <X className=\"w-4 h-4\" />\n        </button>\n      </div>\n\n      {/* Center Content: 4 Full-Screen Portals */}\n      <div className=\"max-w-7xl w-full mx-auto my-auto py-8 space-y-8\">\n        <div className=\"text-center space-y-3 max-w-2xl mx-auto\">\n          <div className=\"inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-200 text-xs font-bold\">\n            <Sparkles className=\"w-3.5 h-3.5\" />\n            <span>{isLogin ? t.nav.login : t.nav.register}</span>\n          </div>\n          <h2 className=\"text-2xl sm:text-4xl font-black text-white tracking-tight\">\n            {isLogin ? t.authModal.loginTitle : t.authModal.registerTitle}\n          </h2>\n          <p className=\"text-sm sm:text-base text-slate-300 leading-relaxed\">\n            {isLogin ? t.authModal.loginSubtitle : t.authModal.registerSubtitle}\n          </p>\n        </div>\n\n        <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5\">\n          {ROLE_VISUAL_CARDS.map((card) => {\n            const Icon = card.icon;\n            const roleText = t.roles[card.role];\n\n            return (\n              <button\n                key={card.role}\n                type=\"button\"\n                onClick={() => handleSelectRole(card.role)}\n                className={`group relative text-start bg-white dark:bg-slate-900 border-2 border-slate-200/90 dark:border-slate-800 ${card.borderHover} rounded-3xl p-6 sm:p-7 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1.5 flex flex-col justify-between cursor-pointer overflow-hidden`}\n              >\n                <div\n                  className={`absolute top-0 inset-x-0 h-2 bg-gradient-to-r ${card.gradient}`}\n                />\n\n                <div className=\"space-y-5 pt-2\">\n                  <div className=\"flex items-center justify-between gap-2\">\n                    <span\n                      className={`px-3 py-1 rounded-full text-[11px] font-extrabold border ${card.badgeStyle}`}\n                    >\n                      {roleText.badge}\n                    </span>\n                    <div\n                      className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg ${card.iconBg} group-hover:scale-110 transition-transform`}\n                    >\n                      <Icon className=\"w-6 h-6\" />\n                    </div>\n                  </div>\n\n                  <div className=\"space-y-2\">\n                    <h3 className=\"text-xl font-black text-slate-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors\">\n                      {roleText.title}\n                    </h3>\n                    <p className=\"text-xs sm:text-sm text-slate-600 dark:text-slate-400 leading-relaxed\">\n                      {roleText.subtitle}\n                    </p>\n                  </div>\n                </div>\n\n                <div className=\"pt-6 mt-6 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between text-xs font-extrabold text-slate-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400\">\n                  <span>\n                    {isLogin ? t.nav.login : t.nav.register} ({roleText.title})\n                  </span>\n                  <ArrowIcon className=\"w-4 h-4 transform group-hover:translate-x-1 rtl:group-hover:-translate-x-1 transition-transform\" />\n                </div>\n              </button>\n            );\n          })}\n        </div>\n\n        <div className=\"text-center pt-2\">\n          <button\n            type=\"button\"\n            onClick={() => openAuthModal(isLogin ? \"register\" : \"login\")}\n            className=\"text-sm font-bold text-blue-300 hover:text-white underline underline-offset-4 transition cursor-pointer\"\n          >\n            {isLogin ? t.authModal.switchToRegister : t.authModal.switchToLogin}\n          </button>\n        </div>\n      </div>\n\n      <div className=\"text-center text-xs text-slate-500\">\n        © {new Date().getFullYear()} {t.brandName}\n      </div>\n    </div>\n  );\n}\n",
  "src/components/layout/Navbar.tsx": "\"use client\";\n\n/**\n * Upgraded Navigation Bar — Al-Musnad (المسند) v3.0\n *\n * Features:\n * 1. Rebranded to \"المسند\" (Al-Musnad) with \"م\" emblem.\n * 2. Notification Bell (`Bell`) right beside the user profile avatar with unread counter\n *    and interactive dropdown list.\n * 3. User Profile Dropdown Menu when clicking the profile avatar/name containing:\n *    - الملف الشخصي ومساحتي (/profile)\n *    - ملفي العام كناشر (/publisher/[id])\n *    - تعديل الملف الشخصي (/profile?tab=edit)\n *    - الاشتراكات (/profile?tab=subscriptions)\n *    - الإعدادات (/profile?tab=settings)\n *    - تسجيل الخروج\n * 4. Theme Toggle (Light / Dark) & Language Switcher (AR / FR / EN).\n */\n\nimport React, { useState, useEffect } from \"react\";\nimport Link from \"next/link\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport {\n  ShieldCheck,\n  Sun,\n  Moon,\n  Globe,\n  LogIn,\n  UserPlus,\n  Upload,\n  Menu,\n  X,\n  Bell,\n  UserCog,\n  CreditCard,\n  Settings,\n  LogOut,\n  User as UserIcon,\n  ChevronDown,\n  ExternalLink,\n  CheckCheck,\n} from \"lucide-react\";\nimport InspectorBadge from \"@/components/ui/InspectorBadge\";\nimport { createSupabaseBrowserClient } from \"@/lib/supabase/client\";\nimport { useAppPreferences, type Locale } from \"@/context/AppPreferencesContext\";\nimport type { NotificationItem } from \"@/types/api\";\n\ninterface UserProfile {\n  id: string;\n  name: string;\n  email: string;\n  avatarUrl: string | null;\n  role?: string;\n}\n\nconst LANGUAGES: { code: Locale; label: string; short: string }[] = [\n  { code: \"ar\", label: \"العربية\", short: \"AR\" },\n  { code: \"fr\", label: \"Français\", short: \"FR\" },\n  { code: \"en\", label: \"English\", short: \"EN\" },\n];\n\nexport default function Navbar() {\n  const pathname = usePathname();\n  const router = useRouter();\n  const supabase = createSupabaseBrowserClient();\n  const { locale, setLocale, theme, toggleTheme, t, openAuthModal } =\n    useAppPreferences();\n\n  const [user, setUser] = useState<UserProfile | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);\n  const [langMenuOpen, setLangMenuOpen] = useState(false);\n  const [profileMenuOpen, setProfileMenuOpen] = useState(false);\n  const [notifMenuOpen, setNotifMenuOpen] = useState(false);\n\n  const [notifications, setNotifications] = useState<NotificationItem[]>([]);\n  const [unreadCount, setUnreadCount] = useState<number>(0);\n\n  const fetchNotifications = async () => {\n    try {\n      const res = await fetch(\"/api/notifications\", { cache: \"no-store\" });\n      if (res.ok) {\n        const json = await res.json();\n        if (json.success && json.data) {\n          setNotifications(json.data.notifications || []);\n          setUnreadCount(json.data.unreadCount || 0);\n        }\n      }\n    } catch {\n      // ignore offline\n    }\n  };\n\n  useEffect(() => {\n    let isMounted = true;\n\n    async function checkUser() {\n      try {\n        const {\n          data: { session },\n        } = await supabase.auth.getSession();\n\n        if (session?.user && isMounted) {\n          const initialUser: UserProfile = {\n            id: session.user.id,\n            name:\n              session.user.user_metadata?.name ||\n              session.user.email?.split(\"@\")[0] ||\n              \"عضو المسند\",\n            email: session.user.email || \"\",\n            avatarUrl: session.user.user_metadata?.avatar_url || null,\n          };\n\n          try {\n            const res = await fetch(\"/api/auth/me\", { cache: \"no-store\" });\n            if (res.ok) {\n              const json = await res.json();\n              if (json.success && json.data) {\n                initialUser.role = json.data.role;\n                initialUser.name = json.data.name || initialUser.name;\n                initialUser.avatarUrl =\n                  json.data.avatarUrl || initialUser.avatarUrl;\n              }\n            }\n          } catch {\n            // fallback\n          }\n\n          if (isMounted) {\n            setUser(initialUser);\n            fetchNotifications();\n          }\n        } else if (isMounted) {\n          setUser(null);\n        }\n      } catch (err) {\n        console.error(\"Auth status error:\", err);\n      } finally {\n        if (isMounted) setLoading(false);\n      }\n    }\n\n    checkUser();\n\n    const {\n      data: { subscription },\n    } = supabase.auth.onAuthStateChange(async (_event, session) => {\n      if (session?.user) {\n        const updatedUser: UserProfile = {\n          id: session.user.id,\n          name:\n            session.user.user_metadata?.name ||\n            session.user.email?.split(\"@\")[0] ||\n            \"عضو المسند\",\n          email: session.user.email || \"\",\n          avatarUrl: session.user.user_metadata?.avatar_url || null,\n        };\n\n        try {\n          const res = await fetch(\"/api/auth/me\", { cache: \"no-store\" });\n          if (res.ok) {\n            const json = await res.json();\n            if (json.success && json.data) {\n              updatedUser.role = json.data.role;\n              updatedUser.name = json.data.name || updatedUser.name;\n            }\n          }\n        } catch {\n          // ignore\n        }\n\n        setUser(updatedUser);\n        fetchNotifications();\n      } else {\n        setUser(null);\n        setNotifications([]);\n        setUnreadCount(0);\n      }\n    });\n\n    return () => {\n      isMounted = false;\n      subscription.unsubscribe();\n    };\n  }, []);\n\n  const handleMarkAllNotificationsRead = async () => {\n    try {\n      await fetch(\"/api/notifications\", {\n        method: \"PATCH\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({}),\n      });\n      setUnreadCount(0);\n      setNotifications((prev) => prev.map((n) => ({ ...n, isRead: true })));\n    } catch {\n      // ignore\n    }\n  };\n\n  const handleSignOut = async () => {\n    setProfileMenuOpen(false);\n    await supabase.auth.signOut();\n    setUser(null);\n    router.push(\"/login\");\n    router.refresh();\n  };\n\n  const navLinks = [\n    { label: t.nav.home, href: \"/\" },\n    { label: t.nav.browse, href: \"/browse\" },\n  ];\n\n  return (\n    <header className=\"sticky top-0 z-50 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 transition-colors\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n        <div className=\"flex items-center justify-between h-18 py-3 gap-4\">\n          {/* Brand Logo: المسند */}\n          <div className=\"flex items-center gap-6\">\n            <Link href=\"/\" className=\"flex items-center gap-2.5 group shrink-0\">\n              <div className=\"w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center font-black text-xl shadow-md shadow-blue-500/20 group-hover:scale-105 transition-transform\">\n                م\n              </div>\n              <div className=\"flex flex-col\">\n                <span className=\"text-lg sm:text-xl font-extrabold text-slate-900 dark:text-white tracking-tight group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors\">\n                  {t.brandName}\n                </span>\n                <span className=\"text-[10px] text-slate-400 dark:text-slate-500 font-medium\">\n                  {t.brandTagline}\n                </span>\n              </div>\n            </Link>\n\n            <nav className=\"hidden lg:flex items-center gap-1\">\n              {navLinks.map((link) => {\n                const isActive = pathname === link.href;\n                return (\n                  <Link\n                    key={link.href}\n                    href={link.href}\n                    className={`px-3.5 py-2 rounded-xl text-sm font-bold transition ${\n                      isActive\n                        ? \"text-blue-600 dark:text-blue-400 bg-blue-50/80 dark:bg-blue-950/50\"\n                        : \"text-slate-600 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-800/60\"\n                    }`}\n                  >\n                    {link.label}\n                  </Link>\n                );\n              })}\n            </nav>\n          </div>\n\n          {/* Action Area */}\n          <div className=\"hidden md:flex items-center gap-2.5\">\n            {/* Language Switcher */}\n            <div className=\"relative\">\n              <button\n                type=\"button\"\n                onClick={() => setLangMenuOpen((prev) => !prev)}\n                className=\"flex items-center gap-1.5 px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-xs font-extrabold text-slate-700 dark:text-slate-200 transition cursor-pointer\"\n                title={t.nav.language}\n              >\n                <Globe className=\"w-4 h-4 text-blue-600 dark:text-blue-400\" />\n                <span>{locale.toUpperCase()}</span>\n              </button>\n\n              {langMenuOpen && (\n                <>\n                  <div\n                    className=\"fixed inset-0 z-10\"\n                    onClick={() => setLangMenuOpen(false)}\n                  />\n                  <div className=\"absolute top-full mt-2 end-0 z-20 w-36 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-xl p-1.5 space-y-1\">\n                    {LANGUAGES.map((lang) => (\n                      <button\n                        key={lang.code}\n                        type=\"button\"\n                        onClick={() => {\n                          setLocale(lang.code);\n                          setLangMenuOpen(false);\n                        }}\n                        className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-bold transition cursor-pointer ${\n                          locale === lang.code\n                            ? \"bg-blue-600 text-white\"\n                            : \"text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800\"\n                        }`}\n                      >\n                        <span>{lang.label}</span>\n                        <span className=\"text-[10px] opacity-80\">\n                          {lang.short}\n                        </span>\n                      </button>\n                    ))}\n                  </div>\n                </>\n              )}\n            </div>\n\n            {/* Theme Toggle */}\n            <button\n              type=\"button\"\n              onClick={toggleTheme}\n              className=\"p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-700 dark:text-amber-300 transition cursor-pointer\"\n              title={theme === \"light\" ? t.nav.themeDark : t.nav.themeLight}\n              aria-label=\"Toggle Theme\"\n            >\n              {theme === \"light\" ? (\n                <Moon className=\"w-4 h-4 text-slate-700\" />\n              ) : (\n                <Sun className=\"w-4 h-4 text-amber-400\" />\n              )}\n            </button>\n\n            <div className=\"h-5 w-px bg-slate-200 dark:bg-slate-700 mx-0.5\" />\n\n            {/* Authenticated vs Unauthenticated */}\n            {!loading && user ? (\n              <div className=\"flex items-center gap-2.5\">\n                <InspectorBadge role={user.role} size=\"md\" />\n\n                {user.role === \"ADMIN\" && (\n                  <Link\n                    href=\"/admin/dashboard\"\n                    className=\"flex items-center gap-1.5 px-3 py-2 rounded-xl bg-purple-50 dark:bg-purple-950/60 hover:bg-purple-100 text-purple-700 dark:text-purple-300 font-bold text-xs border border-purple-200 dark:border-purple-800 transition\"\n                  >\n                    <ShieldCheck className=\"w-4 h-4\" />\n                    <span>{t.nav.adminPanel}</span>\n                  </Link>\n                )}\n\n                {user.role !== \"STUDENT\" && (\n                  <Link\n                    href=\"/upload\"\n                    className=\"flex items-center gap-1.5 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold px-3.5 py-2.5 rounded-xl shadow-sm transition\"\n                  >\n                    <Upload className=\"w-3.5 h-3.5\" />\n                    <span>{t.nav.upload}</span>\n                  </Link>\n                )}\n\n                {/* Notification Bell Icon right next to Profile Avatar */}\n                <div className=\"relative\">\n                  <button\n                    type=\"button\"\n                    onClick={() => {\n                      setNotifMenuOpen((prev) => !prev);\n                      setProfileMenuOpen(false);\n                      if (!notifMenuOpen) fetchNotifications();\n                    }}\n                    className=\"relative p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 transition cursor-pointer\"\n                    title={t.nav.notifications}\n                  >\n                    <Bell className=\"w-4 h-4\" />\n                    {unreadCount > 0 && (\n                      <span className=\"absolute -top-1 -end-1 min-w-[18px] h-[18px] px-1 rounded-full bg-rose-600 text-white text-[10px] font-black flex items-center justify-center shadow-sm\">\n                        {unreadCount > 9 ? \"9+\" : unreadCount}\n                      </span>\n                    )}\n                  </button>\n\n                  {notifMenuOpen && (\n                    <>\n                      <div\n                        className=\"fixed inset-0 z-10\"\n                        onClick={() => setNotifMenuOpen(false)}\n                      />\n                      <div className=\"absolute top-full mt-2 end-0 z-20 w-80 sm:w-96 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden\">\n                        <div className=\"px-4 py-3 bg-slate-50 dark:bg-slate-800/80 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between\">\n                          <span className=\"text-xs font-extrabold text-slate-900 dark:text-white flex items-center gap-1.5\">\n                            <Bell className=\"w-3.5 h-3.5 text-blue-600\" />\n                            <span>{t.nav.notifications}</span>\n                          </span>\n                          {unreadCount > 0 && (\n                            <button\n                              type=\"button\"\n                              onClick={handleMarkAllNotificationsRead}\n                              className=\"text-[11px] font-bold text-blue-600 hover:underline inline-flex items-center gap-1 cursor-pointer\"\n                            >\n                              <CheckCheck className=\"w-3.5 h-3.5\" />\n                              <span>{t.nav.markAllRead}</span>\n                            </button>\n                          )}\n                        </div>\n\n                        <div className=\"max-h-80 overflow-y-auto divide-y divide-slate-100 dark:divide-slate-800\">\n                          {notifications.length === 0 ? (\n                            <div className=\"py-8 px-4 text-center text-xs text-slate-400\">\n                              {t.nav.noNotifications}\n                            </div>\n                          ) : (\n                            notifications.map((n) => (\n                              <div\n                                key={n.id}\n                                onClick={() => {\n                                  setNotifMenuOpen(false);\n                                  if (n.link) router.push(n.link);\n                                }}\n                                className={`p-3.5 text-start transition cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 ${\n                                  !n.isRead\n                                    ? \"bg-blue-50/40 dark:bg-blue-950/20\"\n                                    : \"\"\n                                }`}\n                              >\n                                <div className=\"flex items-start justify-between gap-2\">\n                                  <p className=\"text-xs font-bold text-slate-900 dark:text-white\">\n                                    {n.title}\n                                  </p>\n                                  {!n.isRead && (\n                                    <span className=\"w-2 h-2 rounded-full bg-blue-600 shrink-0 mt-1\" />\n                                  )}\n                                </div>\n                                <p className=\"text-[11px] text-slate-600 dark:text-slate-400 mt-1 leading-relaxed\">\n                                  {n.message}\n                                </p>\n                              </div>\n                            ))\n                          )}\n                        </div>\n                      </div>\n                    </>\n                  )}\n                </div>\n\n                {/* User Profile Avatar & Rich Dropdown Menu */}\n                <div className=\"relative\">\n                  <button\n                    type=\"button\"\n                    onClick={() => {\n                      setProfileMenuOpen((prev) => !prev);\n                      setNotifMenuOpen(false);\n                    }}\n                    className=\"flex items-center gap-2 px-2.5 py-1.5 rounded-xl bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 transition border border-slate-200 dark:border-slate-700 cursor-pointer\"\n                  >\n                    {user.avatarUrl ? (\n                      <img\n                        src={user.avatarUrl}\n                        alt={user.name}\n                        className=\"w-8 h-8 rounded-full object-cover border border-slate-200\"\n                      />\n                    ) : (\n                      <div className=\"w-8 h-8 rounded-full bg-blue-600 text-white font-bold text-xs flex items-center justify-center\">\n                        {user.name.charAt(0)}\n                      </div>\n                    )}\n                    <span className=\"text-xs font-bold text-slate-800 dark:text-slate-100 max-w-[110px] truncate\">\n                      {user.name}\n                    </span>\n                    <ChevronDown className=\"w-3.5 h-3.5 text-slate-400\" />\n                  </button>\n\n                  {profileMenuOpen && (\n                    <>\n                      <div\n                        className=\"fixed inset-0 z-10\"\n                        onClick={() => setProfileMenuOpen(false)}\n                      />\n                      <div className=\"absolute top-full mt-2 end-0 z-20 w-64 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl p-2 space-y-1\">\n                        <div className=\"px-3 py-2.5 border-b border-slate-100 dark:border-slate-800 mb-1\">\n                          <p className=\"text-xs font-extrabold text-slate-900 dark:text-white truncate\">\n                            {user.name}\n                          </p>\n                          <p className=\"text-[11px] text-slate-400 truncate\">\n                            {user.email}\n                          </p>\n                        </div>\n\n                        <Link\n                          href=\"/profile\"\n                          onClick={() => setProfileMenuOpen(false)}\n                          className=\"flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition\"\n                        >\n                          <UserIcon className=\"w-4 h-4 text-blue-600\" />\n                          <span>{t.nav.profile}</span>\n                        </Link>\n\n                        <Link\n                          href={`/publisher/${user.id}`}\n                          onClick={() => setProfileMenuOpen(false)}\n                          className=\"flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition\"\n                        >\n                          <ExternalLink className=\"w-4 h-4 text-indigo-600\" />\n                          <span>صفحتي العامة كناشر</span>\n                        </Link>\n\n                        <Link\n                          href=\"/profile?tab=edit\"\n                          onClick={() => setProfileMenuOpen(false)}\n                          className=\"flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition\"\n                        >\n                          <UserCog className=\"w-4 h-4 text-emerald-600\" />\n                          <span>{t.nav.editProfile}</span>\n                        </Link>\n\n                        <Link\n                          href=\"/profile?tab=subscriptions\"\n                          onClick={() => setProfileMenuOpen(false)}\n                          className=\"flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition\"\n                        >\n                          <CreditCard className=\"w-4 h-4 text-amber-600\" />\n                          <span>{t.nav.subscriptions}</span>\n                        </Link>\n\n                        <Link\n                          href=\"/profile?tab=settings\"\n                          onClick={() => setProfileMenuOpen(false)}\n                          className=\"flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition\"\n                        >\n                          <Settings className=\"w-4 h-4 text-slate-500\" />\n                          <span>{t.nav.settings}</span>\n                        </Link>\n\n                        <div className=\"pt-1 mt-1 border-t border-slate-100 dark:border-slate-800\">\n                          <button\n                            type=\"button\"\n                            onClick={handleSignOut}\n                            className=\"w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/40 transition cursor-pointer\"\n                          >\n                            <LogOut className=\"w-4 h-4\" />\n                            <span>{t.nav.logout}</span>\n                          </button>\n                        </div>\n                      </div>\n                    </>\n                  )}\n                </div>\n              </div>\n            ) : !loading ? (\n              <div className=\"flex items-center gap-2\">\n                <button\n                  type=\"button\"\n                  onClick={() => openAuthModal(\"login\")}\n                  className=\"inline-flex items-center gap-2 px-4 py-2.5 text-sm font-bold text-slate-700 dark:text-slate-200 hover:text-blue-600 dark:hover:text-blue-400 bg-slate-100/80 dark:bg-slate-800 hover:bg-slate-200/70 dark:hover:bg-slate-700 rounded-xl transition cursor-pointer\"\n                >\n                  <LogIn className=\"w-4 h-4\" />\n                  <span>{t.nav.login}</span>\n                </button>\n\n                <button\n                  type=\"button\"\n                  onClick={() => openAuthModal(\"register\")}\n                  className=\"inline-flex items-center gap-2 px-4 py-2.5 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 active:bg-blue-800 rounded-xl shadow-sm shadow-blue-500/20 transition cursor-pointer\"\n                >\n                  <UserPlus className=\"w-4 h-4\" />\n                  <span>{t.nav.register}</span>\n                </button>\n              </div>\n            ) : null}\n          </div>\n\n          {/* Mobile Controls */}\n          <div className=\"flex items-center gap-2 md:hidden\">\n            <button\n              type=\"button\"\n              onClick={() =>\n                setLocale(\n                  locale === \"ar\" ? \"fr\" : locale === \"fr\" ? \"en\" : \"ar\"\n                )\n              }\n              className=\"px-2.5 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs font-extrabold text-slate-700 dark:text-slate-200\"\n            >\n              {locale.toUpperCase()}\n            </button>\n\n            <button\n              type=\"button\"\n              onClick={toggleTheme}\n              className=\"p-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-700 dark:text-amber-300\"\n            >\n              {theme === \"light\" ? (\n                <Moon className=\"w-4 h-4\" />\n              ) : (\n                <Sun className=\"w-4 h-4\" />\n              )}\n            </button>\n\n            <button\n              type=\"button\"\n              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}\n              className=\"p-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition\"\n              aria-label=\"Menu\"\n            >\n              {mobileMenuOpen ? (\n                <X className=\"w-6 h-6\" />\n              ) : (\n                <Menu className=\"w-6 h-6\" />\n              )}\n            </button>\n          </div>\n        </div>\n      </div>\n\n      {/* Mobile Drawer */}\n      {mobileMenuOpen && (\n        <div className=\"md:hidden border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 px-4 pt-3 pb-6 space-y-3\">\n          <nav className=\"flex flex-col gap-1\">\n            {navLinks.map((link) => (\n              <Link\n                key={link.href}\n                href={link.href}\n                onClick={() => setMobileMenuOpen(false)}\n                className=\"px-3 py-2 rounded-lg text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800\"\n              >\n                {link.label}\n              </Link>\n            ))}\n          </nav>\n\n          <div className=\"pt-3 border-t border-slate-100 dark:border-slate-800 space-y-1.5\">\n            {user ? (\n              <>\n                <Link\n                  href=\"/profile\"\n                  onClick={() => setMobileMenuOpen(false)}\n                  className=\"block px-3 py-2 rounded-lg text-sm font-bold text-slate-800 dark:text-slate-100\"\n                >\n                  {t.nav.profile} ({user.name})\n                </Link>\n                <Link\n                  href=\"/profile?tab=edit\"\n                  onClick={() => setMobileMenuOpen(false)}\n                  className=\"block px-3 py-2 rounded-lg text-sm font-bold text-slate-700 dark:text-slate-200\"\n                >\n                  {t.nav.editProfile}\n                </Link>\n                <Link\n                  href=\"/profile?tab=subscriptions\"\n                  onClick={() => setMobileMenuOpen(false)}\n                  className=\"block px-3 py-2 rounded-lg text-sm font-bold text-slate-700 dark:text-slate-200\"\n                >\n                  {t.nav.subscriptions}\n                </Link>\n                <Link\n                  href=\"/profile?tab=settings\"\n                  onClick={() => setMobileMenuOpen(false)}\n                  className=\"block px-3 py-2 rounded-lg text-sm font-bold text-slate-700 dark:text-slate-200\"\n                >\n                  {t.nav.settings}\n                </Link>\n                {user.role !== \"STUDENT\" && (\n                  <Link\n                    href=\"/upload\"\n                    onClick={() => setMobileMenuOpen(false)}\n                    className=\"block px-3 py-2 rounded-lg text-sm font-bold text-blue-600 dark:text-blue-400\"\n                  >\n                    + {t.nav.upload}\n                  </Link>\n                )}\n                <button\n                  type=\"button\"\n                  onClick={() => {\n                    setMobileMenuOpen(false);\n                    handleSignOut();\n                  }}\n                  className=\"w-full text-start px-3 py-2 text-sm font-bold text-red-600 rounded-lg\"\n                >\n                  {t.nav.logout}\n                </button>\n              </>\n            ) : (\n              <div className=\"grid grid-cols-2 gap-2 pt-1\">\n                <button\n                  type=\"button\"\n                  onClick={() => {\n                    setMobileMenuOpen(false);\n                    openAuthModal(\"login\");\n                  }}\n                  className=\"py-2.5 text-sm font-bold text-slate-700 dark:text-slate-200 bg-slate-100 dark:bg-slate-800 rounded-xl\"\n                >\n                  {t.nav.login}\n                </button>\n                <button\n                  type=\"button\"\n                  onClick={() => {\n                    setMobileMenuOpen(false);\n                    openAuthModal(\"register\");\n                  }}\n                  className=\"py-2.5 text-sm font-bold text-white bg-blue-600 rounded-xl\"\n                >\n                  {t.nav.register}\n                </button>\n              </div>\n            )}\n          </div>\n        </div>\n      )}\n    </header>\n  );\n}\n",
  "src/app/layout.tsx": "import type { Metadata } from \"next\";\nimport { Cairo } from \"next/font/google\";\nimport Navbar from \"@/components/layout/Navbar\";\nimport AuthRoleModal from \"@/components/auth/AuthRoleModal\";\nimport { AppPreferencesProvider } from \"@/context/AppPreferencesContext\";\nimport \"./globals.css\";\n\nconst cairo = Cairo({\n  subsets: [\"arabic\", \"latin\"],\n  weight: [\"300\", \"400\", \"500\", \"600\", \"700\", \"800\"],\n  variable: \"--font-cairo\",\n  display: \"swap\",\n});\n\nexport const metadata: Metadata = {\n  title: \"المسند | المنصة التربوية والبيداغوجية المعتمدة\",\n  description:\n    \"منصة المسند للمؤسسات التربوية، المتفقدين، المعلمين، والتلاميذ لتصفح، مشاركة، اعتماد، وتحميل الأنشطة والوثائق البيداغوجية.\",\n};\n\nexport default function RootLayout({\n  children,\n}: Readonly<{\n  children: React.ReactNode;\n}>) {\n  return (\n    <html lang=\"ar\" dir=\"rtl\" className={cairo.variable} suppressHydrationWarning>\n      <body className=\"min-h-screen flex flex-col bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-50 font-cairo\">\n        <AppPreferencesProvider>\n          <Navbar />\n          <AuthRoleModal />\n          <main className=\"flex-1\">{children}</main>\n\n          <footer className=\"bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 py-10 mt-16\">\n            <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n              <div className=\"grid grid-cols-1 md:grid-cols-3 gap-8 mb-8\">\n                <div className=\"space-y-3\">\n                  <div className=\"flex items-center gap-2.5\">\n                    <div className=\"w-9 h-9 bg-blue-600 text-white rounded-xl flex items-center justify-center font-black text-lg shadow-sm\">\n                      م\n                    </div>\n                    <span className=\"text-xl font-extrabold text-slate-900 dark:text-white\">\n                      المسند (Al-Musnad)\n                    </span>\n                  </div>\n                  <p className=\"text-slate-500 text-sm leading-relaxed\">\n                    المنصة التربوية المتكاملة للمؤسسات التعليمية، المتفقدين، المعلمين، والتلاميذ لتبادل واعتماد الوثائق والأنشطة البيداغوجية.\n                  </p>\n                </div>\n\n                <div>\n                  <h4 className=\"font-bold text-slate-800 dark:text-slate-200 text-sm mb-3\">\n                    أقسام المنصة\n                  </h4>\n                  <ul className=\"space-y-2 text-sm text-slate-500\">\n                    <li>\n                      <a href=\"/\" className=\"hover:text-blue-600 transition\">\n                        الرئيسية\n                      </a>\n                    </li>\n                    <li>\n                      <a href=\"/browse\" className=\"hover:text-blue-600 transition\">\n                        بنك المنشورات\n                      </a>\n                    </li>\n                    <li>\n                      <a href=\"/upload\" className=\"hover:text-blue-600 transition\">\n                        نشر وثيقة جديدة\n                      </a>\n                    </li>\n                  </ul>\n                </div>\n\n                <div>\n                  <h4 className=\"font-bold text-slate-800 dark:text-slate-200 text-sm mb-3\">\n                    التواصل والاشتراكات\n                  </h4>\n                  <ul className=\"space-y-2 text-sm text-slate-500\">\n                    <li>\n                      <a href=\"/profile?tab=subscriptions\" className=\"hover:text-blue-600 transition\">\n                        باقات اشتراك المؤسسات والمعلمين\n                      </a>\n                    </li>\n                    <li>\n                      <span className=\"text-slate-400\">\n                        support@almusnad.edu\n                      </span>\n                    </li>\n                  </ul>\n                </div>\n              </div>\n\n              <div className=\"pt-6 border-t border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row items-center justify-between text-xs text-slate-400 gap-3\">\n                <p>© {new Date().getFullYear()} منصة المسند (Al-Musnad). جميع الحقوق محفوظة.</p>\n                <p>منصة تعليمية معتمدة للمؤسسات، المتفقدين، المعلمين، والتلاميذ.</p>\n              </div>\n            </div>\n          </footer>\n        </AppPreferencesProvider>\n      </body>\n    </html>\n  );\n}\n",
  "src/components/worksheets/WorksheetCard.tsx": "\"use client\";\n\n/**\n * Educational Activity / Worksheet Card — Al-Musnad (المسند) v3.0\n *\n * Upgrades:\n * 1. Displays prominent \"معتمد علمياً وبيداغوجياً\" badge when `worksheet.isEndorsed` is true.\n * 2. Displays Target Audience badge (`للمعلمين فقط - إصلاح/مذكرة`, `للمعلمين والتلاميذ`, `خاص بنفس الفئة`).\n * 3. Clickable publisher profile link (`/publisher/[uploadedBy]`) so members can visit the publisher's\n *    full profile, follow them, and add them to favorites.\n */\n\nimport React, { useState } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter } from \"next/navigation\";\nimport { BadgeCheck, Lock, Users } from \"lucide-react\";\nimport type { WorksheetWithRelations } from \"@/types/api\";\nimport InspectorBadge from \"@/components/ui/InspectorBadge\";\n\ninterface WorksheetCardProps {\n  worksheet: WorksheetWithRelations;\n}\n\nconst AUDIENCE_LABELS: Record<string, { label: string; isRestricted: boolean }> = {\n  TEACHERS_ONLY: { label: \"للمعلمين فقط (إصلاح / مذكرة)\", isRestricted: true },\n  SAME_ROLE_ONLY: { label: \"خاص بنفس فئة الناشر\", isRestricted: true },\n  INSTITUTIONS_ONLY: { label: \"خاص بالمؤسسات\", isRestricted: true },\n  TEACHERS_AND_STUDENTS: { label: \"للمعلمين والتلاميذ\", isRestricted: false },\n  ALL: { label: \"عام لجميع الفئات\", isRestricted: false },\n};\n\nexport default function WorksheetCard({ worksheet }: WorksheetCardProps) {\n  const router = useRouter();\n  const [favoriteCount, setFavoriteCount] = useState(\n    worksheet.favoriteCount ?? (worksheet as any).favoritesCount ?? 0\n  );\n  const [isFavorited, setIsFavorited] = useState(false);\n  const [isToggling, setIsToggling] = useState(false);\n\n  const title = worksheet.titleAr || worksheet.title;\n  const subjectColor = worksheet.subject?.color || \"#2563EB\";\n  const downloadCount =\n    worksheet.downloadCount ?? (worksheet as any).downloadsCount ?? 0;\n  const audienceInfo =\n    AUDIENCE_LABELS[worksheet.audience || \"TEACHERS_AND_STUDENTS\"] ||\n    AUDIENCE_LABELS.TEACHERS_AND_STUDENTS;\n\n  const handleQuickFavorite = async (e: React.MouseEvent) => {\n    e.preventDefault();\n    e.stopPropagation();\n\n    if (isToggling) return;\n\n    try {\n      setIsToggling(true);\n      const res = await fetch(`/api/worksheets/${worksheet.id}/favorite`, {\n        method: \"POST\",\n      });\n\n      if (res.status === 401) {\n        router.push(`/login?redirectTo=/worksheet/${worksheet.id}`);\n        return;\n      }\n\n      const json = await res.json();\n      if (json.success) {\n        setIsFavorited(json.data.isFavorited);\n        setFavoriteCount(json.data.favoriteCount);\n      }\n    } catch (err) {\n      console.error(\"Quick favorite error:\", err);\n    } finally {\n      setIsToggling(false);\n    }\n  };\n\n  return (\n    <div\n      className={`group bg-white dark:bg-slate-900 rounded-2xl border transition-all duration-200 flex flex-col justify-between overflow-hidden ${\n        worksheet.isEndorsed\n          ? \"border-2 border-amber-400 shadow-md shadow-amber-500/10\"\n          : \"border-slate-200/90 dark:border-slate-800 shadow-sm hover:shadow-md hover:border-slate-300\"\n      }`}\n    >\n      <div>\n        {/* Inspector Endorsement Top Ribbon */}\n        {worksheet.isEndorsed && (\n          <div className=\"bg-gradient-to-r from-amber-500 via-amber-600 to-orange-500 text-white px-3.5 py-1.5 text-[11px] font-extrabold flex items-center justify-between\">\n            <span className=\"flex items-center gap-1.5\">\n              <BadgeCheck className=\"w-4 h-4 shrink-0\" />\n              <span>معتمد علمياً وبيداغوجياً من المتفقد</span>\n            </span>\n            <span className=\"bg-white/20 px-2 py-0.5 rounded-full text-[10px]\">\n              صدارة المادة ★\n            </span>\n          </div>\n        )}\n\n        {/* Card Cover Banner */}\n        <Link\n          href={`/worksheet/${worksheet.id}`}\n          className=\"block relative overflow-hidden\"\n        >\n          {worksheet.thumbnailUrl ? (\n            <img\n              src={worksheet.thumbnailUrl}\n              alt={title}\n              className=\"w-full h-44 object-cover group-hover:scale-102 transition-transform duration-300\"\n            />\n          ) : (\n            <div\n              className=\"w-full h-40 flex flex-col justify-between p-4 relative text-white\"\n              style={{\n                background: `linear-gradient(135deg, ${subjectColor} 0%, #1e293b 100%)`,\n              }}\n            >\n              <div className=\"flex items-center justify-between\">\n                <span className=\"px-2.5 py-1 bg-black/25 backdrop-blur-sm rounded-lg text-xs font-semibold\">\n                  {worksheet.category?.nameAr || \"ورقة عمل\"}\n                </span>\n                <span className=\"text-xl\">📄</span>\n              </div>\n\n              <div className=\"font-extrabold text-base line-clamp-2 leading-snug drop-shadow-sm\">\n                {title}\n              </div>\n            </div>\n          )}\n\n          {/* Quick Favorite Button */}\n          <button\n            type=\"button\"\n            onClick={handleQuickFavorite}\n            disabled={isToggling}\n            className={`absolute top-3 left-3 w-9 h-9 rounded-full flex items-center justify-center backdrop-blur-md transition shadow-sm cursor-pointer ${\n              isFavorited\n                ? \"bg-white text-rose-600 shadow-rose-500/20\"\n                : \"bg-white/80 hover:bg-white text-slate-600 hover:text-rose-600\"\n            }`}\n            title={isFavorited ? \"إزالة من المفضلة\" : \"إضافة إلى المفضلة\"}\n          >\n            <span className=\"text-base leading-none\">\n              {isFavorited ? \"♥\" : \"♡\"}\n            </span>\n          </button>\n        </Link>\n\n        {/* Card Body */}\n        <div className=\"p-4 space-y-3\">\n          {/* Taxonomy & Audience Badges */}\n          <div className=\"flex flex-wrap items-center gap-1.5 text-xs\">\n            <span\n              className=\"px-2 py-0.5 rounded-md font-semibold text-white\"\n              style={{ backgroundColor: subjectColor }}\n            >\n              {worksheet.subject?.nameAr}\n            </span>\n            <span className=\"px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-semibold\">\n              {worksheet.grade?.nameAr}\n            </span>\n            <span\n              className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-md font-bold text-[10px] ${\n                audienceInfo.isRestricted\n                  ? \"bg-rose-50 text-rose-700 border border-rose-200 dark:bg-rose-950/50 dark:text-rose-300\"\n                  : \"bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-950/50 dark:text-emerald-300\"\n              }`}\n            >\n              {audienceInfo.isRestricted ? (\n                <Lock className=\"w-2.5 h-2.5\" />\n              ) : (\n                <Users className=\"w-2.5 h-2.5\" />\n              )}\n              <span>{audienceInfo.label}</span>\n            </span>\n          </div>\n\n          {/* Title */}\n          <Link href={`/worksheet/${worksheet.id}`} className=\"block\">\n            <h3 className=\"font-bold text-slate-900 dark:text-white text-sm hover:text-blue-600 transition line-clamp-2 leading-relaxed\">\n              {title}\n            </h3>\n          </Link>\n\n          {/* Description Snippet */}\n          <p className=\"text-xs text-slate-500 dark:text-slate-400 line-clamp-2 leading-relaxed\">\n            {worksheet.descriptionAr ||\n              worksheet.description ||\n              \"وثيقة تربوية منشورة عبر منصة المسند.\"}\n          </p>\n        </div>\n      </div>\n\n      {/* Card Footer: Clickable Publisher Profile Link & Counters */}\n      <div className=\"px-4 py-3 bg-slate-50/70 dark:bg-slate-800/50 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs text-slate-500\">\n        <Link\n          href={`/publisher/${worksheet.uploader?.id || worksheet.uploadedBy}`}\n          className=\"flex items-center gap-2 min-w-0 hover:text-blue-600 transition group/pub\"\n          title=\"عرض الملف الشخصي الكامل للناشر ومتابعته\"\n        >\n          {worksheet.uploader?.avatarUrl ? (\n            <img\n              src={worksheet.uploader.avatarUrl}\n              alt={worksheet.uploader.name}\n              className=\"w-6 h-6 rounded-full object-cover border border-slate-200\"\n            />\n          ) : (\n            <div className=\"w-6 h-6 rounded-full bg-blue-100 text-blue-700 font-bold text-[10px] flex items-center justify-center\">\n              {worksheet.uploader?.name\n                ? worksheet.uploader.name.charAt(0)\n                : \"م\"}\n            </div>\n          )}\n          <span className=\"truncate max-w-[105px] font-bold text-slate-700 dark:text-slate-200 group-hover/pub:text-blue-600 group-hover/pub:underline\">\n            {worksheet.uploader?.name || \"ناشر معتمد\"}\n          </span>\n          <InspectorBadge role={worksheet.uploader?.role} size=\"sm\" />\n        </Link>\n\n        <div className=\"flex items-center gap-3 font-semibold text-slate-400\">\n          <span className=\"flex items-center gap-1\" title=\"متوسط التقييم\">\n            <span className=\"text-amber-400\">★</span>\n            <span className=\"text-slate-600 dark:text-slate-300\">\n              {worksheet.ratingAvg > 0 ? worksheet.ratingAvg.toFixed(1) : \"جديد\"}\n            </span>\n          </span>\n          <span className=\"flex items-center gap-1\" title=\"عدد التحميلات\">\n            <span>⬇</span>\n            <span className=\"text-slate-600 dark:text-slate-300\">\n              {downloadCount}\n            </span>\n          </span>\n          <span className=\"flex items-center gap-1\" title=\"عدد التفضيلات\">\n            <span className=\"text-rose-500\">♥</span>\n            <span className=\"text-slate-600 dark:text-slate-300\">\n              {favoriteCount}\n            </span>\n          </span>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
  "src/components/worksheets/WorksheetDetailClient.tsx": "\"use client\";\n\n/**\n * Worksheet Detail Client — Al-Musnad (المسند) v3.0\n *\n * Upgrades:\n * 1. Inspector Endorsement Button (`toggleWorksheetEndorsementAction`):\n *    Allows logged-in Inspectors (`INSPECTOR` or `ADMIN`) to endorse/verify the scientific & pedagogical\n *    accuracy of the worksheet, boosting its rank to the top of its subject!\n * 2. Displays Target Audience badge & Endorsement certificate banner.\n * 3. Publisher Card links directly to `/publisher/[id]` with Follow & Favorite Publisher actions.\n */\n\nimport React, { useEffect, useState } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport Link from \"next/link\";\nimport {\n  Download,\n  Heart,\n  FileText,\n  User as UserIcon,\n  School,\n  Calendar,\n  ExternalLink,\n  ArrowRight,\n  Share2,\n  Check,\n  Loader2,\n  Tag,\n  Star,\n  BadgeCheck,\n  Lock,\n  Users,\n  UserPlus,\n} from \"lucide-react\";\nimport ReviewSection from \"@/components/worksheets/ReviewSection\";\nimport InspectorBadge from \"@/components/ui/InspectorBadge\";\nimport { toggleWorksheetEndorsementAction } from \"@/actions/inspector.actions\";\nimport type { WorksheetWithRelations, ApiResponse } from \"@/types\";\nimport type { DownloadUrlResult } from \"@/services/download.service\";\nimport type { ToggleFavoriteResult } from \"@/services/favorite.service\";\n\ninterface WorksheetDetailClientProps {\n  initialWorksheet: WorksheetWithRelations;\n}\n\nconst AUDIENCE_LABELS: Record<string, string> = {\n  TEACHERS_ONLY: \"خاص بالمعلمين والمتفقدين فقط (إصلاح / مذكرة)\",\n  SAME_ROLE_ONLY: \"خاص بنفس فئة الناشر فقط\",\n  INSTITUTIONS_ONLY: \"خاص بالمؤسسات التربوية فقط\",\n  TEACHERS_AND_STUDENTS: \"متاح للمعلمين والتلاميذ\",\n  ALL: \"متاح لجميع منتسبي المسند\",\n};\n\nexport default function WorksheetDetailClient({\n  initialWorksheet,\n}: WorksheetDetailClientProps) {\n  const router = useRouter();\n\n  const [worksheet] = useState<WorksheetWithRelations>(initialWorksheet);\n  const [isFavorited, setIsFavorited] = useState<boolean>(false);\n  const [favoriteCount, setFavoriteCount] = useState<number>(\n    initialWorksheet.favoriteCount\n  );\n  const [favLoading, setFavLoading] = useState<boolean>(false);\n\n  const [isEndorsed, setIsEndorsed] = useState<boolean>(\n    Boolean(initialWorksheet.isEndorsed)\n  );\n  const [endorseLoading, setEndorseLoading] = useState<boolean>(false);\n  const [viewerRole, setViewerRole] = useState<string | null>(null);\n\n  const [downloadCount, setDownloadCount] = useState<number>(\n    initialWorksheet.downloadCount\n  );\n  const [downloading, setDownloading] = useState<boolean>(false);\n  const [copied, setCopied] = useState<boolean>(false);\n\n  useEffect(() => {\n    let isMounted = true;\n    async function checkViewerState() {\n      try {\n        const [favRes, meRes] = await Promise.all([\n          fetch(\"/api/me/favorites\").catch(() => null),\n          fetch(\"/api/auth/me\").catch(() => null),\n        ]);\n\n        if (favRes && favRes.ok) {\n          const json = await favRes.json();\n          if (json.success && Array.isArray(json.data)) {\n            const favorited = json.data.some((f: any) => f.id === worksheet.id);\n            if (isMounted) setIsFavorited(favorited);\n          }\n        }\n\n        if (meRes && meRes.ok) {\n          const meJson = await meRes.json();\n          if (meJson.success && meJson.data?.role && isMounted) {\n            setViewerRole(meJson.data.role);\n          }\n        }\n      } catch {\n        // ignore\n      }\n    }\n\n    checkViewerState();\n    return () => {\n      isMounted = false;\n    };\n  }, [worksheet.id]);\n\n  const handleToggleEndorsement = async () => {\n    if (endorseLoading) return;\n    try {\n      setEndorseLoading(true);\n      const res = await toggleWorksheetEndorsementAction(worksheet.id);\n      setIsEndorsed(res.isEndorsed);\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"تعذر تحديث حالة الاعتماد\");\n    } finally {\n      setEndorseLoading(false);\n    }\n  };\n\n  const handleDownload = async () => {\n    try {\n      setDownloading(true);\n      const res = await fetch(`/api/worksheets/${worksheet.id}/download`);\n      if (res.status === 401) {\n        router.push(`/login?redirectTo=/worksheet/${worksheet.id}`);\n        return;\n      }\n\n      const json: ApiResponse<DownloadUrlResult> = await res.json();\n      if (!json.success) {\n        alert(json.error.message || \"فشل في استخراج رابط التحميل\");\n        return;\n      }\n\n      setDownloadCount((prev) => prev + 1);\n      window.open(json.data.downloadUrl, \"_blank\", \"noopener,noreferrer\");\n    } catch {\n      alert(\"حدث خطأ أثناء الاتصال بالخادم لتحميل الملف\");\n    } finally {\n      setDownloading(false);\n    }\n  };\n\n  const handleToggleFavorite = async () => {\n    if (favLoading) return;\n    try {\n      setFavLoading(true);\n      const res = await fetch(`/api/worksheets/${worksheet.id}/favorite`, {\n        method: \"POST\",\n      });\n\n      if (res.status === 401) {\n        router.push(`/login?redirectTo=/worksheet/${worksheet.id}`);\n        return;\n      }\n\n      const json: ApiResponse<ToggleFavoriteResult> = await res.json();\n      if (json.success) {\n        setIsFavorited(json.data.isFavorited);\n        setFavoriteCount(json.data.favoriteCount);\n      }\n    } catch {\n      alert(\"تعذر تحديث حالة المفضلة\");\n    } finally {\n      setFavLoading(false);\n    }\n  };\n\n  const handleShare = async () => {\n    try {\n      await navigator.clipboard.writeText(window.location.href);\n      setCopied(true);\n      setTimeout(() => setCopied(false), 2500);\n    } catch {\n      alert(\"تم نسخ الرابط: \" + window.location.href);\n    }\n  };\n\n  const formatFileSize = (bytes: number) => {\n    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} كيلوبايت`;\n    return `${(bytes / (1024 * 1024)).toFixed(2)} ميجابايت`;\n  };\n\n  const displayTitle = worksheet.titleAr || worksheet.title;\n  const displayDesc = worksheet.descriptionAr || worksheet.description;\n  const subjectColor = worksheet.subject?.color || \"#2563EB\";\n  const canEndorse = viewerRole === \"INSPECTOR\" || viewerRole === \"ADMIN\";\n\n  return (\n    <main className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8\" dir=\"rtl\">\n      {/* Breadcrumb */}\n      <nav className=\"flex items-center gap-2 text-sm text-slate-500 mb-6\">\n        <Link\n          href=\"/browse\"\n          className=\"hover:text-blue-600 inline-flex items-center gap-1\"\n        >\n          <ArrowRight className=\"w-4 h-4\" />\n          بنك المنشورات\n        </Link>\n        <span>/</span>\n        <span>{worksheet.grade?.nameAr || worksheet.grade?.name}</span>\n        <span>/</span>\n        <span className=\"font-semibold text-slate-800 dark:text-slate-200 truncate max-w-xs\">\n          {displayTitle}\n        </span>\n      </nav>\n\n      {/* Official Inspector Endorsement Banner */}\n      {isEndorsed && (\n        <div className=\"mb-6 p-4 rounded-2xl bg-gradient-to-r from-amber-500/15 via-amber-500/10 to-transparent border-2 border-amber-400 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\">\n          <div className=\"flex items-center gap-3\">\n            <div className=\"w-11 h-11 rounded-2xl bg-gradient-to-br from-amber-500 to-amber-600 text-white flex items-center justify-center shrink-0 shadow-sm\">\n              <BadgeCheck className=\"w-6 h-6\" />\n            </div>\n            <div>\n              <h2 className=\"text-sm font-black text-amber-900 dark:text-amber-300\">\n                منشور معتمد علمياً وبيداغوجياً من المتفقد التربوي\n              </h2>\n              <p className=\"text-xs text-amber-800 dark:text-amber-200/80 mt-0.5\">\n                تم التحقق من سلامة المحتوى العلمي والبيداغوجي لهذا المنشور، وهو يظهر في صدارة ترتيب مادة ({worksheet.subject?.nameAr}).\n              </p>\n            </div>\n          </div>\n          <span className=\"px-3 py-1 rounded-full bg-amber-500 text-white text-xs font-extrabold shrink-0\">\n            مرتبة الصدارة ★\n          </span>\n        </div>\n      )}\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-12 gap-8\">\n        {/* Right Column: Embedded PDF Viewer & Reviews */}\n        <section className=\"lg:col-span-8 flex flex-col gap-6\">\n          <div className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm overflow-hidden\">\n            <div className=\"bg-slate-50 dark:bg-slate-800 px-5 py-3.5 border-b border-slate-200 dark:border-slate-700 flex items-center justify-between\">\n              <div className=\"flex items-center gap-2 text-slate-700 dark:text-slate-200 font-semibold text-sm\">\n                <FileText className=\"w-4 h-4 text-blue-600\" />\n                <span>معاينة مباشرة لملف المنشور ({worksheet.fileName})</span>\n              </div>\n              {worksheet.previewUrl && (\n                <a\n                  href={worksheet.previewUrl}\n                  target=\"_blank\"\n                  rel=\"noopener noreferrer\"\n                  className=\"text-xs font-medium text-blue-600 hover:text-blue-800 inline-flex items-center gap-1\"\n                >\n                  <span>فتح في نافذة مستقلة</span>\n                  <ExternalLink className=\"w-3.5 h-3.5\" />\n                </a>\n              )}\n            </div>\n\n            {worksheet.previewUrl ? (\n              <iframe\n                src={`${worksheet.previewUrl}#toolbar=0&navpanes=0`}\n                title={displayTitle}\n                className=\"w-full h-[680px] bg-slate-100\"\n              />\n            ) : (\n              <div className=\"h-[450px] flex flex-col items-center justify-center bg-slate-50 dark:bg-slate-800/40 p-8 text-center\">\n                <FileText className=\"w-16 h-16 text-slate-400 mb-3\" />\n                <p className=\"text-slate-700 dark:text-slate-200 font-semibold mb-1\">\n                  المعاينة المباشرة جاهزة عند التحميل\n                </p>\n                <p className=\"text-sm text-slate-500 max-w-md mb-4\">\n                  اضغط على زر &quot;تحميل مباشر (PDF)&quot; لتنزيل النسخة الكاملة عالية الدقة.\n                </p>\n              </div>\n            )}\n          </div>\n\n          <ReviewSection\n            worksheetId={worksheet.id}\n            initialRatingAvg={worksheet.ratingAvg ?? 0}\n            initialReviewCount={worksheet.reviewCount ?? 0}\n          />\n        </section>\n\n        {/* Left Column: Metadata, Inspector Endorsement Control, Actions & Publisher Profile Card */}\n        <aside className=\"lg:col-span-4 flex flex-col gap-6\">\n          <div className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm flex flex-col gap-5\">\n            {/* Taxonomy & Audience Badges */}\n            <div className=\"flex flex-wrap items-center gap-2\">\n              <span\n                className=\"px-3 py-1 rounded-full text-xs font-bold text-white\"\n                style={{ backgroundColor: subjectColor }}\n              >\n                {worksheet.subject?.nameAr || worksheet.subject?.name}\n              </span>\n              <span className=\"px-3 py-1 rounded-full text-xs font-semibold bg-blue-50 dark:bg-blue-950/60 text-blue-700 dark:text-blue-300\">\n                {worksheet.grade?.nameAr || worksheet.grade?.name}\n              </span>\n              <span className=\"px-3 py-1 rounded-full text-xs font-semibold bg-amber-50 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300\">\n                {worksheet.category?.nameAr || worksheet.category?.name}\n              </span>\n              <span className=\"px-3 py-1 rounded-full text-xs font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 inline-flex items-center gap-1\">\n                {worksheet.audience === \"TEACHERS_ONLY\" ? (\n                  <Lock className=\"w-3 h-3 text-rose-600\" />\n                ) : (\n                  <Users className=\"w-3 h-3 text-emerald-600\" />\n                )}\n                <span>\n                  {AUDIENCE_LABELS[worksheet.audience] ||\n                    AUDIENCE_LABELS.TEACHERS_AND_STUDENTS}\n                </span>\n              </span>\n            </div>\n\n            <h1 className=\"text-2xl font-bold text-slate-900 dark:text-white leading-snug\">\n              {displayTitle}\n            </h1>\n\n            {displayDesc && (\n              <p className=\"text-slate-600 dark:text-slate-300 text-sm leading-relaxed whitespace-pre-line\">\n                {displayDesc}\n              </p>\n            )}\n\n            {canEndorse && (\n              <div className=\"p-4 rounded-2xl bg-amber-50/90 dark:bg-amber-950/40 border-2 border-amber-300 dark:border-amber-700 space-y-2.5\">\n                <div className=\"flex items-center gap-2 text-xs font-extrabold text-amber-900 dark:text-amber-300\">\n                  <BadgeCheck className=\"w-4 h-4 text-amber-600 shrink-0\" />\n                  <span>صلاحية المتفقد التربوي: الاعتماد العلمي والبيداغوجي</span>\n                </div>\n                <p className=\"text-[11px] text-amber-800 dark:text-amber-200/80 leading-relaxed\">\n                  وضع علامة الاعتماد يؤكد صحة المنشور علمياً وبيداغوجياً ويرفع ترتيبه تلقائياً في صدارة مادة ({worksheet.subject?.nameAr}).\n                </p>\n                <button\n                  type=\"button\"\n                  onClick={handleToggleEndorsement}\n                  disabled={endorseLoading}\n                  className={`w-full py-2.5 px-4 rounded-xl font-bold text-xs flex items-center justify-center gap-2 transition cursor-pointer shadow-sm ${\n                    isEndorsed\n                      ? \"bg-white text-amber-800 border border-amber-400 hover:bg-amber-100\"\n                      : \"bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-white\"\n                  }`}\n                >\n                  {endorseLoading ? (\n                    <Loader2 className=\"w-4 h-4 animate-spin\" />\n                  ) : (\n                    <BadgeCheck className=\"w-4 h-4\" />\n                  )}\n                  <span>\n                    {isEndorsed\n                      ? \"معتمد علمياً وبيداغوجياً ✓ (اضغط لإلغاء العلامة)\"\n                      : \"تأكيد الصحة العلمية والبيداغوجية ورفع الترتيب\"}\n                  </span>\n                </button>\n              </div>\n            )}\n\n            {/* Download, Favorite, Share Buttons */}\n            <div className=\"flex flex-col gap-3 pt-2\">\n              <button\n                onClick={handleDownload}\n                disabled={downloading}\n                className=\"w-full py-3.5 px-5 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold flex items-center justify-center gap-2.5 shadow-sm transition cursor-pointer\"\n              >\n                {downloading ? (\n                  <Loader2 className=\"w-5 h-5 animate-spin\" />\n                ) : (\n                  <Download className=\"w-5 h-5\" />\n                )}\n                <span>\n                  {downloading ? \"جاري تجهيز الرابط...\" : \"تحميل مباشر (PDF)\"}\n                </span>\n              </button>\n\n              <div className=\"grid grid-cols-2 gap-3\">\n                <button\n                  onClick={handleToggleFavorite}\n                  disabled={favLoading}\n                  className={`py-2.5 px-4 rounded-xl border font-semibold text-sm flex items-center justify-center gap-2 transition cursor-pointer ${\n                    isFavorited\n                      ? \"bg-rose-50 border-rose-200 text-rose-600\"\n                      : \"bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-50\"\n                  }`}\n                >\n                  <Heart\n                    className={`w-4 h-4 ${\n                      isFavorited ? \"fill-rose-500 text-rose-500\" : \"\"\n                    }`}\n                  />\n                  <span>{isFavorited ? \"في المفضلة\" : \"حفظ بالمفضلة\"}</span>\n                </button>\n\n                <button\n                  onClick={handleShare}\n                  className=\"py-2.5 px-4 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 hover:bg-slate-50 text-slate-700 dark:text-slate-200 font-semibold text-sm flex items-center justify-center gap-2 transition cursor-pointer\"\n                >\n                  {copied ? (\n                    <>\n                      <Check className=\"w-4 h-4 text-emerald-600\" />\n                      <span className=\"text-emerald-600\">تم النسخ!</span>\n                    </>\n                  ) : (\n                    <>\n                      <Share2 className=\"w-4 h-4\" />\n                      <span>مشاركة</span>\n                    </>\n                  )}\n                </button>\n              </div>\n            </div>\n\n            {/* Stats */}\n            <div className=\"border-t border-slate-100 dark:border-slate-800 pt-4 grid grid-cols-4 gap-2 text-center\">\n              <div className=\"bg-slate-50 dark:bg-slate-800 rounded-xl p-2.5\">\n                <span className=\"block text-xs text-slate-500\">التحميلات</span>\n                <span className=\"font-bold text-slate-800 dark:text-white\">\n                  {downloadCount}\n                </span>\n              </div>\n              <div className=\"bg-slate-50 dark:bg-slate-800 rounded-xl p-2.5\">\n                <span className=\"block text-xs text-slate-500\">التفضيلات</span>\n                <span className=\"font-bold text-slate-800 dark:text-white\">\n                  {favoriteCount}\n                </span>\n              </div>\n              <div className=\"bg-slate-50 dark:bg-slate-800 rounded-xl p-2.5\">\n                <span className=\"block text-xs text-slate-500\">التقييم</span>\n                <span className=\"font-bold text-amber-600 flex items-center justify-center gap-0.5 text-xs\">\n                  <Star className=\"w-3.5 h-3.5 fill-amber-400 text-amber-400\" />\n                  <span>\n                    {worksheet.ratingAvg > 0\n                      ? worksheet.ratingAvg.toFixed(1)\n                      : \"جديد\"}\n                  </span>\n                </span>\n              </div>\n              <div className=\"bg-slate-50 dark:bg-slate-800 rounded-xl p-2.5\">\n                <span className=\"block text-xs text-slate-500\">حجم الملف</span>\n                <span className=\"font-bold text-slate-800 dark:text-white text-[11px] truncate\">\n                  {formatFileSize(worksheet.fileSize)}\n                </span>\n              </div>\n            </div>\n\n            {/* Publisher Card with Full Public Profile Link */}\n            <div className=\"border-t border-slate-100 dark:border-slate-800 pt-4 space-y-3\">\n              <div className=\"flex items-center gap-3\">\n                {worksheet.uploader?.avatarUrl ? (\n                  <img\n                    src={worksheet.uploader.avatarUrl}\n                    alt={worksheet.uploader.name}\n                    className=\"w-12 h-12 rounded-full object-cover border border-slate-200\"\n                  />\n                ) : (\n                  <div className=\"w-12 h-12 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold\">\n                    <UserIcon className=\"w-6 h-6\" />\n                  </div>\n                )}\n                <div className=\"flex-1 min-w-0\">\n                  <div className=\"flex items-center gap-1.5 flex-wrap\">\n                    <Link\n                      href={`/publisher/${worksheet.uploader?.id || worksheet.uploadedBy}`}\n                      className=\"text-sm font-extrabold text-slate-900 dark:text-white hover:text-blue-600 truncate\"\n                    >\n                      {worksheet.uploader?.name || \"ناشر معتمد\"}\n                    </Link>\n                    <InspectorBadge role={worksheet.uploader?.role} size=\"sm\" />\n                  </div>\n                  {worksheet.uploader?.school && (\n                    <p className=\"text-xs text-slate-500 flex items-center gap-1 truncate mt-0.5\">\n                      <School className=\"w-3.5 h-3.5\" />\n                      <span>{worksheet.uploader.school}</span>\n                    </p>\n                  )}\n                </div>\n                <div className=\"text-xs text-slate-400 flex items-center gap-1\">\n                  <Calendar className=\"w-3.5 h-3.5\" />\n                  <span>\n                    {new Date(worksheet.createdAt).toLocaleDateString(\"ar-EG\")}\n                  </span>\n                </div>\n              </div>\n\n              <Link\n                href={`/publisher/${worksheet.uploader?.id || worksheet.uploadedBy}`}\n                className=\"w-full py-2.5 px-4 rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 hover:text-blue-600 text-xs font-bold flex items-center justify-center gap-2 transition\"\n              >\n                <UserPlus className=\"w-4 h-4 text-blue-600\" />\n                <span>عرض ملف الناشر الكامل، متابعته، وإضافته للمفضلة</span>\n              </Link>\n            </div>\n\n            {/* Tags */}\n            {worksheet.tags && worksheet.tags.length > 0 && (\n              <div className=\"border-t border-slate-100 dark:border-slate-800 pt-4\">\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {worksheet.tags.map((tag) => (\n                    <Link\n                      key={tag}\n                      href={`/browse?search=${encodeURIComponent(tag)}`}\n                      className=\"inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 text-slate-600 dark:text-slate-300 text-xs\"\n                    >\n                      <Tag className=\"w-3 h-3\" />\n                      <span>{tag}</span>\n                    </Link>\n                  ))}\n                </div>\n              </div>\n            )}\n          </div>\n        </aside>\n      </div>\n    </main>\n  );\n}\n",
  "src/app/(main)/upload/page.tsx": "\"use client\";\n\n/**\n * Upload & Publish Worksheet Page — Al-Musnad (المسند) v3.0\n *\n * Includes Target Audience Selector (`audience`):\n * - TEACHERS_AND_STUDENTS: للمعلمين والتلاميذ معاً (مثل التمارين وأوراق العمل)\n * - TEACHERS_ONLY: للمعلمين والمتفقدين فقط — محجوب عن التلاميذ (مثل إصلاح الامتحانات والمذكرات البيداغوجية)\n * - SAME_ROLE_ONLY: نفس فئة الناشر فقط (مثلاً بين المؤسسات فقط أو بين المعلمين فقط)\n * - ALL: عام لجميع منتسبي منصة المسند\n */\n\nimport React, { useState, useEffect, DragEvent, ChangeEvent, FormEvent } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  UploadCloud,\n  FileText,\n  X,\n  CheckCircle2,\n  AlertCircle,\n  Loader2,\n  Plus,\n  Image as ImageIcon,\n  Users,\n  Lock,\n  Building2,\n  Globe,\n} from \"lucide-react\";\nimport { MAX_FILE_SIZE_BYTES, MAX_FILE_SIZE_MB, ALLOWED_FILE_TYPES } from \"@/config/constants\";\nimport { extractPdfThumbnailAndPages } from \"@/lib/utils/pdf-thumbnail\";\nimport type {\n  Grade,\n  Subject,\n  Category,\n  ApiResponse,\n  WorksheetWithRelations,\n  TargetAudience,\n} from \"@/types\";\n\nconst AUDIENCE_OPTIONS: {\n  value: TargetAudience;\n  title: string;\n  subtitle: string;\n  icon: React.ComponentType<{ className?: string }>;\n  badge: string;\n}[] = [\n  {\n    value: \"TEACHERS_AND_STUDENTS\",\n    title: \"للمعلمين والتلاميذ معاً (تمارين وأنشطة)\",\n    subtitle: \"يظهر للمعلمين والتلاميذ لتزويدهم بالتمارين وأوراق العمل والمراجعات.\",\n    icon: Users,\n    badge: \"تمارين وتطبيقات\",\n  },\n  {\n    value: \"TEACHERS_ONLY\",\n    title: \"للمعلمين والمتفقدين فقط (إصلاح ومذكرات)\",\n    subtitle: \"يُحجب تماماً عن التلاميذ — مثالي لنشر إصلاح الامتحانات، الحلول النموذجية، والتخطيط البيداغوجي.\",\n    icon: Lock,\n    badge: \"خاص بالمعلمين\",\n  },\n  {\n    value: \"SAME_ROLE_ONLY\",\n    title: \"أعضاء نفس فئتي فقط\",\n    subtitle: \"يظل المنشور متاحاً حصرياً للأعضاء الذين يحملون نفس نوع حسابك في المسند.\",\n    icon: Building2,\n    badge: \"نفس فئة الناشر\",\n  },\n  {\n    value: \"ALL\",\n    title: \"جمهور موسّع (جميع منتسبي المسند)\",\n    subtitle: \"متاح لجميع الحسابات (المؤسسات التربوية، المتفقدين، المعلمين، والتلاميذ).\",\n    icon: Globe,\n    badge: \"عام للجميع\",\n  },\n];\n\nexport default function UploadWorksheetPage() {\n  const router = useRouter();\n\n  const [grades, setGrades] = useState<Grade[]>([]);\n  const [subjects, setSubjects] = useState<Subject[]>([]);\n  const [categories, setCategories] = useState<Category[]>([]);\n\n  const [file, setFile] = useState<File | null>(null);\n  const [thumbnailFile, setThumbnailFile] = useState<File | null>(null);\n  const [thumbnailPreview, setThumbnailPreview] = useState<string | null>(null);\n  const [pageCount, setPageCount] = useState<number | null>(null);\n  const [extractingThumb, setExtractingThumb] = useState<boolean>(false);\n  const [isDragging, setIsDragging] = useState<boolean>(false);\n\n  const [titleAr, setTitleAr] = useState<string>(\"\");\n  const [descriptionAr, setDescriptionAr] = useState<string>(\"\");\n  const [gradeId, setGradeId] = useState<string>(\"\");\n  const [subjectId, setSubjectId] = useState<string>(\"\");\n  const [categoryId, setCategoryId] = useState<string>(\"\");\n  const [audience, setAudience] = useState<TargetAudience>(\"TEACHERS_AND_STUDENTS\");\n  const [tagInput, setTagInput] = useState<string>(\"\");\n  const [tags, setTags] = useState<string[]>([]);\n\n  const [submitting, setSubmitting] = useState<boolean>(false);\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    async function loadTaxonomies() {\n      try {\n        const [gRes, sRes, cRes] = await Promise.all([\n          fetch(\"/api/grades\"),\n          fetch(\"/api/subjects\"),\n          fetch(\"/api/categories\"),\n        ]);\n        const [gJson, sJson, cJson] = await Promise.all([\n          gRes.json() as Promise<ApiResponse<Grade[]>>,\n          sRes.json() as Promise<ApiResponse<Subject[]>>,\n          cRes.json() as Promise<ApiResponse<Category[]>>,\n        ]);\n\n        if (gJson.success) setGrades(gJson.data);\n        if (sJson.success) setSubjects(sJson.data);\n        if (cJson.success) setCategories(cJson.data);\n      } catch {\n        setError(\"تعذر تحميل قوائم الصفوف والمواد الدراسية\");\n      }\n    }\n    loadTaxonomies();\n  }, []);\n\n  const validateAndSetFile = async (selected: File) => {\n    setError(null);\n    if (!ALLOWED_FILE_TYPES.includes(selected.type as \"application/pdf\")) {\n      setError(\"يُسمح فقط برفع ملفات بصيغة PDF.\");\n      return;\n    }\n    if (selected.size > MAX_FILE_SIZE_BYTES) {\n      setError(`حجم الملف يتجاوز الحد الأقصى المسموح به (${MAX_FILE_SIZE_MB} ميجابايت).`);\n      return;\n    }\n\n    setFile(selected);\n    if (!titleAr) {\n      setTitleAr(selected.name.replace(/\\.pdf$/i, \"\").replace(/[-_]/g, \" \"));\n    }\n\n    try {\n      setExtractingThumb(true);\n      const extracted = await extractPdfThumbnailAndPages(selected);\n      setThumbnailFile(extracted.thumbnailFile);\n      setThumbnailPreview(extracted.thumbnailPreviewUrl);\n      setPageCount(extracted.pageCount);\n    } catch (err) {\n      console.warn(\"Auto thumbnail generation skipped:\", err);\n      setThumbnailFile(null);\n      setThumbnailPreview(null);\n      setPageCount(null);\n    } finally {\n      setExtractingThumb(false);\n    }\n  };\n\n  const handleClearFile = () => {\n    if (thumbnailPreview) URL.revokeObjectURL(thumbnailPreview);\n    setFile(null);\n    setThumbnailFile(null);\n    setThumbnailPreview(null);\n    setPageCount(null);\n  };\n\n  const handleDrop = (e: DragEvent<HTMLDivElement>) => {\n    e.preventDefault();\n    setIsDragging(false);\n    const droppedFile = e.dataTransfer.files?.[0];\n    if (droppedFile) validateAndSetFile(droppedFile);\n  };\n\n  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {\n    const selected = e.target.files?.[0];\n    if (selected) validateAndSetFile(selected);\n  };\n\n  const handleAddTag = () => {\n    const clean = tagInput.trim();\n    if (clean && !tags.includes(clean) && tags.length < 10) {\n      setTags([...tags, clean]);\n      setTagInput(\"\");\n    }\n  };\n\n  const handleSubmit = async (e: FormEvent) => {\n    e.preventDefault();\n    setError(null);\n\n    if (!file) {\n      setError(\"يرجى اختيار ملف الـ PDF أولاً\");\n      return;\n    }\n    if (!titleAr.trim() || !gradeId || !subjectId || !categoryId) {\n      setError(\"يرجى ملء جميع الحقول الأساسية (العنوان، الصف، المادة، ونوع النشاط)\");\n      return;\n    }\n\n    try {\n      setSubmitting(true);\n      const formData = new FormData();\n      formData.append(\"file\", file);\n      if (thumbnailFile) {\n        formData.append(\"thumbnail\", thumbnailFile);\n      }\n      if (pageCount) {\n        formData.append(\"pageCount\", String(pageCount));\n      }\n\n      const metadata = {\n        title: titleAr.trim(),\n        titleAr: titleAr.trim(),\n        description: descriptionAr.trim() || undefined,\n        descriptionAr: descriptionAr.trim() || undefined,\n        gradeId,\n        subjectId,\n        categoryId,\n        audience,\n        tags,\n      };\n      formData.append(\"metadata\", JSON.stringify(metadata));\n\n      const res = await fetch(\"/api/worksheets\", {\n        method: \"POST\",\n        body: formData,\n      });\n\n      const json: ApiResponse<WorksheetWithRelations> = await res.json();\n\n      if (!res.ok || !json.success) {\n        throw new Error(!json.success ? json.error.message : \"فشل نشر الوثيقة\");\n      }\n\n      router.push(`/worksheet/${json.data.id}`);\n    } catch (err) {\n      setError(err instanceof Error ? err.message : \"حدث خطأ أثناء رفع الملف\");\n    } finally {\n      setSubmitting(false);\n    }\n  };\n\n  return (\n    <main className=\"max-w-3xl mx-auto px-4 py-10\" dir=\"rtl\">\n      <div className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 sm:p-8 shadow-sm\">\n        <h1 className=\"text-2xl font-bold text-slate-900 dark:text-white mb-2\">\n          نشر وثيقة أو نشاط جديد في المسند\n        </h1>\n        <p className=\"text-sm text-slate-500 mb-6\">\n          ارفع ملف الـ PDF وحدد جمهور النشر المستهدف (مثلاً: تمارين للمعلمين والتلاميذ، أو إصلاح خاص بالمعلمين فقط).\n        </p>\n\n        {error && (\n          <div className=\"mb-6 p-4 rounded-xl bg-red-50 border border-red-200 text-red-700 text-sm flex items-center gap-2.5\">\n            <AlertCircle className=\"w-5 h-5 shrink-0\" />\n            <span>{error}</span>\n          </div>\n        )}\n\n        <form onSubmit={handleSubmit} className=\"space-y-6\">\n          {/* File Dropzone */}\n          <div>\n            <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n              ملف الوثيقة (PDF فقط - بحد أقصى {MAX_FILE_SIZE_MB} ميجابايت) *\n            </label>\n\n            {!file ? (\n              <div\n                onDragOver={(e) => {\n                  e.preventDefault();\n                  setIsDragging(true);\n                }}\n                onDragLeave={() => setIsDragging(false)}\n                onDrop={handleDrop}\n                className={`border-2 border-dashed rounded-2xl p-8 text-center transition cursor-pointer ${\n                  isDragging\n                    ? \"border-blue-600 bg-blue-50\"\n                    : \"border-slate-300 hover:border-blue-500 bg-slate-50 dark:bg-slate-800/50\"\n                }`}\n              >\n                <input\n                  type=\"file\"\n                  id=\"pdf-upload\"\n                  accept=\"application/pdf,.pdf\"\n                  onChange={handleFileChange}\n                  className=\"hidden\"\n                />\n                <label htmlFor=\"pdf-upload\" className=\"cursor-pointer flex flex-col items-center\">\n                  <UploadCloud className=\"w-12 h-12 text-blue-600 mb-3\" />\n                  <span className=\"font-bold text-slate-800 dark:text-white mb-1\">\n                    اسحب وأفلت ملف الـ PDF هنا، أو اضغط لاختيار ملف من جهازك\n                  </span>\n                  <span className=\"text-xs text-slate-500\">\n                    سيتم استخراج صورة الغلاف وعدد الصفحات تلقائياً\n                  </span>\n                </label>\n              </div>\n            ) : (\n              <div className=\"p-4 rounded-2xl bg-emerald-50/70 border border-emerald-200 flex flex-col sm:flex-row items-center justify-between gap-4\">\n                <div className=\"flex items-center gap-4 min-w-0 w-full\">\n                  <div className=\"w-20 h-24 rounded-xl bg-white border border-slate-200 overflow-hidden shrink-0 flex items-center justify-center shadow-sm\">\n                    {extractingThumb ? (\n                      <Loader2 className=\"w-6 h-6 text-blue-600 animate-spin\" />\n                    ) : thumbnailPreview ? (\n                      <img\n                        src={thumbnailPreview}\n                        alt=\"معاينة الغلاف\"\n                        className=\"w-full h-full object-cover\"\n                      />\n                    ) : (\n                      <ImageIcon className=\"w-6 h-6 text-slate-400\" />\n                    )}\n                  </div>\n\n                  <div className=\"min-w-0 flex-1\">\n                    <div className=\"flex items-center gap-1.5 text-emerald-700 text-xs font-bold mb-1\">\n                      <CheckCircle2 className=\"w-4 h-4 shrink-0\" />\n                      <span>تم تجهيز الملف وصورة الغلاف تلقائياً</span>\n                    </div>\n                    <p className=\"font-bold text-slate-900 text-sm truncate\">{file.name}</p>\n                    <div className=\"flex items-center gap-3 text-xs text-slate-500 mt-1\">\n                      <span>الحجم: {(file.size / (1024 * 1024)).toFixed(2)} ميجابايت</span>\n                      {pageCount && (\n                        <span className=\"px-2 py-0.5 rounded-md bg-white border border-emerald-200 text-emerald-800 font-semibold\">\n                          {pageCount} {pageCount === 1 ? \"صفحة\" : \"صفحات\"}\n                        </span>\n                      )}\n                    </div>\n                  </div>\n                </div>\n\n                <button\n                  type=\"button\"\n                  onClick={handleClearFile}\n                  className=\"p-2 rounded-xl text-slate-500 hover:text-red-600 hover:bg-white transition self-end sm:self-center\"\n                >\n                  <X className=\"w-5 h-5\" />\n                </button>\n              </div>\n            )}\n          </div>\n\n          {/* Target Audience Selection */}\n          <div>\n            <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n              جمهور النشر المستهدف (من يمكنه رؤية وتحميل هذا المنشور؟) *\n            </label>\n            <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-3\">\n              {AUDIENCE_OPTIONS.map((opt) => {\n                const Icon = opt.icon;\n                const isSelected = audience === opt.value;\n                return (\n                  <button\n                    key={opt.value}\n                    type=\"button\"\n                    onClick={() => setAudience(opt.value)}\n                    className={`text-right p-4 rounded-2xl border-2 transition flex flex-col justify-between gap-2 cursor-pointer ${\n                      isSelected\n                        ? \"border-blue-600 bg-blue-50/70 dark:bg-blue-950/40 shadow-sm\"\n                        : \"border-slate-200 dark:border-slate-800 hover:border-slate-300\"\n                    }`}\n                  >\n                    <div className=\"flex items-center justify-between w-full\">\n                      <span className=\"px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300\">\n                        {opt.badge}\n                      </span>\n                      <Icon\n                        className={`w-5 h-5 ${\n                          isSelected ? \"text-blue-600\" : \"text-slate-400\"\n                        }`}\n                      />\n                    </div>\n                    <div>\n                      <p className=\"text-xs font-extrabold text-slate-900 dark:text-white\">\n                        {opt.title}\n                      </p>\n                      <p className=\"text-[11px] text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                        {opt.subtitle}\n                      </p>\n                    </div>\n                  </button>\n                );\n              })}\n            </div>\n          </div>\n\n          {/* Title */}\n          <div>\n            <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n              عنوان المنشور *\n            </label>\n            <input\n              type=\"text\"\n              required\n              minLength={3}\n              maxLength={255}\n              value={titleAr}\n              onChange={(e) => setTitleAr(e.target.value)}\n              placeholder=\"مثال: اختبار الثلاثي الأول في الرياضيات (مع الإصلاح)\"\n              className=\"w-full px-4 py-3 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 focus:border-blue-600 outline-none text-sm\"\n            />\n          </div>\n\n          {/* Taxonomies */}\n          <div className=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n            <div>\n              <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n                الصف الدراسي *\n              </label>\n              <select\n                required\n                value={gradeId}\n                onChange={(e) => setGradeId(e.target.value)}\n                className=\"w-full px-3.5 py-3 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              >\n                <option value=\"\">اختر الصف...</option>\n                {grades.map((g) => (\n                  <option key={g.id} value={g.id}>\n                    {g.nameAr}\n                  </option>\n                ))}\n              </select>\n            </div>\n\n            <div>\n              <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n                المادة الدراسية *\n              </label>\n              <select\n                required\n                value={subjectId}\n                onChange={(e) => setSubjectId(e.target.value)}\n                className=\"w-full px-3.5 py-3 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              >\n                <option value=\"\">اختر المادة...</option>\n                {subjects.map((s) => (\n                  <option key={s.id} value={s.id}>\n                    {s.nameAr}\n                  </option>\n                ))}\n              </select>\n            </div>\n\n            <div>\n              <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n                نوع الوثيقة *\n              </label>\n              <select\n                required\n                value={categoryId}\n                onChange={(e) => setCategoryId(e.target.value)}\n                className=\"w-full px-3.5 py-3 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              >\n                <option value=\"\">اختر التصنيف...</option>\n                {categories.map((c) => (\n                  <option key={c.id} value={c.id}>\n                    {c.nameAr}\n                  </option>\n                ))}\n              </select>\n            </div>\n          </div>\n\n          {/* Description */}\n          <div>\n            <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n              وصف مختصر وأهداف المنشور (اختياري)\n            </label>\n            <textarea\n              rows={3}\n              maxLength={2000}\n              value={descriptionAr}\n              onChange={(e) => setDescriptionAr(e.target.value)}\n              placeholder=\"اكتب نبذة عن المكتسبات المستهدفة وكيفية استثمار الوثيقة...\"\n              className=\"w-full px-4 py-3 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 focus:border-blue-600 outline-none text-sm\"\n            />\n          </div>\n\n          {/* Tags */}\n          <div>\n            <label className=\"block text-sm font-bold text-slate-700 dark:text-slate-200 mb-2\">\n              الكلمات المفتاحية للبحث (حتى 10 وسوم)\n            </label>\n            <div className=\"flex gap-2 mb-2\">\n              <input\n                type=\"text\"\n                value={tagInput}\n                onChange={(e) => setTagInput(e.target.value)}\n                onKeyDown={(e) => {\n                  if (e.key === \"Enter\") {\n                    e.preventDefault();\n                    handleAddTag();\n                  }\n                }}\n                placeholder=\"أضف كلمة مفتاحية (مثال: إصلاح، تقييم، الكسور)...\"\n                className=\"flex-1 px-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n              <button\n                type=\"button\"\n                onClick={handleAddTag}\n                className=\"px-4 py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 text-slate-700 dark:text-slate-200 font-semibold text-sm inline-flex items-center gap-1\"\n              >\n                <Plus className=\"w-4 h-4\" />\n                إضافة\n              </button>\n            </div>\n            {tags.length > 0 && (\n              <div className=\"flex flex-wrap gap-2\">\n                {tags.map((t) => (\n                  <span\n                    key={t}\n                    className=\"inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-blue-50 text-blue-700 text-xs font-semibold\"\n                  >\n                    {t}\n                    <button\n                      type=\"button\"\n                      onClick={() => setTags(tags.filter((item) => item !== t))}\n                      className=\"hover:text-red-600\"\n                    >\n                      <X className=\"w-3.5 h-3.5\" />\n                    </button>\n                  </span>\n                ))}\n              </div>\n            )}\n          </div>\n\n          <button\n            type=\"submit\"\n            disabled={submitting || extractingThumb}\n            className=\"w-full py-3.5 px-6 rounded-xl bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-bold flex items-center justify-center gap-2 shadow-sm transition cursor-pointer\"\n          >\n            {submitting ? (\n              <>\n                <Loader2 className=\"w-5 h-5 animate-spin\" />\n                <span>جاري رفع الملف والغلاف ونشر الوثيقة...</span>\n              </>\n            ) : (\n              <>\n                <FileText className=\"w-5 h-5\" />\n                <span>نشر الوثيقة في منصة المسند الآن</span>\n              </>\n            )}\n          </button>\n        </form>\n      </div>\n    </main>\n  );\n}\n",
  "src/app/(main)/publisher/[id]/page.tsx": "\"use client\";\n\n/**\n * Public Publisher Profile Page — Al-Musnad (المسند) v3.0\n *\n * Route: /publisher/[id]\n * Displays full public profile for any Publisher (Institution, Teacher, or Inspector):\n * - Full profile info, bio, school/institution, role badge, followers count, favorited count.\n * - Interactive \"متابعة الناشر\" (Follow) and \"إضافة الناشر إلى المفضلة\" (Favorite Publisher) buttons.\n * - Complete grid of published worksheets by this publisher (filtered by viewer's audience permissions).\n */\n\nimport React, { useEffect, useState } from \"react\";\nimport { useParams, useRouter } from \"next/navigation\";\nimport Link from \"next/link\";\nimport {\n  User as UserIcon,\n  School,\n  Users,\n  Heart,\n  FileText,\n  BadgeCheck,\n  UserPlus,\n  UserCheck,\n  Loader2,\n  Calendar,\n  Download,\n  ArrowRight,\n} from \"lucide-react\";\nimport InspectorBadge from \"@/components/ui/InspectorBadge\";\nimport WorksheetCard from \"@/components/worksheets/WorksheetCard\";\nimport {\n  getPublicPublisherProfileData,\n  toggleFollowPublisherAction,\n  toggleFavoritePublisherAction,\n} from \"@/actions/publisher.actions\";\n\ntype PublisherData = Awaited<ReturnType<typeof getPublicPublisherProfileData>>;\n\nexport default function PublicPublisherProfilePage() {\n  const params = useParams<{ id: string }>();\n  const router = useRouter();\n  const publisherId = params?.id;\n\n  const [data, setData] = useState<PublisherData | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const [isFollowing, setIsFollowing] = useState(false);\n  const [followersCount, setFollowersCount] = useState(0);\n  const [followLoading, setFollowLoading] = useState(false);\n\n  const [isFavPublisher, setIsFavPublisher] = useState(false);\n  const [favoritedByCount, setFavoritedByCount] = useState(0);\n  const [favLoading, setFavLoading] = useState(false);\n\n  useEffect(() => {\n    if (!publisherId) return;\n    let isMounted = true;\n\n    async function load() {\n      try {\n        setLoading(true);\n        const res = await getPublicPublisherProfileData(publisherId);\n        if (isMounted) {\n          setData(res);\n          setIsFollowing(res.viewerState.isFollowing);\n          setFollowersCount(res.stats.followersCount);\n          setIsFavPublisher(res.viewerState.isFavoritedPublisher);\n          setFavoritedByCount(res.stats.favoritedByCount);\n        }\n      } catch (err) {\n        if (isMounted) {\n          setError(\n            err instanceof Error ? err.message : \"تعذر تحميل ملف الناشر\"\n          );\n        }\n      } finally {\n        if (isMounted) setLoading(false);\n      }\n    }\n\n    load();\n    return () => {\n      isMounted = false;\n    };\n  }, [publisherId]);\n\n  const handleToggleFollow = async () => {\n    if (!publisherId || followLoading) return;\n    try {\n      setFollowLoading(true);\n      const res = await toggleFollowPublisherAction(publisherId);\n      setIsFollowing(res.isFollowing);\n      setFollowersCount(res.followersCount);\n    } catch (err) {\n      if (err instanceof Error && err.message.includes(\"تسجيل الدخول\")) {\n        router.push(`/login?redirectTo=/publisher/${publisherId}`);\n      } else {\n        alert(err instanceof Error ? err.message : \"تعذر تنفيذ العملية\");\n      }\n    } finally {\n      setFollowLoading(false);\n    }\n  };\n\n  const handleToggleFavPublisher = async () => {\n    if (!publisherId || favLoading) return;\n    try {\n      setFavLoading(true);\n      const res = await toggleFavoritePublisherAction(publisherId);\n      setIsFavPublisher(res.isFavoritedPublisher);\n      setFavoritedByCount(res.favoritedByCount);\n    } catch (err) {\n      if (err instanceof Error && err.message.includes(\"تسجيل الدخول\")) {\n        router.push(`/login?redirectTo=/publisher/${publisherId}`);\n      } else {\n        alert(err instanceof Error ? err.message : \"تعذر تنفيذ العملية\");\n      }\n    } finally {\n      setFavLoading(false);\n    }\n  };\n\n  if (loading) {\n    return (\n      <div className=\"min-h-[65vh] flex items-center justify-center\" dir=\"rtl\">\n        <Loader2 className=\"w-8 h-8 text-blue-600 animate-spin\" />\n      </div>\n    );\n  }\n\n  if (error || !data) {\n    return (\n      <div className=\"max-w-xl mx-auto px-4 py-16 text-center space-y-4\" dir=\"rtl\">\n        <p className=\"text-slate-800 dark:text-white font-bold text-lg\">\n          {error || \"الملف الشخصي للناشر غير متاح\"}\n        </p>\n        <Link\n          href=\"/browse\"\n          className=\"inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-blue-600 text-white text-sm font-bold\"\n        >\n          <ArrowRight className=\"w-4 h-4\" />\n          <span>العودة لبنك المنشورات</span>\n        </Link>\n      </div>\n    );\n  }\n\n  const { publisher, worksheets, stats, viewerState } = data;\n\n  return (\n    <main className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8\" dir=\"rtl\">\n      {/* Publisher Hero Header Card */}\n      <section className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-sm\">\n        <div className=\"flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6\">\n          <div className=\"flex items-start sm:items-center gap-5\">\n            {publisher.avatarUrl ? (\n              <img\n                src={publisher.avatarUrl}\n                alt={publisher.name}\n                className=\"w-20 h-20 rounded-3xl object-cover border-2 border-blue-100 shadow-sm\"\n              />\n            ) : (\n              <div className=\"w-20 h-20 rounded-3xl bg-gradient-to-br from-blue-600 to-indigo-700 text-white flex items-center justify-center font-black text-2xl shadow-md\">\n                {publisher.name.charAt(0)}\n              </div>\n            )}\n\n            <div className=\"space-y-2\">\n              <div className=\"flex flex-wrap items-center gap-2.5\">\n                <h1 className=\"text-2xl sm:text-3xl font-black text-slate-900 dark:text-white\">\n                  {publisher.role === \"INSTITUTION\"\n                    ? publisher.name\n                    : `أ. ${publisher.name}`}\n                </h1>\n                <InspectorBadge role={publisher.role} size=\"md\" />\n                {publisher.role === \"TEACHER\" && (\n                  <span className=\"px-3 py-1 rounded-full text-xs font-bold bg-blue-50 text-blue-700 border border-blue-200\">\n                    معلم ناشر\n                  </span>\n                )}\n              </div>\n\n              {publisher.school && (\n                <p className=\"text-sm text-slate-600 dark:text-slate-300 flex items-center gap-1.5 font-medium\">\n                  <School className=\"w-4 h-4 text-blue-600\" />\n                  <span>{publisher.school}</span>\n                </p>\n              )}\n\n              {publisher.bio && (\n                <p className=\"text-xs sm:text-sm text-slate-500 dark:text-slate-400 max-w-2xl leading-relaxed\">\n                  {publisher.bio}\n                </p>\n              )}\n\n              <div className=\"flex items-center gap-4 text-xs text-slate-400 pt-1\">\n                <span className=\"flex items-center gap-1\">\n                  <Calendar className=\"w-3.5 h-3.5\" />\n                  <span>\n                    عضو في المسند منذ{\" \"}\n                    {new Date(publisher.createdAt).toLocaleDateString(\"ar-EG\")}\n                  </span>\n                </span>\n              </div>\n            </div>\n          </div>\n\n          {/* Follow & Favorite Publisher Buttons */}\n          <div className=\"flex flex-wrap items-center gap-3 w-full lg:w-auto\">\n            {viewerState.isOwnProfile ? (\n              <Link\n                href=\"/profile?tab=edit\"\n                className=\"px-5 py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 text-slate-800 dark:text-white text-xs font-bold transition\"\n              >\n                تعديل ملفي الشخصي\n              </Link>\n            ) : (\n              <>\n                <button\n                  type=\"button\"\n                  onClick={handleToggleFollow}\n                  disabled={followLoading}\n                  className={`flex-1 sm:flex-initial px-6 py-3 rounded-xl font-bold text-sm flex items-center justify-center gap-2 transition cursor-pointer shadow-sm ${\n                    isFollowing\n                      ? \"bg-slate-900 dark:bg-slate-700 text-white\"\n                      : \"bg-blue-600 hover:bg-blue-700 text-white\"\n                  }`}\n                >\n                  {followLoading ? (\n                    <Loader2 className=\"w-4 h-4 animate-spin\" />\n                  ) : isFollowing ? (\n                    <UserCheck className=\"w-4 h-4\" />\n                  ) : (\n                    <UserPlus className=\"w-4 h-4\" />\n                  )}\n                  <span>{isFollowing ? \"متابَع ✓\" : \"+ متابعة الناشر\"}</span>\n                </button>\n\n                <button\n                  type=\"button\"\n                  onClick={handleToggleFavPublisher}\n                  disabled={favLoading}\n                  className={`flex-1 sm:flex-initial px-5 py-3 rounded-xl font-bold text-sm border flex items-center justify-center gap-2 transition cursor-pointer ${\n                    isFavPublisher\n                      ? \"bg-rose-50 border-rose-200 text-rose-600\"\n                      : \"bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 hover:bg-slate-50\"\n                  }`}\n                >\n                  <Heart\n                    className={`w-4 h-4 ${\n                      isFavPublisher ? \"fill-rose-500 text-rose-500\" : \"\"\n                    }`}\n                  />\n                  <span>\n                    {isFavPublisher\n                      ? \"الناشر في مفضلتي\"\n                      : \"إضافة الناشر للمفضلة\"}\n                  </span>\n                </button>\n              </>\n            )}\n          </div>\n        </div>\n\n        {/* Publisher KPI Metrics Bar */}\n        <div className=\"grid grid-cols-2 sm:grid-cols-5 gap-3 mt-8 pt-6 border-t border-slate-100 dark:border-slate-800 text-center\">\n          <div className=\"bg-slate-50 dark:bg-slate-800/60 rounded-2xl p-3.5\">\n            <span className=\"text-xs text-slate-500 block\">المنشورات</span>\n            <span className=\"text-xl font-black text-slate-900 dark:text-white\">\n              {stats.worksheetsCount}\n            </span>\n          </div>\n          <div className=\"bg-amber-50/70 dark:bg-amber-950/30 rounded-2xl p-3.5 border border-amber-200/60\">\n            <span className=\"text-xs text-amber-800 dark:text-amber-300 block\">\n              معتمد من المتفقد\n            </span>\n            <span className=\"text-xl font-black text-amber-600 flex items-center justify-center gap-1\">\n              <BadgeCheck className=\"w-5 h-5\" />\n              {stats.endorsedCount}\n            </span>\n          </div>\n          <div className=\"bg-slate-50 dark:bg-slate-800/60 rounded-2xl p-3.5\">\n            <span className=\"text-xs text-slate-500 block\">المتابعون</span>\n            <span className=\"text-xl font-black text-blue-600\">\n              {followersCount}\n            </span>\n          </div>\n          <div className=\"bg-slate-50 dark:bg-slate-800/60 rounded-2xl p-3.5\">\n            <span className=\"text-xs text-slate-500 block\">في مفضلة الأعضاء</span>\n            <span className=\"text-xl font-black text-rose-600\">\n              {favoritedByCount}\n            </span>\n          </div>\n          <div className=\"bg-slate-50 dark:bg-slate-800/60 rounded-2xl p-3.5 col-span-2 sm:col-span-1\">\n            <span className=\"text-xs text-slate-500 block\">إجمالي التحميلات</span>\n            <span className=\"text-xl font-black text-emerald-600\">\n              {stats.totalDownloads}\n            </span>\n          </div>\n        </div>\n      </section>\n\n      {/* Publisher's Worksheets Grid */}\n      <section className=\"space-y-5\">\n        <div className=\"flex items-center justify-between\">\n          <h2 className=\"text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2\">\n            <FileText className=\"w-5 h-5 text-blue-600\" />\n            <span>منشورات وأعمال الناشر ({worksheets.length})</span>\n          </h2>\n        </div>\n\n        {worksheets.length === 0 ? (\n          <div className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-12 text-center text-slate-500\">\n            لا توجد منشورات متاحة للعرض في هذا الملف حالياً.\n          </div>\n        ) : (\n          <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6\">\n            {worksheets.map((ws) => (\n              <WorksheetCard key={ws.id} worksheet={ws as any} />\n            ))}\n          </div>\n        )}\n      </section>\n    </main>\n  );\n}\n",
  "src/app/(main)/profile/page.tsx": "\"use client\";\n\n/**\n * Member Workspace & Profile Page — Al-Musnad (المسند) v3.0\n *\n * Supports all sections accessible from the Navbar Profile Menu:\n * 1. مرفوعاتي (uploads)\n * 2. المنشورات المفضلة (favorites)\n * 3. الناشرون المفضلون (favorite_publishers)\n * 4. سجل التحميلات (downloads)\n * 5. تعديل الملف الشخصي — خاضع لموافقة المشرف العام (edit)\n * 6. الاشتراكات والباقات (subscriptions)\n * 7. الإعدادات (settings)\n */\n\nimport React, { useEffect, useState, Suspense } from \"react\";\nimport Link from \"next/link\";\nimport { useSearchParams } from \"next/navigation\";\nimport {\n  User as UserIcon,\n  School,\n  Upload,\n  Heart,\n  Download,\n  Trash2,\n  Plus,\n  Loader2,\n  ExternalLink,\n  UserCog,\n  ShieldCheck,\n  Key,\n  Check,\n  CreditCard,\n  Settings,\n  Clock,\n  CheckCircle2,\n  AlertCircle,\n  Users,\n} from \"lucide-react\";\nimport {\n  updateProfileAction,\n  updateSubscriptionPlanAction,\n} from \"@/actions/profile.actions\";\nimport { getMyFavoritePublishersAction } from \"@/actions/publisher.actions\";\nimport InspectorBadge from \"@/components/ui/InspectorBadge\";\nimport { useAppPreferences, type Locale } from \"@/context/AppPreferencesContext\";\nimport type { User, WorksheetWithRelations, ApiResponse } from \"@/types\";\n\ninterface ProfileWithCounts extends User {\n  _count: {\n    worksheets: number;\n    favorites: number;\n    downloads: number;\n  };\n}\n\ntype TabType =\n  | \"uploads\"\n  | \"favorites\"\n  | \"favorite_publishers\"\n  | \"downloads\"\n  | \"edit\"\n  | \"subscriptions\"\n  | \"settings\";\n\nfunction ProfileWorkspaceContent() {\n  const searchParams = useSearchParams();\n  const initialTabParam = searchParams?.get(\"tab\") as TabType | null;\n\n  const { locale, setLocale, theme, toggleTheme } = useAppPreferences();\n\n  const [profile, setProfile] = useState<ProfileWithCounts | null>(null);\n  const [activeTab, setActiveTab] = useState<TabType>(\n    initialTabParam &&\n      [\n        \"uploads\",\n        \"favorites\",\n        \"favorite_publishers\",\n        \"downloads\",\n        \"edit\",\n        \"subscriptions\",\n        \"settings\",\n      ].includes(initialTabParam)\n      ? initialTabParam\n      : \"uploads\"\n  );\n\n  useEffect(() => {\n    if (\n      initialTabParam &&\n      [\n        \"uploads\",\n        \"favorites\",\n        \"favorite_publishers\",\n        \"downloads\",\n        \"edit\",\n        \"subscriptions\",\n        \"settings\",\n      ].includes(initialTabParam)\n    ) {\n      setActiveTab(initialTabParam);\n    }\n  }, [initialTabParam]);\n\n  const [items, setItems] = useState<WorksheetWithRelations[]>([]);\n  const [favPublishers, setFavPublishers] = useState<any[]>([]);\n  const [loadingProfile, setLoadingProfile] = useState(true);\n  const [loadingItems, setLoadingItems] = useState(false);\n\n  // Edit Profile States (Admin-Approved Workflow)\n  const [editName, setEditName] = useState(\"\");\n  const [editSchool, setEditSchool] = useState(\"\");\n  const [editBio, setEditBio] = useState(\"\");\n  const [editLoading, setEditLoading] = useState(false);\n  const [editMessage, setEditMessage] = useState<string | null>(null);\n  const [editError, setEditError] = useState<string | null>(null);\n\n  const [planLoading, setPlanLoading] = useState<string | null>(null);\n\n  useEffect(() => {\n    async function loadProfile() {\n      try {\n        const res = await fetch(\"/api/auth/me\", { cache: \"no-store\" });\n        const json: ApiResponse<ProfileWithCounts> = await res.json();\n        if (json.success) {\n          setProfile(json.data);\n          const pending = json.data.pendingProfileData;\n          setEditName(pending?.name || json.data.name || \"\");\n          setEditSchool(\n            pending?.school !== undefined\n              ? pending.school || \"\"\n              : json.data.school || \"\"\n          );\n          setEditBio(\n            pending?.bio !== undefined\n              ? pending.bio || \"\"\n              : json.data.bio || \"\"\n          );\n        }\n      } finally {\n        setLoadingProfile(false);\n      }\n    }\n    loadProfile();\n  }, []);\n\n  useEffect(() => {\n    async function loadTabItems() {\n      if (\n        activeTab === \"edit\" ||\n        activeTab === \"subscriptions\" ||\n        activeTab === \"settings\"\n      ) {\n        return;\n      }\n\n      if (activeTab === \"favorite_publishers\") {\n        try {\n          setLoadingItems(true);\n          const pubs = await getMyFavoritePublishersAction();\n          setFavPublishers(pubs);\n        } finally {\n          setLoadingItems(false);\n        }\n        return;\n      }\n\n      try {\n        setLoadingItems(true);\n        const endpoint =\n          activeTab === \"uploads\"\n            ? \"/api/me/uploads\"\n            : activeTab === \"favorites\"\n            ? \"/api/me/favorites\"\n            : \"/api/me/downloads\";\n\n        const res = await fetch(endpoint);\n        const json: ApiResponse<WorksheetWithRelations[]> = await res.json();\n        if (json.success) {\n          setItems(json.data);\n        }\n      } finally {\n        setLoadingItems(false);\n      }\n    }\n    loadTabItems();\n  }, [activeTab]);\n\n  const handleArchiveWorksheet = async (id: string) => {\n    if (!confirm(\"هل أنت متأكد من أرشفة وإخفاء هذا المنشور؟\")) return;\n    const res = await fetch(`/api/worksheets/${id}`, { method: \"DELETE\" });\n    if (res.ok) {\n      setItems((prev) => prev.filter((item) => item.id !== id));\n    }\n  };\n\n  const handleSubmitProfileEditRequest = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setEditError(null);\n    setEditMessage(null);\n\n    if (!editName.trim()) {\n      setEditError(\"الاسم مطلوب ولا يمكن تركه فارغاً\");\n      return;\n    }\n\n    try {\n      setEditLoading(true);\n      const res = await updateProfileAction({\n        name: editName.trim(),\n        school: editSchool.trim() || undefined,\n        bio: editBio.trim() || undefined,\n      });\n\n      if (res.pendingApproval) {\n        setEditMessage(\n          \"تم إرسال طلب تعديل ملفك الشخصي بنجاح! سيظهر التعديل للعموم فور موافقة المشرف العام عليه.\"\n        );\n        setProfile((prev) =>\n          prev\n            ? {\n                ...prev,\n                profileEditStatus: \"PENDING\",\n                pendingProfileData: {\n                  name: editName.trim(),\n                  school: editSchool.trim(),\n                  bio: editBio.trim(),\n                },\n              }\n            : null\n        );\n      } else {\n        setEditMessage(\"تم تحديث بيانات الملف الشخصي بنجاح.\");\n        setProfile((prev) =>\n          prev\n            ? {\n                ...prev,\n                name: editName.trim(),\n                school: editSchool.trim(),\n                bio: editBio.trim(),\n              }\n            : null\n        );\n      }\n    } catch (err) {\n      setEditError(\n        err instanceof Error ? err.message : \"فشل إرسال طلب تحديث البيانات\"\n      );\n    } finally {\n      setEditLoading(false);\n    }\n  };\n\n  const handleSelectPlan = async (planCode: string) => {\n    try {\n      setPlanLoading(planCode);\n      await updateSubscriptionPlanAction(planCode);\n      setProfile((prev) =>\n        prev ? { ...prev, subscriptionPlan: planCode } : null\n      );\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"تعذر تحديث الاشتراك\");\n    } finally {\n      setPlanLoading(null);\n    }\n  };\n\n  if (loadingProfile) {\n    return (\n      <div className=\"min-h-[60vh] flex items-center justify-center\" dir=\"rtl\">\n        <Loader2 className=\"w-8 h-8 text-blue-600 animate-spin\" />\n      </div>\n    );\n  }\n\n  if (!profile) {\n    return (\n      <div className=\"max-w-xl mx-auto px-4 py-16 text-center\" dir=\"rtl\">\n        <p className=\"text-slate-700 font-bold mb-4\">\n          يرجى تسجيل الدخول لعرض مساحتك الشخصية في المسند\n        </p>\n        <Link\n          href=\"/login\"\n          className=\"px-5 py-2.5 rounded-xl bg-blue-600 text-white font-semibold text-sm\"\n        >\n          تسجيل الدخول\n        </Link>\n      </div>\n    );\n  }\n\n  return (\n    <main className=\"max-w-6xl mx-auto px-4 py-8\" dir=\"rtl\">\n      {/* Header Profile Card */}\n      <section className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-sm mb-6 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6\">\n        <div className=\"flex items-center gap-4\">\n          <div className=\"w-16 h-16 rounded-2xl bg-blue-600 text-white flex items-center justify-center font-black text-2xl shadow-sm\">\n            {profile.name.charAt(0)}\n          </div>\n          <div>\n            <div className=\"flex flex-wrap items-center gap-2.5\">\n              <h1 className=\"text-2xl font-bold text-slate-900 dark:text-white\">\n                {profile.name}\n              </h1>\n              <InspectorBadge role={profile.role} size=\"md\" />\n              {profile.role === \"ADMIN\" && (\n                <span className=\"inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-purple-100 text-purple-800\">\n                  <ShieldCheck className=\"w-3.5 h-3.5\" />\n                  مشرف عام\n                </span>\n              )}\n              <Link\n                href={`/publisher/${profile.id}`}\n                className=\"inline-flex items-center gap-1 px-3 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-blue-50 text-blue-600 text-xs font-bold transition\"\n              >\n                <ExternalLink className=\"w-3.5 h-3.5\" />\n                <span>ملفي العام كناشر</span>\n              </Link>\n            </div>\n            <p className=\"text-sm text-slate-500 mt-0.5\">{profile.email}</p>\n            {profile.school && (\n              <p className=\"text-xs text-slate-600 dark:text-slate-300 flex items-center gap-1 mt-1\">\n                <School className=\"w-3.5 h-3.5 text-blue-600\" />\n                <span>{profile.school}</span>\n              </p>\n            )}\n          </div>\n        </div>\n\n        <div className=\"flex items-center gap-4 self-stretch sm:self-auto justify-around bg-slate-50 dark:bg-slate-800 px-6 py-3 rounded-2xl border border-slate-100 dark:border-slate-700\">\n          <div className=\"text-center\">\n            <span className=\"block text-lg font-bold text-slate-900 dark:text-white\">\n              {profile._count?.worksheets ?? 0}\n            </span>\n            <span className=\"text-xs text-slate-500\">منشوراتي</span>\n          </div>\n          <div className=\"h-8 w-px bg-slate-200 dark:bg-slate-700\" />\n          <div className=\"text-center\">\n            <span className=\"block text-lg font-bold text-slate-900 dark:text-white\">\n              {profile.followersCount ?? 0}\n            </span>\n            <span className=\"text-xs text-slate-500\">المتابعون</span>\n          </div>\n          <div className=\"h-8 w-px bg-slate-200 dark:bg-slate-700\" />\n          <div className=\"text-center\">\n            <span className=\"block text-lg font-bold text-slate-900 dark:text-white\">\n              {profile._count?.favorites ?? 0}\n            </span>\n            <span className=\"text-xs text-slate-500\">المفضلة</span>\n          </div>\n        </div>\n      </section>\n\n      {/* Pending Profile Edit Notice Banner */}\n      {profile.profileEditStatus === \"PENDING\" && (\n        <div className=\"mb-6 p-4 rounded-2xl bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 flex items-center justify-between gap-4\">\n          <div className=\"flex items-center gap-3 text-amber-900 dark:text-amber-200 text-xs font-bold\">\n            <Clock className=\"w-5 h-5 text-amber-600 shrink-0\" />\n            <span>\n              لديك طلب تعديل بيانات شخصية قيد المراجعة حالياً بانتظار موافقة المشرف العام.\n            </span>\n          </div>\n          <button\n            type=\"button\"\n            onClick={() => setActiveTab(\"edit\")}\n            className=\"text-xs font-extrabold text-amber-800 underline shrink-0 cursor-pointer\"\n          >\n            معاينة الطلب\n          </button>\n        </div>\n      )}\n\n      {/* Navigation Tabs */}\n      <div className=\"flex flex-wrap items-center gap-1.5 border-b border-slate-200 dark:border-slate-800 mb-6 pb-2\">\n        <button\n          onClick={() => setActiveTab(\"uploads\")}\n          className={`px-4 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"uploads\"\n              ? \"bg-blue-600 text-white\"\n              : \"text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800\"\n          }`}\n        >\n          <Upload className=\"w-4 h-4\" />\n          <span>منشوراتي</span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"favorites\")}\n          className={`px-4 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"favorites\"\n              ? \"bg-blue-600 text-white\"\n              : \"text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800\"\n          }`}\n        >\n          <Heart className=\"w-4 h-4\" />\n          <span>المنشورات المفضلة</span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"favorite_publishers\")}\n          className={`px-4 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"favorite_publishers\"\n              ? \"bg-blue-600 text-white\"\n              : \"text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800\"\n          }`}\n        >\n          <Users className=\"w-4 h-4\" />\n          <span>الناشرون المفضلون</span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"downloads\")}\n          className={`px-4 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"downloads\"\n              ? \"bg-blue-600 text-white\"\n              : \"text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800\"\n          }`}\n        >\n          <Download className=\"w-4 h-4\" />\n          <span>سجل التحميلات</span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"edit\")}\n          className={`px-4 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"edit\"\n              ? \"bg-blue-600 text-white\"\n              : \"text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800\"\n          }`}\n        >\n          <UserCog className=\"w-4 h-4\" />\n          <span>تعديل الملف الشخصي</span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"subscriptions\")}\n          className={`px-4 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"subscriptions\"\n              ? \"bg-blue-600 text-white\"\n              : \"text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800\"\n          }`}\n        >\n          <CreditCard className=\"w-4 h-4\" />\n          <span>الاشتراكات</span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"settings\")}\n          className={`px-4 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"settings\"\n              ? \"bg-blue-600 text-white\"\n              : \"text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800\"\n          }`}\n        >\n          <Settings className=\"w-4 h-4\" />\n          <span>الإعدادات</span>\n        </button>\n      </div>\n\n      {/* TAB: EDIT PROFILE (Requires Admin Approval) */}\n      {activeTab === \"edit\" && (\n        <section className=\"max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-sm space-y-5\">\n          <div>\n            <h2 className=\"text-lg font-extrabold text-slate-900 dark:text-white\">\n              طلب تعديل بيانات الملف الشخصي\n            </h2>\n            <p className=\"text-xs text-slate-500 mt-1 leading-relaxed\">\n              حرصاً على موثوقية الناشرين في منصة المسند، تخضع تعديلات الاسم والمؤسسة والنبذة التعريفية لمراجعة وموافقة المشرف العام قبل نشرها للعموم.\n            </p>\n          </div>\n\n          {editMessage && (\n            <div className=\"p-4 rounded-2xl bg-emerald-50 border border-emerald-200 text-emerald-800 text-xs font-bold flex items-center gap-2\">\n              <CheckCircle2 className=\"w-4 h-4 shrink-0\" />\n              <span>{editMessage}</span>\n            </div>\n          )}\n\n          {editError && (\n            <div className=\"p-4 rounded-2xl bg-red-50 border border-red-200 text-red-700 text-xs font-bold flex items-center gap-2\">\n              <AlertCircle className=\"w-4 h-4 shrink-0\" />\n              <span>{editError}</span>\n            </div>\n          )}\n\n          <form onSubmit={handleSubmitProfileEditRequest} className=\"space-y-4\">\n            <div>\n              <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n                الاسم الكامل / اسم المؤسسة *\n              </label>\n              <input\n                type=\"text\"\n                required\n                value={editName}\n                onChange={(e) => setEditName(e.target.value)}\n                className=\"w-full px-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n\n            <div>\n              <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n                المؤسسة التربوية / المدرسة / الدائرة التفقدية\n              </label>\n              <input\n                type=\"text\"\n                value={editSchool}\n                onChange={(e) => setEditSchool(e.target.value)}\n                placeholder=\"مثال: المدرسة الابتدائية حي النور\"\n                className=\"w-full px-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n\n            <div>\n              <label className=\"block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5\">\n                النبذة التعريفية للناشر (تظهر للأعضاء في ملفك العام)\n              </label>\n              <textarea\n                rows={4}\n                value={editBio}\n                onChange={(e) => setEditBio(e.target.value)}\n                placeholder=\"اكتب نبذة عن خبرتك التربوية، المواد التي تدرسها، أو رسالتك التعليمية...\"\n                className=\"w-full px-4 py-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n\n            <button\n              type=\"submit\"\n              disabled={editLoading}\n              className=\"px-6 py-3 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold inline-flex items-center gap-2 transition cursor-pointer\"\n            >\n              {editLoading ? (\n                <Loader2 className=\"w-4 h-4 animate-spin\" />\n              ) : (\n                <Check className=\"w-4 h-4\" />\n              )}\n              <span>إرسال التعديلات لموافقة المشرف</span>\n            </button>\n          </form>\n        </section>\n      )}\n\n      {/* TAB: SUBSCRIPTIONS */}\n      {activeTab === \"subscriptions\" && (\n        <section className=\"space-y-6\">\n          <div className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-sm\">\n            <h2 className=\"text-xl font-black text-slate-900 dark:text-white\">\n              باقات الاشتراك في منصة المسند\n            </h2>\n            <p className=\"text-xs sm:text-sm text-slate-500 mt-1\">\n              باقتك الحالية:{\" \"}\n              <span className=\"font-extrabold text-blue-600\">\n                {profile.subscriptionPlan || \"STANDARD\"}\n              </span>\n            </p>\n\n            <div className=\"grid grid-cols-1 md:grid-cols-3 gap-6 mt-6\">\n              {[\n                {\n                  code: \"STANDARD\",\n                  title: \"باقة العضو الأساسي\",\n                  price: \"الباقة القياسية\",\n                  features: [\n                    \"تصفح ومعاينة المنشورات التربوية\",\n                    \"متابعة الناشرين وإضافتهم للمفضلة\",\n                    \"نشر الأنشطة مع تحديد جمهور النشر\",\n                  ],\n                },\n                {\n                  code: \"PRO_EDUCATOR\",\n                  title: \"باقة المعلم المتميز (Pro)\",\n                  price: \"اشتراك سنوي للمعلمين\",\n                  features: [\n                    \"تحميل غير محدود لكافة المذكرات والإصلاحات\",\n                    \"أولوية عرض المنشورات في ملف ناشر موثق\",\n                    \"إحصائيات تفصيلية لتحميلات وتفاعل الزملاء\",\n                  ],\n                },\n                {\n                  code: \"INSTITUTION_PLUS\",\n                  title: \"باقة المؤسسات والمدارس\",\n                  price: \"اشتراك مؤسساتي شامل\",\n                  features: [\n                    \"فضاء رسمي باسم المؤسسة التربوية\",\n                    \"نشر موجه لمعلمي وتلاميذ المؤسسة\",\n                    \"اعتماد وتوثيق مباشر مع المتفقدين التربويين\",\n                  ],\n                },\n              ].map((plan) => {\n                const isCurrent =\n                  (profile.subscriptionPlan || \"STANDARD\") === plan.code;\n                return (\n                  <div\n                    key={plan.code}\n                    className={`rounded-3xl border-2 p-6 flex flex-col justify-between gap-6 ${\n                      isCurrent\n                        ? \"border-blue-600 bg-blue-50/40 dark:bg-blue-950/30\"\n                        : \"border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900\"\n                    }`}\n                  >\n                    <div className=\"space-y-3\">\n                      <span className=\"px-3 py-1 rounded-full text-[11px] font-extrabold bg-blue-100 text-blue-800\">\n                        {plan.price}\n                      </span>\n                      <h3 className=\"text-lg font-black text-slate-900 dark:text-white\">\n                        {plan.title}\n                      </h3>\n                      <ul className=\"space-y-2 text-xs text-slate-600 dark:text-slate-300 pt-2\">\n                        {plan.features.map((f) => (\n                          <li key={f} className=\"flex items-center gap-2\">\n                            <Check className=\"w-4 h-4 text-emerald-600 shrink-0\" />\n                            <span>{f}</span>\n                          </li>\n                        ))}\n                      </ul>\n                    </div>\n\n                    <button\n                      type=\"button\"\n                      disabled={isCurrent || planLoading === plan.code}\n                      onClick={() => handleSelectPlan(plan.code)}\n                      className={`w-full py-2.5 rounded-xl text-xs font-bold transition cursor-pointer ${\n                        isCurrent\n                          ? \"bg-emerald-600 text-white cursor-default\"\n                          : \"bg-slate-900 hover:bg-blue-600 text-white\"\n                      }`}\n                    >\n                      {isCurrent ? \"الباقة المفعّلة حالياً ✓\" : \"ترقية / اختيار الباقة\"}\n                    </button>\n                  </div>\n                );\n              })}\n            </div>\n          </div>\n        </section>\n      )}\n\n      {/* TAB: SETTINGS */}\n      {activeTab === \"settings\" && (\n        <section className=\"max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-sm space-y-6\">\n          <h2 className=\"text-lg font-extrabold text-slate-900 dark:text-white\">\n            إعدادات الحساب والواجهة\n          </h2>\n\n          <div className=\"flex items-center justify-between py-3 border-b border-slate-100 dark:border-slate-800\">\n            <div>\n              <p className=\"text-sm font-bold text-slate-800 dark:text-white\">\n                مظهر المنصة (الوضع النهاري / الليلي)\n              </p>\n              <p className=\"text-xs text-slate-500\">\n                اختر المظهر المريح للقراءة والعمل\n              </p>\n            </div>\n            <button\n              type=\"button\"\n              onClick={toggleTheme}\n              className=\"px-4 py-2 rounded-xl bg-slate-100 dark:bg-slate-800 text-xs font-bold text-slate-800 dark:text-white cursor-pointer\"\n            >\n              {theme === \"light\" ? \"تفعيل الوضع الليلي 🌙\" : \"تفعيل الوضع النهاري ☀️\"}\n            </button>\n          </div>\n\n          <div className=\"flex items-center justify-between py-3 border-b border-slate-100 dark:border-slate-800\">\n            <div>\n              <p className=\"text-sm font-bold text-slate-800 dark:text-white\">\n                لغة الواجهة\n              </p>\n              <p className=\"text-xs text-slate-500\">\n                العربية، الفرنسية، أو الإنجليزية\n              </p>\n            </div>\n            <div className=\"flex items-center gap-2\">\n              {([\"ar\", \"fr\", \"en\"] as Locale[]).map((l) => (\n                <button\n                  key={l}\n                  type=\"button\"\n                  onClick={() => setLocale(l)}\n                  className={`px-3 py-1.5 rounded-lg text-xs font-bold cursor-pointer ${\n                    locale === l\n                      ? \"bg-blue-600 text-white\"\n                      : \"bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300\"\n                  }`}\n                >\n                  {l.toUpperCase()}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {profile.role !== \"INSPECTOR\" && (\n            <div className=\"flex items-center justify-between py-3\">\n              <div>\n                <p className=\"text-sm font-bold text-slate-800 dark:text-white\">\n                  توثيق حساب المتفقد التربوي\n                </p>\n                <p className=\"text-xs text-slate-500\">\n                  إدخال الكود السري الممنوح من الإدارة لتفعيل شارة المتفقد\n                </p>\n              </div>\n              <Link\n                href=\"/inspector/activate\"\n                className=\"px-4 py-2 rounded-xl bg-amber-500 hover:bg-amber-600 text-white text-xs font-bold inline-flex items-center gap-1.5\"\n              >\n                <Key className=\"w-3.5 h-3.5\" />\n                <span>تفعيل الكود</span>\n              </Link>\n            </div>\n          )}\n        </section>\n      )}\n\n      {/* TAB: FAVORITE PUBLISHERS */}\n      {activeTab === \"favorite_publishers\" && (\n        <section>\n          {loadingItems ? (\n            <div className=\"py-12 flex justify-center\">\n              <Loader2 className=\"w-7 h-7 text-blue-600 animate-spin\" />\n            </div>\n          ) : favPublishers.length === 0 ? (\n            <div className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-12 text-center\">\n              <p className=\"text-slate-600 font-medium mb-4\">\n                لم تقم بإضافة أي ناشر إلى قائمتك المفضلة بعد.\n              </p>\n              <Link\n                href=\"/browse\"\n                className=\"inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-blue-600 text-white text-sm font-bold\"\n              >\n                استكشف المنشورات والناشرين\n              </Link>\n            </div>\n          ) : (\n            <div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n              {favPublishers.map((pub) => (\n                <Link\n                  key={pub.id}\n                  href={`/publisher/${pub.id}`}\n                  className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm hover:border-blue-500 transition flex items-center justify-between gap-4\"\n                >\n                  <div className=\"flex items-center gap-3 min-w-0\">\n                    <div className=\"w-12 h-12 rounded-2xl bg-blue-100 text-blue-700 font-black flex items-center justify-center shrink-0\">\n                      {pub.name.charAt(0)}\n                    </div>\n                    <div className=\"min-w-0\">\n                      <div className=\"flex items-center gap-1.5 flex-wrap\">\n                        <p className=\"font-bold text-slate-900 dark:text-white text-sm truncate\">\n                          {pub.name}\n                        </p>\n                        <InspectorBadge role={pub.role} size=\"sm\" />\n                      </div>\n                      <p className=\"text-xs text-slate-500 truncate\">\n                        {pub.school || \"ناشر في منصة المسند\"}\n                      </p>\n                      <p className=\"text-[11px] text-blue-600 font-semibold mt-1\">\n                        {pub._count?.worksheets ?? 0} منشور •{\" \"}\n                        {pub.followersCount ?? 0} متابع\n                      </p>\n                    </div>\n                  </div>\n                  <ExternalLink className=\"w-4 h-4 text-slate-400 shrink-0\" />\n                </Link>\n              ))}\n            </div>\n          )}\n        </section>\n      )}\n\n      {/* TABS: UPLOADS / FAVORITES / DOWNLOADS */}\n      {(activeTab === \"uploads\" ||\n        activeTab === \"favorites\" ||\n        activeTab === \"downloads\") && (\n        <section>\n          {loadingItems ? (\n            <div className=\"py-12 flex justify-center\">\n              <Loader2 className=\"w-7 h-7 text-blue-600 animate-spin\" />\n            </div>\n          ) : items.length === 0 ? (\n            <div className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-12 text-center\">\n              <p className=\"text-slate-600 font-medium mb-4\">\n                لا توجد منشورات في هذا القسم حتى الآن.\n              </p>\n              <Link\n                href={activeTab === \"uploads\" ? \"/upload\" : \"/browse\"}\n                className=\"inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-blue-600 text-white text-sm font-bold\"\n              >\n                {activeTab === \"uploads\"\n                  ? \"انشر أول وثيقة لك\"\n                  : \"تصفح بنك المنشورات\"}\n              </Link>\n            </div>\n          ) : (\n            <div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n              {items.map((ws) => (\n                <div\n                  key={ws.id}\n                  className=\"bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm flex flex-col justify-between gap-4\"\n                >\n                  <div>\n                    <div className=\"flex items-center gap-2 mb-2\">\n                      <span\n                        className=\"px-2.5 py-0.5 rounded-full text-xs font-bold text-white\"\n                        style={{\n                          backgroundColor: ws.subject.color || \"#2563EB\",\n                        }}\n                      >\n                        {ws.subject.nameAr}\n                      </span>\n                      <span className=\"px-2.5 py-0.5 rounded-full text-xs bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-semibold\">\n                        {ws.grade.nameAr}\n                      </span>\n                    </div>\n                    <Link\n                      href={`/worksheet/${ws.id}`}\n                      className=\"font-bold text-slate-900 dark:text-white hover:text-blue-600 line-clamp-2\"\n                    >\n                      {ws.titleAr || ws.title}\n                    </Link>\n                  </div>\n\n                  <div className=\"flex items-center justify-between border-t border-slate-100 dark:border-slate-800 pt-3 text-xs text-slate-500\">\n                    <span>التحميلات: {ws.downloadCount}</span>\n                    <div className=\"flex items-center gap-2\">\n                      <Link\n                        href={`/worksheet/${ws.id}`}\n                        className=\"p-1.5 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-blue-50 text-slate-700 dark:text-slate-300 hover:text-blue-600\"\n                        title=\"معاينة\"\n                      >\n                        <ExternalLink className=\"w-4 h-4\" />\n                      </Link>\n                      {activeTab === \"uploads\" && (\n                        <button\n                          onClick={() => handleArchiveWorksheet(ws.id)}\n                          className=\"p-1.5 rounded-lg bg-red-50 hover:bg-red-100 text-red-600 cursor-pointer\"\n                          title=\"أرشفة وحذف\"\n                        >\n                          <Trash2 className=\"w-4 h-4\" />\n                        </button>\n                      )}\n                    </div>\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </section>\n      )}\n    </main>\n  );\n}\n\nexport default function TeacherProfilePage() {\n  return (\n    <Suspense\n      fallback={\n        <div className=\"min-h-[60vh] flex items-center justify-center\" dir=\"rtl\">\n          <Loader2 className=\"w-8 h-8 text-blue-600 animate-spin\" />\n        </div>\n      }\n    >\n      <ProfileWorkspaceContent />\n    </Suspense>\n  );\n}\n",
  "src/app/admin/dashboard/page.tsx": "\"use client\";\n\n/**\n * Admin Moderation Dashboard — Al-Musnad (المسند) v3.0\n *\n * Includes:\n * 1. Tab 1: مراجعة وإدارة المنشورات + زر اعتماد الصحة العلمية والبيداغوجية.\n * 2. Tab 2: إدارة الحسابات، الأدوار الـ 5، وتوليد أكواد المتفقدين.\n * 3. Tab 3: الموافقة على طلبات تعديل الملفات الشخصية (`approveProfileEditAdminAction` / `rejectProfileEditAdminAction`).\n */\n\nimport React, { useEffect, useState, useMemo } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ShieldCheck,\n  FileText,\n  Users,\n  Download,\n  CheckCircle2,\n  Clock,\n  Search,\n  ExternalLink,\n  Trash2,\n  UserCheck,\n  UserCog,\n  Key,\n  Copy,\n  Check,\n  Loader2,\n  AlertTriangle,\n  RefreshCw,\n  BadgeCheck,\n  XCircle,\n} from \"lucide-react\";\nimport {\n  getAdminDashboardData,\n  updateWorksheetStatusAdminAction,\n  deleteWorksheetAdminAction,\n  updateUserRoleAdminAction,\n  approveProfileEditAdminAction,\n  rejectProfileEditAdminAction,\n} from \"@/actions/admin.actions\";\nimport {\n  generateInspectorCodeAdminAction,\n  toggleWorksheetEndorsementAction,\n} from \"@/actions/inspector.actions\";\nimport type { Role, WorksheetStatus } from \"@/types\";\nimport InspectorBadge from \"@/components/ui/InspectorBadge\";\n\ntype AdminData = Awaited<ReturnType<typeof getAdminDashboardData>>;\ntype AdminTeacher = AdminData[\"teachers\"][number];\n\nexport default function AdminDashboardPage() {\n  const [data, setData] = useState<AdminData | null>(null);\n  const [loading, setLoading] = useState<boolean>(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const [activeTab, setActiveTab] = useState<\n    \"worksheets\" | \"teachers\" | \"profile_edits\"\n  >(\"worksheets\");\n\n  const [worksheetSearch, setWorksheetSearch] = useState<string>(\"\");\n  const [statusFilter, setStatusFilter] = useState<string>(\"ALL\");\n  const [actionLoadingId, setActionLoadingId] = useState<string | null>(null);\n\n  const [teacherSearch, setTeacherSearch] = useState<string>(\"\");\n  const [copiedCodeId, setCopiedCodeId] = useState<string | null>(null);\n\n  const handleCopyCode = async (teacherId: string, code: string) => {\n    try {\n      await navigator.clipboard.writeText(code);\n      setCopiedCodeId(teacherId);\n      setTimeout(() => setCopiedCodeId(null), 2000);\n    } catch {\n      alert(\"كود التفعيل: \" + code);\n    }\n  };\n\n  const loadDashboard = async () => {\n    try {\n      setLoading(true);\n      setError(null);\n      const result = await getAdminDashboardData();\n      setData(result);\n    } catch (err) {\n      setError(\n        err instanceof Error\n          ? err.message\n          : \"غير مصرح لك بالوصول إلى لوحة تحكم المشرفين\"\n      );\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  useEffect(() => {\n    loadDashboard();\n  }, []);\n\n  const handleStatusChange = async (\n    worksheetId: string,\n    newStatus: WorksheetStatus\n  ) => {\n    if (!data) return;\n    try {\n      setActionLoadingId(worksheetId);\n      await updateWorksheetStatusAdminAction(worksheetId, newStatus);\n      setData((prev) =>\n        prev\n          ? {\n              ...prev,\n              worksheets: prev.worksheets.map((ws) =>\n                ws.id === worksheetId ? { ...ws, status: newStatus } : ws\n              ),\n            }\n          : null\n      );\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"فشل تحديث حالة المنشور\");\n    } finally {\n      setActionLoadingId(null);\n    }\n  };\n\n  const handleToggleEndorsement = async (worksheetId: string) => {\n    try {\n      setActionLoadingId(worksheetId);\n      const res = await toggleWorksheetEndorsementAction(worksheetId);\n      setData((prev) =>\n        prev\n          ? {\n              ...prev,\n              worksheets: prev.worksheets.map((ws) =>\n                ws.id === worksheetId ? { ...ws, isEndorsed: res.isEndorsed } : ws\n              ),\n            }\n          : null\n      );\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"تعذر تحديث الاعتماد\");\n    } finally {\n      setActionLoadingId(null);\n    }\n  };\n\n  const handleDeleteWorksheet = async (worksheetId: string, title: string) => {\n    if (\n      !confirm(\n        `تحذير: هل أنت متأكد من الحذف النهائي للمنشور \"${title}\" وملف الـ PDF الخاص به؟`\n      )\n    ) {\n      return;\n    }\n\n    try {\n      setActionLoadingId(worksheetId);\n      await deleteWorksheetAdminAction(worksheetId);\n      setData((prev) =>\n        prev\n          ? {\n              ...prev,\n              worksheets: prev.worksheets.filter((ws) => ws.id !== worksheetId),\n            }\n          : null\n      );\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"فشل حذف المنشور\");\n    } finally {\n      setActionLoadingId(null);\n    }\n  };\n\n  const handleRoleChange = async (teacher: AdminTeacher, newRole: Role) => {\n    if (teacher.role === newRole) return;\n\n    const roleLabels: Record<Role, string> = {\n      INSTITUTION: \"مؤسسة تربوية (INSTITUTION)\",\n      INSPECTOR: \"متفقد تربوي (INSPECTOR)\",\n      TEACHER: \"معلم (TEACHER)\",\n      STUDENT: \"تلميذ (STUDENT)\",\n      ADMIN: \"مشرف نظام (ADMIN)\",\n    };\n\n    if (\n      !confirm(\n        `هل تريد تغيير رتبة \"${teacher.name}\" إلى ${roleLabels[newRole]}؟`\n      )\n    )\n      return;\n\n    try {\n      setActionLoadingId(teacher.id);\n      await updateUserRoleAdminAction(teacher.id, newRole);\n      setData((prev) =>\n        prev\n          ? {\n              ...prev,\n              teachers: prev.teachers.map((t) =>\n                t.id === teacher.id ? { ...t, role: newRole } : t\n              ),\n            }\n          : null\n      );\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"تعذر تحديث صلاحية المستخدم\");\n    } finally {\n      setActionLoadingId(null);\n    }\n  };\n\n  const handleGenerateInspectorCode = async (teacher: AdminTeacher) => {\n    if (!confirm(`هل تريد توليد كود تفعيل سري للمتفقد \"${teacher.name}\"؟`)) {\n      return;\n    }\n\n    try {\n      setActionLoadingId(teacher.id);\n      const res = await generateInspectorCodeAdminAction(teacher.id);\n      setData((prev) =>\n        prev\n          ? {\n              ...prev,\n              teachers: prev.teachers.map((t) =>\n                t.id === teacher.id\n                  ? {\n                      ...t,\n                      inspectorCode: res.inspectorCode,\n                      inspectorPending: true,\n                    }\n                  : t\n              ),\n            }\n          : null\n      );\n      alert(`تم توليد كود التفعيل بنجاح:\n\n${res.inspectorCode}`);\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"فشل توليد كود المتفقد\");\n    } finally {\n      setActionLoadingId(null);\n    }\n  };\n\n  const handleApproveProfileEdit = async (userId: string) => {\n    try {\n      setActionLoadingId(userId);\n      await approveProfileEditAdminAction(userId);\n      await loadDashboard();\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"تعذر اعتماد التعديل\");\n    } finally {\n      setActionLoadingId(null);\n    }\n  };\n\n  const handleRejectProfileEdit = async (userId: string) => {\n    try {\n      setActionLoadingId(userId);\n      await rejectProfileEditAdminAction(userId);\n      await loadDashboard();\n    } catch (err) {\n      alert(err instanceof Error ? err.message : \"تعذر رفض الطلب\");\n    } finally {\n      setActionLoadingId(null);\n    }\n  };\n\n  const filteredWorksheets = useMemo(() => {\n    if (!data) return [];\n    return data.worksheets.filter((ws) => {\n      const matchesStatus =\n        statusFilter === \"ALL\" || ws.status === statusFilter;\n      const term = worksheetSearch.trim().toLowerCase();\n      const matchesSearch =\n        !term ||\n        (ws.titleAr && ws.titleAr.toLowerCase().includes(term)) ||\n        ws.title.toLowerCase().includes(term) ||\n        ws.uploader.name.toLowerCase().includes(term);\n      return matchesStatus && matchesSearch;\n    });\n  }, [data, statusFilter, worksheetSearch]);\n\n  const filteredTeachers = useMemo(() => {\n    if (!data) return [];\n    const term = teacherSearch.trim().toLowerCase();\n    if (!term) return data.teachers;\n    return data.teachers.filter(\n      (t) =>\n        t.name.toLowerCase().includes(term) ||\n        t.email.toLowerCase().includes(term) ||\n        (t.school && t.school.toLowerCase().includes(term))\n    );\n  }, [data, teacherSearch]);\n\n  if (loading) {\n    return (\n      <div\n        className=\"min-h-[75vh] flex flex-col items-center justify-center gap-3\"\n        dir=\"rtl\"\n      >\n        <Loader2 className=\"w-10 h-10 text-blue-600 animate-spin\" />\n        <p className=\"text-slate-600 font-semibold\">\n          جاري تحميل لوحة إشراف منصة المسند...\n        </p>\n      </div>\n    );\n  }\n\n  if (error || !data) {\n    return (\n      <div className=\"max-w-xl mx-auto px-4 py-16 text-center\" dir=\"rtl\">\n        <div className=\"bg-red-50 border border-red-200 rounded-2xl p-8 flex flex-col items-center gap-4\">\n          <AlertTriangle className=\"w-12 h-12 text-red-600\" />\n          <h1 className=\"text-xl font-bold text-slate-900\">\n            وصول مقيد للمشرفين فقط\n          </h1>\n          <p className=\"text-sm text-red-700\">{error}</p>\n          <Link\n            href=\"/\"\n            className=\"px-5 py-2.5 rounded-xl bg-slate-900 text-white text-sm font-bold\"\n          >\n            العودة للصفحة الرئيسية\n          </Link>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <main className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8\" dir=\"rtl\">\n      <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"w-12 h-12 rounded-2xl bg-slate-900 text-white flex items-center justify-center\">\n            <ShieldCheck className=\"w-6 h-6 text-emerald-400\" />\n          </div>\n          <div>\n            <h1 className=\"text-2xl font-bold text-slate-900 dark:text-white\">\n              لوحة تحكم المشرف العام — المسند\n            </h1>\n            <p className=\"text-sm text-slate-500\">\n              إدارة المنشورات، اعتماد تعديلات الملفات الشخصية، وتوثيق المتفقدين\n            </p>\n          </div>\n        </div>\n\n        <button\n          onClick={loadDashboard}\n          className=\"inline-flex items-center gap-2 px-4 py-2.5 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 font-semibold text-sm transition cursor-pointer\"\n        >\n          <RefreshCw className=\"w-4 h-4\" />\n          <span>تحديث البيانات</span>\n        </button>\n      </div>\n\n      {/* KPI Cards */}\n      <section className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8\">\n        <div className=\"bg-white border border-slate-200 rounded-2xl p-5 shadow-sm\">\n          <div className=\"flex items-center justify-between mb-2\">\n            <span className=\"text-xs font-bold text-slate-500\">\n              إجمالي المنشورات\n            </span>\n            <FileText className=\"w-5 h-5 text-blue-600\" />\n          </div>\n          <p className=\"text-3xl font-extrabold text-slate-900\">\n            {data.stats.totalWorksheets}\n          </p>\n          <p className=\"text-xs text-amber-600 font-bold mt-1\">\n            معتمد من المتفقد: {data.stats.endorsedWorksheets}\n          </p>\n        </div>\n\n        <div className=\"bg-white border border-slate-200 rounded-2xl p-5 shadow-sm\">\n          <div className=\"flex items-center justify-between mb-2\">\n            <span className=\"text-xs font-bold text-slate-500\">\n              طلبات تعديل الملف الشخصي\n            </span>\n            <UserCog className=\"w-5 h-5 text-amber-600\" />\n          </div>\n          <p className=\"text-3xl font-extrabold text-slate-900\">\n            {data.stats.pendingProfileEditsCount}\n          </p>\n          <p className=\"text-xs text-slate-500 mt-1\">بانتظار موافقة المشرف</p>\n        </div>\n\n        <div className=\"bg-white border border-slate-200 rounded-2xl p-5 shadow-sm\">\n          <div className=\"flex items-center justify-between mb-2\">\n            <span className=\"text-xs font-bold text-slate-500\">\n              الأعضاء المسجلون\n            </span>\n            <Users className=\"w-5 h-5 text-indigo-600\" />\n          </div>\n          <p className=\"text-3xl font-extrabold text-slate-900\">\n            {data.stats.totalUsers}\n          </p>\n          <p className=\"text-xs text-slate-500 mt-1\">\n            مؤسسات، متفقدون، معلمون، وتلاميذ\n          </p>\n        </div>\n\n        <div className=\"bg-white border border-slate-200 rounded-2xl p-5 shadow-sm\">\n          <div className=\"flex items-center justify-between mb-2\">\n            <span className=\"text-xs font-bold text-slate-500\">\n              إجمالي التحميلات\n            </span>\n            <Download className=\"w-5 h-5 text-emerald-600\" />\n          </div>\n          <p className=\"text-3xl font-extrabold text-slate-900\">\n            {data.stats.totalDownloads}\n          </p>\n          <p className=\"text-xs text-slate-500 mt-1\">عمليات تنزيل ملفات PDF</p>\n        </div>\n      </section>\n\n      {/* Tabs */}\n      <div className=\"flex flex-wrap border-b border-slate-200 mb-6 gap-2\">\n        <button\n          onClick={() => setActiveTab(\"worksheets\")}\n          className={`px-5 py-3.5 font-bold text-sm border-b-2 flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"worksheets\"\n              ? \"border-blue-600 text-blue-600\"\n              : \"border-transparent text-slate-600 hover:text-slate-900\"\n          }`}\n        >\n          <FileText className=\"w-4 h-4\" />\n          <span>إدارة المنشورات والاعتماد ({data.worksheets.length})</span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"profile_edits\")}\n          className={`px-5 py-3.5 font-bold text-sm border-b-2 flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"profile_edits\"\n              ? \"border-blue-600 text-blue-600\"\n              : \"border-transparent text-slate-600 hover:text-slate-900\"\n          }`}\n        >\n          <UserCog className=\"w-4 h-4\" />\n          <span>\n            طلبات تعديل الملفات الشخصية ({data.pendingProfileUsers.length})\n          </span>\n        </button>\n\n        <button\n          onClick={() => setActiveTab(\"teachers\")}\n          className={`px-5 py-3.5 font-bold text-sm border-b-2 flex items-center gap-2 transition cursor-pointer ${\n            activeTab === \"teachers\"\n              ? \"border-blue-600 text-blue-600\"\n              : \"border-transparent text-slate-600 hover:text-slate-900\"\n          }`}\n        >\n          <Users className=\"w-4 h-4\" />\n          <span>إدارة الأعضاء والصلاحيات ({data.teachers.length})</span>\n        </button>\n      </div>\n\n      {/* TAB 1: WORKSHEETS */}\n      {activeTab === \"worksheets\" && (\n        <section className=\"bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden\">\n          <div className=\"p-4 sm:p-5 border-b border-slate-200 flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4 bg-slate-50\">\n            <div className=\"relative flex-1 max-w-md\">\n              <Search className=\"w-4 h-4 text-slate-400 absolute right-3.5 top-3.5\" />\n              <input\n                type=\"text\"\n                value={worksheetSearch}\n                onChange={(e) => setWorksheetSearch(e.target.value)}\n                placeholder=\"ابحث بعنوان المنشور أو اسم الناشر...\"\n                className=\"w-full pr-10 pl-4 py-2 rounded-xl border border-slate-300 bg-white text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n\n            <div className=\"flex items-center gap-2\">\n              {([\"ALL\", \"PUBLISHED\", \"DRAFT\", \"ARCHIVED\"] as const).map(\n                (st) => (\n                  <button\n                    key={st}\n                    onClick={() => setStatusFilter(st)}\n                    className={`px-3.5 py-2 rounded-xl text-xs font-bold transition cursor-pointer ${\n                      statusFilter === st\n                        ? \"bg-slate-900 text-white\"\n                        : \"bg-white border border-slate-200 text-slate-600 hover:bg-slate-100\"\n                    }`}\n                  >\n                    {st === \"ALL\" && \"الكل\"}\n                    {st === \"PUBLISHED\" && \"منشور\"}\n                    {st === \"DRAFT\" && \"مسودة\"}\n                    {st === \"ARCHIVED\" && \"مؤرشف\"}\n                  </button>\n                )\n              )}\n            </div>\n          </div>\n\n          <div className=\"overflow-x-auto\">\n            <table className=\"w-full text-right text-sm\">\n              <thead className=\"bg-slate-50 text-slate-600 text-xs font-bold border-b border-slate-200\">\n                <tr>\n                  <th className=\"py-3.5 px-4\">المنشور</th>\n                  <th className=\"py-3.5 px-4\">الصف / المادة</th>\n                  <th className=\"py-3.5 px-4\">الناشر</th>\n                  <th className=\"py-3.5 px-4\">الاعتماد البيداغوجي</th>\n                  <th className=\"py-3.5 px-4\">الحالة</th>\n                  <th className=\"py-3.5 px-4 text-left\">إجراءات</th>\n                </tr>\n              </thead>\n              <tbody className=\"divide-y divide-slate-100\">\n                {filteredWorksheets.map((ws) => (\n                  <tr key={ws.id} className=\"hover:bg-slate-50/80 transition\">\n                    <td className=\"py-3.5 px-4 max-w-xs\">\n                      <Link\n                        href={`/worksheet/${ws.id}`}\n                        className=\"font-bold text-slate-900 hover:text-blue-600 line-clamp-1\"\n                      >\n                        {ws.titleAr || ws.title}\n                      </Link>\n                      <span className=\"text-xs text-slate-400 block\">\n                        {ws.category.nameAr}\n                      </span>\n                    </td>\n\n                    <td className=\"py-3.5 px-4\">\n                      <div className=\"flex flex-wrap gap-1.5\">\n                        <span\n                          className=\"px-2.5 py-0.5 rounded-full text-xs font-bold text-white\"\n                          style={{\n                            backgroundColor: ws.subject.color || \"#2563EB\",\n                          }}\n                        >\n                          {ws.subject.nameAr}\n                        </span>\n                        <span className=\"px-2.5 py-0.5 rounded-full text-xs bg-slate-100 text-slate-700 font-semibold\">\n                          {ws.grade.nameAr}\n                        </span>\n                      </div>\n                    </td>\n\n                    <td className=\"py-3.5 px-4\">\n                      <Link\n                        href={`/publisher/${ws.uploader.id}`}\n                        className=\"font-semibold text-slate-800 hover:text-blue-600\"\n                      >\n                        {ws.uploader.name}\n                      </Link>\n                      <p className=\"text-xs text-slate-400\">\n                        {ws.uploader.school || ws.uploader.email}\n                      </p>\n                    </td>\n\n                    <td className=\"py-3.5 px-4\">\n                      <button\n                        type=\"button\"\n                        disabled={actionLoadingId === ws.id}\n                        onClick={() => handleToggleEndorsement(ws.id)}\n                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border transition cursor-pointer ${\n                          ws.isEndorsed\n                            ? \"bg-amber-100 text-amber-900 border-amber-300\"\n                            : \"bg-slate-100 text-slate-600 border-slate-200 hover:bg-amber-50\"\n                        }`}\n                      >\n                        <BadgeCheck className=\"w-3.5 h-3.5 text-amber-600\" />\n                        <span>\n                          {ws.isEndorsed ? \"معتمد (في الصدارة)\" : \"اعتماد المنشور\"}\n                        </span>\n                      </button>\n                    </td>\n\n                    <td className=\"py-3.5 px-4\">\n                      {ws.status === \"PUBLISHED\" ? (\n                        <span className=\"inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-50 text-emerald-700\">\n                          <CheckCircle2 className=\"w-3.5 h-3.5\" />\n                          منشور\n                        </span>\n                      ) : (\n                        <span className=\"inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold bg-slate-100 text-slate-600\">\n                          {ws.status}\n                        </span>\n                      )}\n                    </td>\n\n                    <td className=\"py-3.5 px-4\">\n                      <div className=\"flex items-center justify-end gap-2\">\n                        <Link\n                          href={`/worksheet/${ws.id}`}\n                          className=\"p-2 rounded-lg bg-slate-100 hover:bg-blue-50 text-slate-700 hover:text-blue-600\"\n                        >\n                          <ExternalLink className=\"w-4 h-4\" />\n                        </Link>\n                        {ws.status !== \"PUBLISHED\" && (\n                          <button\n                            disabled={actionLoadingId === ws.id}\n                            onClick={() =>\n                              handleStatusChange(ws.id, \"PUBLISHED\")\n                            }\n                            className=\"px-2.5 py-1.5 rounded-lg bg-emerald-600 text-white text-xs font-bold cursor-pointer\"\n                          >\n                            نشر\n                          </button>\n                        )}\n                        <button\n                          disabled={actionLoadingId === ws.id}\n                          onClick={() =>\n                            handleDeleteWorksheet(\n                              ws.id,\n                              ws.titleAr || ws.title\n                            )\n                          }\n                          className=\"p-2 rounded-lg bg-red-50 hover:bg-red-100 text-red-600 cursor-pointer\"\n                        >\n                          <Trash2 className=\"w-4 h-4\" />\n                        </button>\n                      </div>\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </section>\n      )}\n\n      {/* TAB 2: PENDING PROFILE EDITS */}\n      {activeTab === \"profile_edits\" && (\n        <section className=\"bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden\">\n          {data.pendingProfileUsers.length === 0 ? (\n            <div className=\"p-12 text-center text-slate-500 font-medium\">\n              لا توجد طلبات معلقة لتعديل الملفات الشخصية حالياً.\n            </div>\n          ) : (\n            <div className=\"divide-y divide-slate-100\">\n              {data.pendingProfileUsers.map((u) => {\n                const pending = (u.pendingProfileData || {}) as {\n                  name?: string;\n                  school?: string;\n                  bio?: string;\n                };\n                return (\n                  <div\n                    key={u.id}\n                    className=\"p-5 flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4\"\n                  >\n                    <div className=\"space-y-2\">\n                      <div className=\"flex items-center gap-2\">\n                        <span className=\"text-xs font-bold px-2.5 py-0.5 rounded-full bg-amber-100 text-amber-800\">\n                          طلب تعديل معلق\n                        </span>\n                        <span className=\"font-bold text-slate-900\">\n                          {u.email}\n                        </span>\n                        <InspectorBadge role={u.role} size=\"sm\" />\n                      </div>\n\n                      <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs bg-slate-50 p-3.5 rounded-xl border border-slate-200\">\n                        <div>\n                          <p className=\"font-bold text-slate-500 mb-1\">\n                            البيانات الحالية:\n                          </p>\n                          <p>\n                            <strong>الاسم:</strong> {u.name}\n                          </p>\n                          <p>\n                            <strong>المؤسسة:</strong> {u.school || \"—\"}\n                          </p>\n                          <p>\n                            <strong>النبذة:</strong> {u.bio || \"—\"}\n                          </p>\n                        </div>\n                        <div>\n                          <p className=\"font-bold text-blue-600 mb-1\">\n                            التعديل المطلوب اعتماده:\n                          </p>\n                          <p>\n                            <strong>الاسم الجديد:</strong>{\" \"}\n                            {pending.name || u.name}\n                          </p>\n                          <p>\n                            <strong>المؤسسة الجديدة:</strong>{\" \"}\n                            {pending.school ?? u.school ?? \"—\"}\n                          </p>\n                          <p>\n                            <strong>النبذة الجديدة:</strong>{\" \"}\n                            {pending.bio ?? u.bio ?? \"—\"}\n                          </p>\n                        </div>\n                      </div>\n                    </div>\n\n                    <div className=\"flex items-center gap-2 self-end lg:self-center\">\n                      <button\n                        type=\"button\"\n                        disabled={actionLoadingId === u.id}\n                        onClick={() => handleApproveProfileEdit(u.id)}\n                        className=\"px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold flex items-center gap-1.5 cursor-pointer\"\n                      >\n                        <Check className=\"w-4 h-4\" />\n                        <span>موافقة واعتماد</span>\n                      </button>\n\n                      <button\n                        type=\"button\"\n                        disabled={actionLoadingId === u.id}\n                        onClick={() => handleRejectProfileEdit(u.id)}\n                        className=\"px-4 py-2 rounded-xl bg-red-50 hover:bg-red-100 text-red-600 text-xs font-bold flex items-center gap-1.5 cursor-pointer\"\n                      >\n                        <XCircle className=\"w-4 h-4\" />\n                        <span>رفض</span>\n                      </button>\n                    </div>\n                  </div>\n                );\n              })}\n            </div>\n          )}\n        </section>\n      )}\n\n      {/* TAB 3: TEACHERS & USERS */}\n      {activeTab === \"teachers\" && (\n        <section className=\"bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden\">\n          <div className=\"p-4 sm:p-5 border-b border-slate-200 bg-slate-50 flex items-center justify-between\">\n            <div className=\"relative flex-1 max-w-md\">\n              <Search className=\"w-4 h-4 text-slate-400 absolute right-3.5 top-3.5\" />\n              <input\n                type=\"text\"\n                value={teacherSearch}\n                onChange={(e) => setTeacherSearch(e.target.value)}\n                placeholder=\"ابحث بالاسم، البريد الإلكتروني، أو المؤسسة...\"\n                className=\"w-full pr-10 pl-4 py-2 rounded-xl border border-slate-300 bg-white text-sm outline-none focus:border-blue-600\"\n              />\n            </div>\n          </div>\n\n          <div className=\"overflow-x-auto\">\n            <table className=\"w-full text-right text-sm\">\n              <thead className=\"bg-slate-50 text-slate-600 text-xs font-bold border-b border-slate-200\">\n                <tr>\n                  <th className=\"py-3.5 px-4\">العضو</th>\n                  <th className=\"py-3.5 px-4\">المؤسسة</th>\n                  <th className=\"py-3.5 px-4\">المنشورات</th>\n                  <th className=\"py-3.5 px-4\">الصلاحية</th>\n                  <th className=\"py-3.5 px-4 text-left\">إدارة الصلاحيات</th>\n                </tr>\n              </thead>\n              <tbody className=\"divide-y divide-slate-100\">\n                {filteredTeachers.map((teacher) => (\n                  <tr\n                    key={teacher.id}\n                    className=\"hover:bg-slate-50/80 transition\"\n                  >\n                    <td className=\"py-3.5 px-4\">\n                      <Link\n                        href={`/publisher/${teacher.id}`}\n                        className=\"font-bold text-slate-900 hover:text-blue-600\"\n                      >\n                        {teacher.name}\n                      </Link>\n                      <p className=\"text-xs text-slate-500\">{teacher.email}</p>\n                      {teacher.inspectorCode && (\n                        <div className=\"mt-1.5 flex items-center gap-1.5 text-xs text-amber-900 bg-amber-50 px-2.5 py-1 rounded-lg border border-amber-200 w-fit\">\n                          <Key className=\"w-3.5 h-3.5 text-amber-600\" />\n                          <code className=\"font-mono font-bold\">\n                            {teacher.inspectorCode}\n                          </code>\n                          <button\n                            type=\"button\"\n                            onClick={() =>\n                              handleCopyCode(teacher.id, teacher.inspectorCode!)\n                            }\n                            className=\"p-1 hover:bg-amber-100 rounded cursor-pointer\"\n                          >\n                            {copiedCodeId === teacher.id ? (\n                              <Check className=\"w-3.5 h-3.5 text-emerald-600\" />\n                            ) : (\n                              <Copy className=\"w-3.5 h-3.5\" />\n                            )}\n                          </button>\n                        </div>\n                      )}\n                    </td>\n\n                    <td className=\"py-3.5 px-4 text-slate-600\">\n                      {teacher.school || \"—\"}\n                    </td>\n\n                    <td className=\"py-3.5 px-4 font-bold text-slate-800\">\n                      {teacher._count.worksheets}\n                    </td>\n\n                    <td className=\"py-3.5 px-4\">\n                      <InspectorBadge role={teacher.role} size=\"md\" />\n                      {teacher.role === \"TEACHER\" && (\n                        <span className=\"inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-semibold bg-blue-50 text-blue-700\">\n                          <UserCheck className=\"w-3.5 h-3.5\" />\n                          معلم\n                        </span>\n                      )}\n                    </td>\n\n                    <td className=\"py-3.5 px-4 text-left\">\n                      {teacher.id === data.currentAdminId ? (\n                        <span className=\"text-xs text-slate-400\">حسابك الحالي</span>\n                      ) : (\n                        <div className=\"inline-flex items-center gap-2\">\n                          <select\n                            disabled={actionLoadingId === teacher.id}\n                            value={teacher.role}\n                            onChange={(e) =>\n                              handleRoleChange(teacher, e.target.value as Role)\n                            }\n                            className=\"text-xs font-bold px-3 py-1.5 rounded-xl border border-slate-300 bg-white cursor-pointer\"\n                          >\n                            <option value=\"INSTITUTION\">مؤسسة تربوية</option>\n                            <option value=\"INSPECTOR\">متفقد تربوي</option>\n                            <option value=\"TEACHER\">معلم</option>\n                            <option value=\"STUDENT\">تلميذ</option>\n                            <option value=\"ADMIN\">مشرف عام</option>\n                          </select>\n\n                          {teacher.role !== \"ADMIN\" && (\n                            <button\n                              type=\"button\"\n                              disabled={actionLoadingId === teacher.id}\n                              onClick={() =>\n                                handleGenerateInspectorCode(teacher)\n                              }\n                              className=\"px-2.5 py-1.5 rounded-xl border border-amber-300 bg-amber-50 hover:bg-amber-100 text-amber-800 text-xs font-bold flex items-center gap-1 cursor-pointer\"\n                            >\n                              <Key className=\"w-3.5 h-3.5 text-amber-600\" />\n                              <span>كود متفقد</span>\n                            </button>\n                          )}\n                        </div>\n                      )}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </section>\n      )}\n    </main>\n  );\n}\n",
  "src/app/page.tsx": "/**\n * Al-Musnad (المسند) — Main Landing & Discovery Page (v3.0)\n *\n * Route: /\n * - Rebranded to \"المسند\" (Al-Musnad) with zero \"free / مجاني\" claims.\n * - Fixes demo data schema fields (`slug`, `downloadCount`, `favoriteCount`, `isEndorsed`, `audience`).\n * - Passes current user's role (`viewerRole`) to `listWorksheets` so audience filtering and\n *   Inspector Endorsement ranking boost work out of the box.\n */\n\nimport React, { Suspense } from \"react\";\nimport Link from \"next/link\";\nimport { AlertCircle, Sparkles, BadgeCheck } from \"lucide-react\";\nimport { db } from \"@/lib/db\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { listWorksheets } from \"@/services/worksheet.service\";\nimport FilterBar from \"@/components/worksheets/FilterBar\";\nimport WorksheetCard from \"@/components/worksheets/WorksheetCard\";\nimport type { WorksheetSortOption } from \"@/types/api\";\n\ninterface HomePageProps {\n  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;\n}\n\nconst DEMO_GRADES = [\n  { id: \"g1\", name: \"Grade 1\", nameAr: \"الصف الأول\", slug: \"grade-1\", sortOrder: 1 },\n  { id: \"g2\", name: \"Grade 2\", nameAr: \"الصف الثاني\", slug: \"grade-2\", sortOrder: 2 },\n  { id: \"g3\", name: \"Grade 3\", nameAr: \"الصف الثالث\", slug: \"grade-3\", sortOrder: 3 },\n  { id: \"g4\", name: \"Grade 4\", nameAr: \"الصف الرابع\", slug: \"grade-4\", sortOrder: 4 },\n  { id: \"g5\", name: \"Grade 5\", nameAr: \"الصف الخامس\", slug: \"grade-5\", sortOrder: 5 },\n  { id: \"g6\", name: \"Grade 6\", nameAr: \"الصف السادس\", slug: \"grade-6\", sortOrder: 6 },\n];\n\nconst DEMO_SUBJECTS = [\n  { id: \"s1\", name: \"Arabic\", nameAr: \"اللغة العربية\", slug: \"arabic\", icon: \"BookOpen\", color: \"#2563EB\", sortOrder: 1 },\n  { id: \"s2\", name: \"Mathematics\", nameAr: \"الرياضيات\", slug: \"math\", icon: \"Calculator\", color: \"#DC2626\", sortOrder: 2 },\n  { id: \"s3\", name: \"Science\", nameAr: \"العلوم والإيقاظ العلمي\", slug: \"science\", icon: \"FlaskConical\", color: \"#16A34A\", sortOrder: 3 },\n  { id: \"s4\", name: \"Islamic Studies\", nameAr: \"التربية الإسلامية\", slug: \"islamic-studies\", icon: \"Compass\", color: \"#0D9488\", sortOrder: 4 },\n  { id: \"s5\", name: \"French\", nameAr: \"اللغة الفرنسية\", slug: \"french\", icon: \"Languages\", color: \"#4F46E5\", sortOrder: 5 },\n  { id: \"s6\", name: \"English\", nameAr: \"اللغة الإنجليزية\", slug: \"english\", icon: \"Globe\", color: \"#9333EA\", sortOrder: 6 },\n];\n\nconst DEMO_CATEGORIES = [\n  { id: \"c1\", name: \"Exercises\", nameAr: \"تمارين وأنشطة\", slug: \"worksheet\", sortOrder: 1 },\n  { id: \"c2\", name: \"Assessments\", nameAr: \"تقييمات واختبارات\", slug: \"exam\", sortOrder: 2 },\n  { id: \"c3\", name: \"Answer Keys\", nameAr: \"إصلاح اختبارات (للمعلمين)\", slug: \"answer-key\", sortOrder: 3 },\n  { id: \"c4\", name: \"Lesson Plans\", nameAr: \"مذكرات وتخطيط دروس\", slug: \"lesson-plan\", sortOrder: 4 },\n];\n\nconst DEMO_WORKSHEETS = [\n  {\n    id: \"demo-1\",\n    title: \"Arabic Alphabet Writing & Phonics Worksheet\",\n    titleAr: \"مذكرة وإصلاح تقييم القراءة والكتابة — معتمدة بيداغوجياً\",\n    description: \"Endorsed pedagogical worksheet\",\n    descriptionAr: \"وثيقة بيداغوجية معتمدة من المتفقد التربوي تتضمن شبكة التقييم وإصلاح التمارين الخاصة بالمعلمين.\",\n    fileUrl: \"/sample.pdf\",\n    fileName: \"arabic-grade1-endorsed.pdf\",\n    thumbnailUrl: null,\n    fileSize: 1024 * 750,\n    pageCount: 4,\n    status: \"PUBLISHED\" as const,\n    audience: \"TEACHERS_ONLY\" as const,\n    isEndorsed: true,\n    downloadCount: 185,\n    favoriteCount: 64,\n    ratingAvg: 5.0,\n    reviewCount: 15,\n    tags: [\"لغة عربية\", \"إصلاح\", \"الصف الأول\", \"معتمد\"],\n    createdAt: new Date(\"2026-10-27\"),\n    updatedAt: new Date(\"2026-10-27\"),\n    gradeId: \"g1\",\n    subjectId: \"s1\",\n    categoryId: \"c3\",\n    uploadedBy: \"u1\",\n    grade: DEMO_GRADES[0],\n    subject: DEMO_SUBJECTS[0],\n    category: DEMO_CATEGORIES[2],\n    uploader: {\n      id: \"u1\",\n      name: \"د. الهادي المنصوري\",\n      school: \"دائرة التفقد التربوي بقفصة\",\n      role: \"INSPECTOR\",\n      avatarUrl: null,\n    },\n  },\n  {\n    id: \"demo-2\",\n    title: \"Multiplication Tables and Mental Math Practice\",\n    titleAr: \"سلسلة تمارين الحساب الذهني والكسور العشرية\",\n    description: \"Math activities for Grade 5\",\n    descriptionAr: \"كراسة تمارين تطبيقية موجهة للمعلمين والتلاميذ لتثبيت مهارات الحساب الذهني وحل المسائل.\",\n    fileUrl: \"/sample.pdf\",\n    fileName: \"math-grade5.pdf\",\n    thumbnailUrl: null,\n    fileSize: 1024 * 1200,\n    pageCount: 5,\n    status: \"PUBLISHED\" as const,\n    audience: \"TEACHERS_AND_STUDENTS\" as const,\n    isEndorsed: true,\n    downloadCount: 230,\n    favoriteCount: 89,\n    ratingAvg: 4.9,\n    reviewCount: 19,\n    tags: [\"رياضيات\", \"تمارين\", \"الصف الخامس\"],\n    createdAt: new Date(\"2026-10-26\"),\n    updatedAt: new Date(\"2026-10-26\"),\n    gradeId: \"g5\",\n    subjectId: \"s2\",\n    categoryId: \"c1\",\n    uploadedBy: \"u2\",\n    grade: DEMO_GRADES[4],\n    subject: DEMO_SUBJECTS[1],\n    category: DEMO_CATEGORIES[0],\n    uploader: {\n      id: \"u2\",\n      name: \"المدرسة الابتدائية حي النور\",\n      school: \"مؤسسة تربوية معتمدة\",\n      role: \"INSTITUTION\",\n      avatarUrl: null,\n    },\n  },\n  {\n    id: \"demo-3\",\n    title: \"Plant Life Cycle and Photosynthesis\",\n    titleAr: \"دورة حياة النبات والإنبات — نشاط إيقاظ علمي\",\n    description: \"Science activity sheet for Grade 4\",\n    descriptionAr: \"ورقة عمل استكشافية تتضمن تجارب عملية ومخططاً توضيحياً لمراحل نمو النباتات الزهرية.\",\n    fileUrl: \"/sample.pdf\",\n    fileName: \"science-grade4.pdf\",\n    thumbnailUrl: null,\n    fileSize: 1024 * 950,\n    pageCount: 2,\n    status: \"PUBLISHED\" as const,\n    audience: \"TEACHERS_AND_STUDENTS\" as const,\n    isEndorsed: false,\n    downloadCount: 95,\n    favoriteCount: 24,\n    ratingAvg: 4.8,\n    reviewCount: 7,\n    tags: [\"علوم\", \"النبات\", \"الصف الرابع\"],\n    createdAt: new Date(\"2026-10-25\"),\n    updatedAt: new Date(\"2026-10-25\"),\n    gradeId: \"g4\",\n    subjectId: \"s3\",\n    categoryId: \"c1\",\n    uploadedBy: \"u3\",\n    grade: DEMO_GRADES[3],\n    subject: DEMO_SUBJECTS[2],\n    category: DEMO_CATEGORIES[0],\n    uploader: {\n      id: \"u3\",\n      name: \"عبد الرحمن السعدي\",\n      school: \"مدرسة الأمل الابتدائية\",\n      role: \"TEACHER\",\n      avatarUrl: null,\n    },\n  },\n];\n\nexport default async function HomePage(props: HomePageProps) {\n  const resolvedParams = await props.searchParams;\n\n  const page = Number(resolvedParams.page) || 1;\n  const search = typeof resolvedParams.search === \"string\" ? resolvedParams.search : undefined;\n  const grade = typeof resolvedParams.grade === \"string\" ? resolvedParams.grade : undefined;\n  const subject = typeof resolvedParams.subject === \"string\" ? resolvedParams.subject : undefined;\n  const category = typeof resolvedParams.category === \"string\" ? resolvedParams.category : undefined;\n  const sort = (typeof resolvedParams.sort === \"string\" ? resolvedParams.sort : \"newest\") as WorksheetSortOption;\n\n  let grades: any[] = [];\n  let subjects: any[] = [];\n  let categories: any[] = [];\n  let worksheets: any[] = [];\n  let meta = { total: 0, page, limit: 12, totalPages: 1 };\n  let isDbConnected = true;\n\n  try {\n    let viewerRole: string | null = null;\n    try {\n      const supabase = await createSupabaseServerClient();\n      const {\n        data: { user },\n      } = await supabase.auth.getUser();\n      if (user) {\n        const dbUser = await db.user.findUnique({\n          where: { id: user.id },\n          select: { role: true },\n        });\n        viewerRole = dbUser?.role || null;\n      }\n    } catch {\n      // Guest\n    }\n\n    const [fetchedGrades, fetchedSubjects, fetchedCategories, fetchedWorksheets] =\n      await Promise.all([\n        db.grade.findMany({ orderBy: { sortOrder: \"asc\" } }),\n        db.subject.findMany({ orderBy: { sortOrder: \"asc\" } }),\n        db.category.findMany({ orderBy: { sortOrder: \"asc\" } }),\n        listWorksheets(\n          {\n            page,\n            limit: 12,\n            search,\n            grade,\n            subject,\n            category,\n            sort,\n          },\n          viewerRole\n        ),\n      ]);\n\n    grades = fetchedGrades;\n    subjects = fetchedSubjects;\n    categories = fetchedCategories;\n    worksheets = fetchedWorksheets.data;\n    meta = fetchedWorksheets.meta;\n  } catch {\n    isDbConnected = false;\n    grades = DEMO_GRADES;\n    subjects = DEMO_SUBJECTS;\n    categories = DEMO_CATEGORIES;\n    worksheets = DEMO_WORKSHEETS;\n    meta = { total: DEMO_WORKSHEETS.length, page: 1, limit: 12, totalPages: 1 };\n  }\n\n  const buildPageUrl = (targetPage: number) => {\n    const params = new URLSearchParams();\n    if (search) params.set(\"search\", search);\n    if (grade) params.set(\"grade\", grade);\n    if (subject) params.set(\"subject\", subject);\n    if (category) params.set(\"category\", category);\n    if (sort && sort !== \"newest\") params.set(\"sort\", sort);\n    params.set(\"page\", String(targetPage));\n    return `/?${params.toString()}`;\n  };\n\n  return (\n    <div className=\"space-y-10 pb-16\">\n      {!isDbConnected && (\n        <div className=\"bg-amber-50 border-b border-amber-200 px-4 py-2.5 text-xs text-amber-900 flex flex-wrap items-center justify-center gap-2\" dir=\"rtl\">\n          <AlertCircle className=\"w-4 h-4 text-amber-600 shrink-0\" />\n          <span>\n            <strong>الوضع التجريبي لمنصة المسند:</strong> الموقع يعرض حالياً بيانات المعاينة المحلية. لربط قاعدة البيانات السحابية، أدخل بيانات Supabase في ملف <code>.env.local</code>.\n          </span>\n        </div>\n      )}\n\n      {/* Hero Section: المسند */}\n      <section className=\"relative overflow-hidden bg-gradient-to-b from-blue-700 via-indigo-800 to-slate-900 text-white pt-16 pb-20 px-4 sm:px-6 lg:px-8\">\n        <div className=\"absolute top-0 right-1/4 w-96 h-96 bg-blue-500/20 rounded-full blur-3xl pointer-events-none\" />\n        <div className=\"absolute bottom-0 left-1/4 w-80 h-80 bg-indigo-500/20 rounded-full blur-3xl pointer-events-none\" />\n\n        <div className=\"relative max-w-5xl mx-auto text-center space-y-6\">\n          <div className=\"inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/10 backdrop-blur-md border border-white/20 text-xs font-bold text-amber-200 shadow-sm\">\n            <Sparkles className=\"w-3.5 h-3.5 text-amber-300\" />\n            <span>منصة المسند التربوية والبيداغوجية المعتمدة</span>\n          </div>\n\n          <h1 className=\"text-3xl sm:text-5xl lg:text-6xl font-black tracking-tight leading-tight\">\n            المرجع التربوي الموثوق للمؤسسات، <br className=\"hidden sm:inline\" />\n            <span className=\"text-amber-300\">المتفقدين، المعلمين، والتلاميذ</span>\n          </h1>\n\n          <p className=\"max-w-2xl mx-auto text-blue-100 text-base sm:text-lg leading-relaxed font-normal\">\n            فضاء تربوي متكامل يجمع المذكرات البيداغوجية، التقييمات، وإصلاح الاختبارات مع نظام الاعتماد العلمي والبيداغوجي المباشر من المتفقدين التربويين وتحديد دقيق لجمهور كل منشور.\n          </p>\n\n          <div className=\"pt-2 flex flex-wrap justify-center items-center gap-3\">\n            <a\n              href=\"#catalog\"\n              className=\"px-6 py-3.5 bg-amber-400 hover:bg-amber-300 text-slate-900 font-extrabold text-sm rounded-xl shadow-lg shadow-amber-400/20 transition transform hover:-translate-y-0.5\"\n            >\n              استكشف المنشورات المعتمدة ↓\n            </a>\n            <Link\n              href=\"/upload\"\n              className=\"px-6 py-3.5 bg-white/10 hover:bg-white/20 text-white font-bold text-sm rounded-xl border border-white/30 backdrop-blur-sm transition\"\n            >\n              + نشر وثيقة أو نشاط جديد\n            </Link>\n          </div>\n\n          <div className=\"pt-8 grid grid-cols-2 sm:grid-cols-4 gap-4 max-w-3xl mx-auto border-t border-white/10 text-xs text-blue-200\">\n            <div>\n              <div className=\"text-xl font-extrabold text-white\">4 فضاءات مخصصة</div>\n              <div className=\"mt-0.5\">مؤسسة، متفقد، معلم، تلميذ</div>\n            </div>\n            <div>\n              <div className=\"text-xl font-extrabold text-white\">اعتماد المتفقد</div>\n              <div className=\"mt-0.5\">يرفع ترتيب المنشور في المادة</div>\n            </div>\n            <div>\n              <div className=\"text-xl font-extrabold text-white\">تخصيص الجمهور</div>\n              <div className=\"mt-0.5\">إصلاح للمعلمين وتمارين للتلاميذ</div>\n            </div>\n            <div>\n              <div className=\"text-xl font-extrabold text-white\">معاينة فورية</div>\n              <div className=\"mt-0.5\">عارض PDF مدمج عالي الدقة</div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* Catalog & Filter Area */}\n      <section id=\"catalog\" className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-8 scroll-mt-24\">\n        <div className=\"space-y-4\">\n          <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-4\">\n            <div>\n              <h2 className=\"text-2xl font-bold text-slate-900 dark:text-white\">\n                بنك المنشورات والوثائق البيداغوجية\n              </h2>\n              <p className=\"text-slate-500 text-sm mt-0.5\">\n                تظهر المنشورات المعتمدة علمياً وبيداغوجياً من المتفقدين في صدارة الترتيب تلقائياً • إجمالي النتائج:{\" \"}\n                <span className=\"font-bold text-blue-600\">{meta.total}</span>\n              </p>\n            </div>\n          </div>\n\n          <Suspense fallback={<div className=\"h-20 bg-slate-100 rounded-2xl animate-pulse\" />}>\n            <FilterBar grades={grades} subjects={subjects} categories={categories} />\n          </Suspense>\n        </div>\n\n        {worksheets.length > 0 ? (\n          <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6\">\n            {worksheets.map((worksheet) => (\n              <WorksheetCard key={worksheet.id} worksheet={worksheet} />\n            ))}\n          </div>\n        ) : (\n          <div className=\"text-center py-16 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-dashed border-slate-300 dark:border-slate-800\">\n            <p className=\"text-slate-500 font-semibold text-base\">\n              لا توجد منشورات مطابقة لخيارات البحث المحددة\n            </p>\n            <Link\n              href=\"/\"\n              className=\"inline-block mt-4 px-4 py-2 text-xs font-bold text-blue-600 bg-blue-50 rounded-lg transition\"\n            >\n              إعادة ضبط الفلاتر\n            </Link>\n          </div>\n        )}\n\n        {meta.totalPages > 1 && (\n          <div className=\"flex items-center justify-center gap-2 pt-8 border-t border-slate-200 dark:border-slate-800\">\n            {page > 1 && (\n              <Link\n                href={buildPageUrl(page - 1)}\n                className=\"px-4 py-2 text-xs font-bold rounded-lg border border-slate-300 text-slate-700 hover:bg-slate-100 transition\"\n              >\n                الصفحة السابقة\n              </Link>\n            )}\n            {page < meta.totalPages && (\n              <Link\n                href={buildPageUrl(page + 1)}\n                className=\"px-4 py-2 text-xs font-bold rounded-lg border border-slate-300 text-slate-700 hover:bg-slate-100 transition\"\n              >\n                الصفحة التالية\n              </Link>\n            )}\n          </div>\n        )}\n      </section>\n    </div>\n  );\n}\n",
  "src/app/(main)/worksheet/[id]/page.tsx": "/**\n * Worksheet Detail View Route (Server Component) — Al-Musnad (المسند) v3.0\n */\n\nimport React from \"react\";\nimport type { Metadata } from \"next\";\nimport { notFound } from \"next/navigation\";\nimport { getWorksheetById } from \"@/services/worksheet.service\";\nimport { createSupabaseServerClient } from \"@/lib/supabase/server\";\nimport { db } from \"@/lib/db\";\nimport WorksheetDetailClient from \"@/components/worksheets/WorksheetDetailClient\";\nimport type { WorksheetWithRelations } from \"@/types\";\n\ninterface WorksheetPageProps {\n  params: Promise<{ id: string }>;\n}\n\nexport async function generateMetadata(props: WorksheetPageProps): Promise<Metadata> {\n  const { id } = await props.params;\n\n  try {\n    const worksheet = await getWorksheetById(id, \"ADMIN\");\n    const title = worksheet.titleAr || worksheet.title;\n    const gradeName = worksheet.grade?.nameAr || worksheet.grade?.name || \"\";\n    const subjectName = worksheet.subject?.nameAr || worksheet.subject?.name || \"\";\n    const description =\n      worksheet.descriptionAr ||\n      worksheet.description ||\n      `وثيقة ${title} في مادة ${subjectName} للصف ${gradeName} عبر منصة المسند التربوية`;\n\n    return {\n      title: `${title} | المسند`,\n      description,\n    };\n  } catch {\n    return {\n      title: \"المنشور غير موجود | المسند\",\n      description: \"تعذر العثور على الوثيقة التربوية المطلوبة.\",\n    };\n  }\n}\n\nexport default async function WorksheetDetailPage(props: WorksheetPageProps) {\n  const { id } = await props.params;\n\n  let viewerRole: string | null = null;\n  let viewerUserId: string | null = null;\n\n  try {\n    const supabase = await createSupabaseServerClient();\n    const {\n      data: { user },\n    } = await supabase.auth.getUser();\n    if (user) {\n      viewerUserId = user.id;\n      const dbUser = await db.user.findUnique({\n        where: { id: user.id },\n        select: { role: true },\n      });\n      viewerRole = dbUser?.role || null;\n    }\n  } catch {\n    // Guest\n  }\n\n  let worksheet: (WorksheetWithRelations & { previewUrl?: string }) | null = null;\n  try {\n    worksheet = (await getWorksheetById(\n      id,\n      viewerRole,\n      viewerUserId\n    )) as WorksheetWithRelations & { previewUrl?: string };\n  } catch {\n    notFound();\n  }\n\n  if (!worksheet) {\n    notFound();\n  }\n\n  return <WorksheetDetailClient initialWorksheet={worksheet} />;\n}\n"
};

const rootDir = process.cwd();
console.log("🏛️ Applying Al-Musnad (v3.0) Upgrades in:", rootDir);

let writtenCount = 0;
for (const [relPath, content] of Object.entries(files)) {
  const fullPath = path.join(rootDir, relPath);
  const dir = path.dirname(fullPath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(fullPath, content, "utf-8");
  console.log("  ✓ Updated:", relPath);
  writtenCount++;
}

console.log(`\n🎉 Successfully applied ${writtenCount} Al-Musnad v3.0 core files!\n`);
console.log("Next steps:");
